const std = @import("std");
const core = @import("core");
const ast = core.ast;
const token = core.token;
const types = core.types;

const AnalyzeError = @import("analyzer.zig").AnalyzeError;
const Evaluator = @import("evaluator.zig").Evaluator;
const Failure = core.Failure;
const Integer = core.Integer;
const Value = core.Value;

const followPointer = types.followPointer;
const isZeroSized = types.isZeroSized;

const instance_limit = 512;

const top_level_signature: ast.FunctionSignature = .{
    .name = "",
    .parameters = &.{},
    .return_type = .{ .kind = .undefined, .location = .{ .row = 0, .column = 0 }, .denoted = .void },
};

pub const TypeChecker = struct {
    arena: *std.heap.ArenaAllocator,
    program: ast.Program,
    module_index: usize = 0,
    constraints: []const ast.Constraint = &.{},
    evaluator: Evaluator,
    resolver: ?Resolver = null,
    quiet_operations: usize = 0,
    compile_time: bool = false,
    compile_time_function: bool = false,
    return_type: ?types.Type = null,
    signature: ?*const ast.FunctionSignature = null,
    production: ?*Production = null,
    inferring: ?*types.Enum = null,
    inferring_functions: std.ArrayList(*ast.FunctionDefinition) = .empty,
    rechecking: bool = false,
    allocator_type: ?types.Type = null,
    allocator_root: bool = false,
    context_allocator: ?ContextAllocator = null,
    need_reason: ?ast.NeedReason = null,
    allocator_calls: std.ArrayList(AllocatorCall) = .empty,
    trace: []const InstanceCall = &.{},
    checking: bool = false,
    need_calls: std.ArrayList(NeedCall) = .empty,
    undecided_calls: std.ArrayList(UndecidedCall) = .empty,
    need_undecided: bool = false,
    early_call: bool = false,
    allocator_instances: std.ArrayList(AllocatorInstance) = .empty,
    groups: std.ArrayList(Grouped) = .empty,
    empty_error_set: ?*const types.Enum = null,
    deferring: bool = false,
    current_function: ?ast.Resolution.Function = null,
    move_frames: std.ArrayList(MoveFrame) = .empty,
    move_loops: std.ArrayList(MoveLoop) = .empty,
    move_deferring: bool = false,
    move_skipped: ?*std.ArrayList(*const ast.Statement) = null,
    own_trusted: bool = false,
    skipped_defers: std.ArrayList(ast.SkippedDefer) = .empty,
    failed_function: ?ast.Resolution.Function = null,
    exact_numbers: bool = false,
    instances: std.ArrayList(Instance) = .empty,
    created: std.ArrayList(ast.Resolution.Function) = .empty,
    instance_depth: usize = 0,
    failure: ?Failure = null,

    pub fn init(arena: *std.heap.ArenaAllocator, program: ast.Program) TypeChecker {
        return .{ .arena = arena, .program = program, .evaluator = Evaluator.init(arena, program) };
    }

    pub fn check(self: *TypeChecker) TypeError!void {
        self.checking = true;
        for (self.program.types.entries.items) |value_type| {
            switch (value_type) {
                .@"struct" => |struct_type| try self.checkFieldDefaults(struct_type),
                .@"enum" => {},
                .number, .boolean, .void, .type, .array, .slice, .pointer, .optional, .result, .tuple, .function, .variable, .application => {
                    unreachable;
                },
            }
        }
        for (self.program.modules, 0..) |module, index| {
            self.module_index = index;
            for (module.declarations, 0..) |declaration, declaration_index| {
                switch (declaration.kind) {
                    .function_definition => |function| {
                        if (function.default_of == null and !ast.isGeneric(function.signature) and !function.pattern) {
                            try self.prepareWithoutAllocator(.{ .module = index, .declaration = declaration_index });
                        } else if (function.default_of == null and !function.pattern and self.resolver != null) {
                            const resolver = &self.resolver.?;
                            const resolution: ast.Resolution.Function = .{ .module = index, .declaration = declaration_index };
                            try self.prepareCheckCopy(try resolver.createCheckCopy(resolver.context, resolution));
                        }
                    },
                    .typeclass_definition => |definition| {
                        const typeclass: ast.Resolution.Typeclass = .{ .module = index, .declaration = declaration_index };
                        for (definition.functions) |signature| try self.checkParameterDefaults(signature.parameters);
                        for (definition.functions, definition.defaults) |signature, default| {
                            const written = default orelse continue;
                            if (ast.isGeneric(signature)) {
                                const resolver = self.resolver orelse continue;
                                const position = findTypeclassFunction(definition, signature.name).?;
                                try self.prepareCheckCopy(try resolver.createDefaultCheckCopy(resolver.context, typeclass, position));
                                continue;
                            }
                            const function: ast.FunctionDefinition = .{ .signature = signature, .body = written.body };
                            self.inferring = signature.error_set;
                            defer self.inferring = null;
                            self.checkDefault(function, typeclass, try self.buildOwnArguments(definition)) catch |check_error| {
                                if (check_error != error.NeedsAllocator) return check_error;
                                self.failure = null;
                                self.failed_function = null;
                            };
                        }
                    },
                    .function_declaration => |signature| {
                        try self.checkExternalFunction(signature, declaration.location);
                    },
                    .constant_declaration => |constant| {
                        if (ast.isAlias(constant)) continue;
                        const resolution: ast.Resolution.Constant = .{ .module = index, .declaration = declaration_index };
                        _ = try self.checkConstant(resolution);
                        _ = try self.evaluateConstant(resolution);
                    },
                    .instance_declaration => try self.checkInstanceDefaults(module, declaration_index),
                    .struct_definition, .enum_definition, .import => {},
                }
            }
        }
        for (self.program.modules, 0..) |module, index| {
            for (module.declarations, 0..) |declaration, declaration_index| {
                if (declaration.kind != .function_definition) continue;
                const function = declaration.kind.function_definition;
                if (function.default_of == null or function.pattern or ast.isGeneric(function.signature)) continue;
                try self.prepareWithoutAllocator(.{ .module = index, .declaration = declaration_index });
            }
        }
        var created_index: usize = 0;
        while (created_index < self.created.items.len) : (created_index += 1) {
            const function = self.created.items[created_index];
            const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
            if (!ast.isGeneric(declaration.kind.function_definition.signature)) {
                if (declaration.kind.function_definition.allocator != null) {
                    try self.prepareFunction(function);
                } else {
                    try self.prepareWithoutAllocator(function);
                }
                continue;
            }
            const resolver = self.resolver orelse continue;
            try self.prepareCheckCopy(try resolver.createCheckCopy(resolver.context, function));
        }
        try self.finishNeeds();
        try self.checkInlineRecursion();
        try self.checkOwnership();
    }

    fn prepareCheckCopy(self: *TypeChecker, function: ast.Resolution.Function) TypeError!void {
        self.prepareFunction(function) catch |check_error| {
            if (check_error != error.NeedsAllocator) return check_error;
            self.failure = null;
            self.failed_function = null;
        };
    }

    fn prepareWithoutAllocator(self: *TypeChecker, function: ast.Resolution.Function) TypeError!void {
        const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
        if (declaration.kind != .function_definition) return;
        const definition = &declaration.kind.function_definition;
        if (definition.allocator != null or definition.allocator_root or definition.pattern or ast.isGeneric(definition.signature)) return;
        if (ast.isMain(definition.signature)) {
            definition.allocator_root = true;
            definition.need = .no;
            return self.prepareFunction(function);
        }
        if (definition.need == .yes or definition.need == .running or definition.signature.progress == .running) return;
        if (definition.need == .no and definition.check_progress != .pending) return;
        definition.need = .running;
        self.prepareFunction(function) catch |check_error| {
            if (check_error != error.NeedsAllocator) return check_error;
            self.failure = null;
            self.failed_function = null;
            self.markNeed(definition, self.need_reason);
            self.need_reason = null;
            return;
        };
        if (definition.need == .running) definition.need = .no;
    }

    fn markNeed(_: *const TypeChecker, definition: *ast.FunctionDefinition, reason: ?ast.NeedReason) void {
        definition.need = .yes;
        definition.need_reason = reason;
        definition.check_only = true;
        definition.check_progress = .done;
    }

    fn needsAllocator(self: *TypeChecker, function: ast.Resolution.Function) TypeError!bool {
        const allocator = self.arena.allocator();
        var visited: std.ArrayList(ast.Resolution.Function) = .empty;
        var waiting: std.ArrayList(ast.Resolution.Function) = .empty;
        var undecided = false;
        try waiting.append(allocator, function);
        while (waiting.pop()) |current| {
            if (containsFunction(visited.items, current)) continue;
            try visited.append(allocator, current);
            try self.prepareWithoutAllocator(current);
            if (self.isNeedRunning(current)) undecided = true;
            for (self.need_calls.items) |need_call| {
                if (std.meta.eql(need_call.caller, current)) try waiting.append(allocator, need_call.callee);
            }
        }
        self.spreadNeeds(visited.items);
        try self.reviseUndecidedCalls();
        self.need_undecided = undecided;
        return self.hasNeed(function);
    }

    fn isNeedRunning(self: *const TypeChecker, function: ast.Resolution.Function) bool {
        const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
        return declaration.kind == .function_definition and declaration.kind.function_definition.need == .running;
    }

    fn reviseUndecidedCalls(self: *TypeChecker) TypeError!void {
        var index: usize = 0;
        while (index < self.undecided_calls.items.len) {
            const undecided = self.undecided_calls.items[index];
            const definition = &ast.findDeclaration(self.program.modules[undecided.caller.module], undecided.caller.declaration).kind.function_definition;
            if (!self.hasNeed(undecided.callee) or definition.check_progress == .running) {
                index += 1;
                continue;
            }
            _ = self.undecided_calls.swapRemove(index);
            if (definition.need == .yes) continue;
            try self.reviseCaller(undecided.caller, definition);
            index = 0;
        }
    }

    fn reviseCaller(self: *TypeChecker, function: ast.Resolution.Function, definition: *ast.FunctionDefinition) TypeError!void {
        const caller_rechecking = self.rechecking;
        defer self.rechecking = caller_rechecking;
        self.rechecking = true;
        definition.check_progress = .pending;
        if (definition.signature.error_set) |error_set| {
            const value_type = ast.extractType(definition.signature.return_type).result.value;
            const result = try self.program.types.addResult(self.arena.allocator(), error_set, value_type);
            definition.signature.return_type.denoted = .{ .result = result };
        }
        if (definition.allocator != null or definition.allocator_root) return self.prepareFunction(function);
        definition.need = .unknown;
        try self.prepareWithoutAllocator(function);
    }

    fn hasNeed(self: *const TypeChecker, function: ast.Resolution.Function) bool {
        const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
        return declaration.kind == .function_definition and declaration.kind.function_definition.need == .yes;
    }

    fn spreadNeeds(self: *TypeChecker, functions: []const ast.Resolution.Function) void {
        var changed = true;
        while (changed) {
            changed = false;
            for (self.need_calls.items) |need_call| {
                if (!containsFunction(functions, need_call.caller)) continue;
                if (self.hasNeed(need_call.caller) or !self.hasNeed(need_call.callee)) continue;
                const reason: ast.NeedReason = .{ .location = need_call.location, .callee = need_call.callee };
                self.markNeed(&ast.findDeclaration(self.program.modules[need_call.caller.module], need_call.caller.declaration).kind.function_definition, reason);
                changed = true;
            }
        }
    }

    fn finishNeeds(self: *TypeChecker) TypeError!void {
        var callers: std.ArrayList(ast.Resolution.Function) = .empty;
        for (self.need_calls.items) |need_call| try callers.append(self.arena.allocator(), need_call.caller);
        self.spreadNeeds(callers.items);
        try self.reviseUndecidedCalls();
        for (self.undecided_calls.items) |undecided| {
            const location = undecided.with_location orelse continue;
            const definition = ast.findDeclaration(self.program.modules[undecided.caller.module], undecided.caller.declaration).kind.function_definition;
            if (definition.need == .yes) continue;
            self.module_index = undecided.caller.module;
            return self.fail(location, error.AllocatorNotNeeded);
        }
    }

    fn resolveAllocatorCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        const call = &expression.kind.call;
        const resolution = ast.extractResolution(call.callee);
        if (resolution != .function) return;
        const declaration = ast.findDeclaration(self.program.modules[resolution.function.module], resolution.function.declaration);
        if (declaration.kind != .function_definition) {
            if (call.with_value) |value| return self.fail(value.location, error.AllocatorNotNeeded);
            return;
        }
        const definition = &declaration.kind.function_definition;
        if (definition.allocator != null) return;
        const context = self.context_allocator;
        const with_type = if (call.with_value) |value| try self.checkWithOperand(parameters, value) else null;
        const cleared = if (call.with_value != null) with_type == null else context != null and context.?.type == null;
        const decided = call.with_value != null or context != null or self.allocator_type != null or self.allocator_root or (self.current_function == null and self.checking) or definition.signature.error_set != null;
        if (!decided and !self.hasNeed(resolution.function)) {
            const caller = self.current_function orelse {
                self.early_call = true;
                return;
            };
            try self.need_calls.append(self.arena.allocator(), .{ .caller = caller, .callee = resolution.function, .location = expression.location });
            return;
        }
        if (!try self.needsAllocator(resolution.function)) {
            const given = call.with_value != null or context != null or self.allocator_type != null or self.allocator_root;
            if (given and self.need_undecided and self.current_function != null) {
                const with_location = if (call.with_value) |value| value.location else null;
                try self.undecided_calls.append(self.arena.allocator(), .{ .caller = self.current_function.?, .callee = resolution.function, .with_location = with_location });
                return;
            }
            if (call.with_value) |value| return self.fail(value.location, error.AllocatorNotNeeded);
            if (self.current_function != null and self.allocator_type == null and !self.allocator_root) {
                try self.need_calls.append(self.arena.allocator(), .{ .caller = self.current_function.?, .callee = resolution.function, .location = expression.location });
            }
            return;
        }
        if (cleared) return self.failMissingAllocator(expression.location, resolution.function);
        if (call.with_value == null and context == null and self.allocator_type == null) {
            if (!self.allocator_root and self.current_function != null) {
                self.need_reason = .{ .location = expression.location, .callee = resolution.function };
                return self.fail(expression.location, error.NeedsAllocator);
            }
            return self.failMissingAllocator(expression.location, resolution.function);
        }
        const allocator = self.arena.allocator();
        const arguments = try allocator.alloc(ast.Argument, call.arguments.len + 1);
        @memcpy(arguments[0 .. arguments.len - 1], call.arguments);
        const allocator_type = if (call.with_value) |value| type: {
            arguments[arguments.len - 1] = .{ .name = null, .value = value.*, .location = value.location };
            break :type with_type.?;
        } else if (context) |given| type: {
            given.statement.kind.constant_declaration.context_used = true;
            const name: ast.Identifier = .{ .name = ast.context_local, .resolution = .{ .local = given.statement } };
            const value: ast.Expression = .{ .kind = .{ .identifier = name }, .location = expression.location, .type = given.type };
            arguments[arguments.len - 1] = .{ .name = null, .value = value, .location = expression.location };
            break :type given.type.?;
        } else type: {
            const given = self.allocator_type.?;
            const name: ast.Identifier = .{ .name = ast.allocator_parameter, .resolution = .{ .parameter = self.signature.?.parameters.len - 1 } };
            arguments[arguments.len - 1] = .{ .name = null, .value = .{ .kind = .{ .identifier = name }, .location = expression.location }, .location = expression.location };
            break :type given;
        };
        const instance = try self.findAllocatorInstance(resolution.function, allocator_type);
        try self.recordAllocatorCall(instance, expression.location);
        switch (call.callee) {
            inline else => |*name| name.resolution = .{ .function = instance },
        }
        call.arguments = arguments;
        call.with_value = null;
    }

    fn recordAllocatorCall(self: *TypeChecker, instance: ast.Resolution.Function, location: token.Location) TypeError!void {
        for (self.allocator_calls.items) |recorded| {
            if (std.meta.eql(recorded.function, instance)) return;
        }
        const call: InstanceCall = .{ .module = self.module_index, .location = location, .caller = self.current_function };
        try self.allocator_calls.append(self.arena.allocator(), .{ .function = instance, .call = call });
    }

    fn failMissingAllocator(self: *TypeChecker, location: token.Location, callee: ast.Resolution.Function) TypeError {
        const allocator = self.arena.allocator();
        var calls: std.ArrayList(InstanceCall) = .empty;
        try calls.append(allocator, .{ .module = self.module_index, .location = location, .caller = self.current_function });
        var current = callee;
        var root: InstanceCall = .{ .module = callee.module, .location = ast.findDeclaration(self.program.modules[callee.module], callee.declaration).location, .caller = callee };
        for (0..instance_limit) |_| {
            const declaration = ast.findDeclaration(self.program.modules[current.module], current.declaration);
            if (declaration.kind != .function_definition) break;
            const reason = declaration.kind.function_definition.need_reason orelse break;
            const next = reason.callee orelse {
                root = .{ .module = current.module, .location = reason.location, .caller = current };
                break;
            };
            try calls.append(allocator, .{ .module = current.module, .location = reason.location, .caller = current });
            current = next;
        }
        std.mem.reverse(InstanceCall, calls.items);
        self.trace = calls.items;
        self.module_index = root.module;
        return self.fail(root.location, error.MissingAllocator);
    }

    fn findCreatingInstance(self: *const TypeChecker, function: ast.Resolution.Function) ?Instance {
        for (self.instances.items) |instance| {
            if (std.meta.eql(instance.function, function)) return instance;
        }
        return null;
    }

    fn failUnsetAllocator(self: *TypeChecker, location: token.Location) TypeError!void {
        if (!self.allocator_root and self.current_function != null) {
            self.need_reason = .{ .location = location };
            return self.fail(location, error.NeedsAllocator);
        }
        self.trace = &.{};
        return self.fail(location, error.MissingAllocator);
    }

    fn checkWithOperand(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        value: *ast.Expression,
    ) TypeError!?types.Type {
        const operand = try self.inferType(parameters, value);
        if (operand != .type) return try self.expectAllocatorOperand(parameters, value);
        if (!self.evaluator.isKnown(value.*)) return self.fail(value.location, error.CannotEvaluate);
        const known = try self.evaluateValue(value);
        if (known != .type) return self.fail(value.location, error.NotAllocator);
        const target = known.type;
        if (isNoneAllocator(self.program.modules, target)) return null;
        const typeclass = findMemoryTypeclass(self.program.modules, "Allocator") orelse return self.fail(value.location, error.NotAllocator);
        if (!try self.hasTypeclassInstance(typeclass, target)) return self.fail(value.location, error.NotAllocator);
        if (target != .@"struct" or target.@"struct".fields.len > 0) return self.fail(value.location, error.AllocatorNeedsPointer);
        const allocator = self.arena.allocator();
        const literal = try allocator.create(ast.Expression);
        literal.* = .{ .kind = .{ .composite_literal = .{ .type = null, .elements = &.{} } }, .location = value.location, .type = target };
        const pointer: types.Type = .{ .pointer = try self.program.types.addPointer(allocator, .{ .target = target, .many = false, .constant = false }) };
        value.* = .{ .kind = .{ .address_of = literal }, .location = value.location, .type = pointer };
        return pointer;
    }

    fn expectAllocatorOperand(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        value: *ast.Expression,
    ) TypeError!types.Type {
        const operand = try self.inferType(parameters, value);
        if (operand != .pointer or operand.pointer.many or operand.pointer.constant) return self.fail(value.location, error.NotAllocator);
        const typeclass = findMemoryTypeclass(self.program.modules, "Allocator") orelse return self.fail(value.location, error.NotAllocator);
        if (!try self.hasTypeclassInstance(typeclass, operand.pointer.target)) return self.fail(value.location, error.NotAllocator);
        return operand;
    }

    fn findAllocatorInstance(
        self: *TypeChecker,
        function: ast.Resolution.Function,
        allocator_type: types.Type,
    ) TypeError!ast.Resolution.Function {
        var number: usize = 1;
        for (self.allocator_instances.items) |instance| {
            if (std.meta.eql(instance.function, function)) {
                if (std.meta.eql(instance.allocator_type, allocator_type)) return instance.instance;
                number += 1;
            }
        }
        const resolver = &self.resolver.?;
        const allocator = self.arena.allocator();
        const instance = if (self.findCreatingInstance(function)) |creating| instance: {
            const name = findFunctionName(self.program.modules, creating.template);
            var name_number: usize = 1;
            for (self.instances.items) |other| {
                if (other.template.module == creating.template.module and std.mem.eql(u8, findFunctionName(self.program.modules, other.template), name)) name_number += 1;
            }
            const created = try resolver.instantiate(resolver.context, creating.template, creating.arguments, name_number, false);
            try self.instances.append(allocator, .{ .template = creating.template, .arguments = creating.arguments, .function = created, .depth = creating.depth, .call = creating.call });
            try resolver.giveAllocator(resolver.context, created, allocator_type);
            break :instance created;
        } else try resolver.instantiateAllocator(resolver.context, function, allocator_type, number);
        try self.allocator_instances.append(allocator, .{ .function = function, .allocator_type = allocator_type, .instance = instance });
        try self.created.append(allocator, instance);
        try resolver.resolve(resolver.context, instance);
        return instance;
    }

    fn checkOwnership(self: *TypeChecker) TypeError!void {
        for (self.program.modules, 0..) |module, module_index| {
            for (0..module.declarations.len + module.instances.items.len) |declaration_index| {
                const declaration = ast.findDeclaration(module, declaration_index);
                self.module_index = module_index;
                switch (declaration.kind) {
                    .function_definition => |*definition| {
                        if (definition.pattern or ast.isGeneric(definition.signature) or definition.check_progress != .done) continue;
                        if (isOriginalFunction(definition.*)) try self.checkOwnReturnType(definition.signature);
                        if (definition.check_only) continue;
                        const function: ast.Resolution.Function = .{ .module = module_index, .declaration = declaration_index };
                        self.current_function = function;
                        errdefer if (self.failed_function == null) {
                            self.failed_function = function;
                        };
                        const caller_signature = self.signature;
                        defer self.signature = caller_signature;
                        self.signature = &definition.signature;
                        self.own_trusted = self.isTrustedFunction(module, definition.*);
                        try self.checkOwnStatements(definition.body, .plain);
                        try self.checkMoves(definition.*);
                    },
                    .function_declaration => |signature| try self.checkOwnReturnType(signature),
                    .constant_declaration, .struct_definition, .enum_definition, .typeclass_definition, .instance_declaration, .import => {},
                }
            }
        }
        self.current_function = null;
        self.own_trusted = false;
    }

    fn isTrustedFunction(self: *const TypeChecker, module: ast.Module, definition: ast.FunctionDefinition) bool {
        if (isMemoryModule(module.path)) return true;
        const allocator = findMemoryTypeclass(self.program.modules, "Allocator") orelse return false;
        if (definition.default_of) |typeclass| {
            if (std.meta.eql(typeclass, allocator)) return true;
        }
        const reference = definition.instance orelse return false;
        const instance = self.program.modules[reference.module].declarations[reference.declaration].kind.instance_declaration;
        const typeclass = instance.resolved orelse return false;
        if (!std.meta.eql(typeclass, allocator)) return false;
        var original = definition;
        while (original.template) |template| {
            original = ast.findDeclaration(self.program.modules[template.module], template.declaration).kind.function_definition;
        }
        const name = original.signature.name;
        return std.mem.eql(u8, name, "allocate") or std.mem.eql(u8, name, "free");
    }

    fn checkMoves(self: *TypeChecker, definition: ast.FunctionDefinition) TypeError!void {
        const allocator = self.arena.allocator();
        self.move_frames = .empty;
        self.move_loops = .empty;
        self.move_deferring = false;
        var owners: std.ArrayList(Owner) = .empty;
        for (definition.signature.parameters, 0..) |parameter, index| {
            if (!parameter.own or parameter.kind != .run_time) continue;
            const parameter_type = ast.extractType(parameter.type);
            const pointer = isOwnPointerParameter(parameter);
            const owned_type = if (pointer) parameter_type.pointer.target else parameter_type;
            if (!self.canOwn(owned_type)) continue;
            try owners.append(allocator, .{
                .root = .{ .parameter = index },
                .name = parameter.name,
                .type = owned_type,
                .location = parameter.location,
                .pointer = pointer,
            });
        }
        var state: MoveState = .{};
        _ = try self.checkMoveBlock(definition.body, &state, null, owners.items, null);
    }

    fn checkMoveBlock(
        self: *TypeChecker,
        statements: []const ast.Statement,
        state: *MoveState,
        loop: ?*const ast.Statement,
        owners: []const Owner,
        fallible: ?Fallible,
    ) TypeError!bool {
        const allocator = self.arena.allocator();
        try self.move_frames.append(allocator, .{ .loop = loop });
        try self.move_frames.items[self.move_frames.items.len - 1].owners.appendSlice(allocator, owners);
        var reachable = true;
        for (statements, 0..) |*statement, index| {
            reachable = if (fallible != null and index == statements.len - 1)
                try self.checkMoveTail(statement, state, fallible.?)
            else
                try self.checkMoveStatement(statement, state);
            if (!reachable) break;
        }
        const kind: MoveExit.Kind = if (self.move_frames.items.len == 1) .function_end else .block_end;
        if (reachable) try self.checkMoveExits(self.move_frames.items.len - 1, false, state, .{ .kind = kind });
        _ = self.move_frames.pop();
        return reachable;
    }

    fn checkMoveStatement(self: *TypeChecker, statement: *const ast.Statement, state: *MoveState) TypeError!bool {
        const allocator = self.arena.allocator();
        switch (statement.kind) {
            .noop => return true,
            .@"return" => |*returned| {
                const value = if (returned.*) |*value| value else {
                    try self.checkMoveExits(0, false, state, .{ .kind = .@"return", .location = statement.location });
                    return false;
                };
                if (self.returnsFallibleValue(value.*)) {
                    var paths: std.ArrayList(FailingPath) = .empty;
                    try self.checkMoveFallible(value, state, .{ .paths = &paths, .operator = .@"try" });
                    try self.checkMoveFailures(paths.items, .{ .kind = .@"return", .location = statement.location, .exit = value });
                } else try self.checkMoveExpression(value, state);
                if (self.signature.?.return_own and try self.isOwnPlace(value.*)) try self.moveName(value, state);
                const exit: MoveExit = .{ .kind = .@"return", .location = statement.location, .exit = value };
                try self.checkMoveExits(0, isErrorValue(value.*), state, exit);
                return false;
            },
            .discard, .call => |*expression| {
                try self.checkMoveExpression(expression, state);
                return true;
            },
            .value => |*expression| {
                try self.checkMoveExpression(expression, state);
                if (expression.handed) try self.moveName(expression, state);
                return true;
            },
            .constant_declaration => |*constant| {
                if (constant.known != null) return true;
                try self.checkMoveExpression(&constant.value, state);
                if (constant.moved) try self.moveName(&constant.value, state);
                state.restore(.{ .root = .{ .local = statement } });
                if (!constant.own) return true;
                try self.addOwner(statement, constant.name, ast.extractDeclaredType(constant.type, constant.value));
                try self.emptyWrittenParts(state, .{ .root = .{ .local = statement } }, constant.value);
                return true;
            },
            .variable_declaration => |*variable| {
                try self.checkMoveExpression(&variable.value, state);
                if (variable.moved) try self.moveName(&variable.value, state);
                state.restore(.{ .root = .{ .local = statement } });
                if (!variable.own) return true;
                try self.addOwner(statement, variable.name, ast.extractDeclaredType(variable.type, variable.value));
                try self.emptyWrittenParts(state, .{ .root = .{ .local = statement } }, variable.value);
                return true;
            },
            .tuple_declaration => |*declaration| {
                try self.checkMoveExpression(&declaration.value, state);
                if (declaration.moved) try self.moveName(&declaration.value, state);
                for (0..declaration.names.len) |position| {
                    state.restore(.{ .root = .{ .element = .{ .statement = statement, .position = position } } });
                }
                const owners = try self.buildElementOwners(statement, declaration.own, 0, declaration.names.len);
                try self.move_frames.items[self.move_frames.items.len - 1].owners.appendSlice(allocator, owners);
                return true;
            },
            .assignment => |*assignment| {
                const target = if (assignment.operator == null) try self.findPlace(assignment.target) else null;
                if (target) |place| {
                    try self.expectWritablePlace(place, assignment.target.location, state);
                    try self.expectEndedVariable(assignment.target, place, state);
                    try self.expectEmptyPart(place, assignment.target.location, state);
                } else try self.checkMoveExpression(&assignment.target, state);
                try self.checkMoveExpression(&assignment.value, state);
                if (assignment.moved) try self.moveName(&assignment.value, state);
                const place = target orelse return true;
                try self.fillPart(state, place);
                state.restore(place);
                try self.emptyWrittenParts(state, place, assignment.value);
                return true;
            },
            .@"if" => return self.checkMoveIf(statement, state, null),
            .match => return self.checkMoveMatch(statement, state, null),
            .@"while" => |*loop| {
                const owners = try self.buildElementOwners(statement, loop.own, 0, loop.names.len);
                try self.checkMoveLoop(statement, true, loop.body, loop.else_body, owners, state);
                return true;
            },
            .@"for" => |*loop| {
                switch (loop.sequence) {
                    .value => |*value| try self.checkMoveExpression(value, state),
                    .range => |*range| {
                        try self.checkMoveExpression(&range.start, state);
                        if (range.end) |*end| try self.checkMoveExpression(end, state);
                    },
                }
                try self.checkMoveLoop(statement, false, loop.body, loop.else_body, &.{}, state);
                return true;
            },
            .@"defer" => |*deferred| {
                try self.move_frames.items[self.move_frames.items.len - 1].deferred.append(allocator, deferred);
                return true;
            },
            .@"break", .@"continue" => |jump| {
                const target = jump.loop.?;
                var frame_index = self.move_frames.items.len - 1;
                while (self.move_frames.items[frame_index].loop != target) frame_index -= 1;
                const kind: MoveExit.Kind = if (statement.kind == .@"break") .@"break" else .@"continue";
                try self.checkMoveExits(frame_index, false, state, .{ .kind = kind, .location = statement.location });
                for (self.move_loops.items) |*context| {
                    if (context.statement != target) continue;
                    if (statement.kind == .@"break") {
                        try context.breaks.join(allocator, state);
                    } else try context.ends.join(allocator, state);
                }
                return false;
            },
        }
    }

    fn checkMoveIf(self: *TypeChecker, statement: *const ast.Statement, state: *MoveState, fallible: ?Fallible) TypeError!bool {
        const conditional = &statement.kind.@"if";
        try self.checkMoveCondition(statement, state);
        const owners = try self.buildElementOwners(statement, conditional.own, 0, conditional.names.len);
        if (conditional.known) |known| {
            if (known) return self.checkMoveBlock(conditional.body, state, null, owners, fallible);
            const chosen = conditional.else_body orelse return true;
            return self.checkMoveBlock(chosen, state, null, &.{}, fallible);
        }
        var other = try state.clone(self.arena.allocator());
        const body_reaches = try self.checkMoveBlock(conditional.body, state, null, owners, fallible);
        const else_reaches = if (conditional.else_body) |body| try self.checkMoveBlock(body, &other, null, &.{}, fallible) else true;
        return self.mergeMoveStates(state, body_reaches, &other, else_reaches);
    }

    fn checkMoveMatch(self: *TypeChecker, statement: *const ast.Statement, state: *MoveState, fallible: ?Fallible) TypeError!bool {
        const allocator = self.arena.allocator();
        const matching = &statement.kind.match;
        try self.checkMoveExpression(&matching.value, state);
        if (matching.moved) try self.moveName(&matching.value, state);
        const start = try state.clone(allocator);
        var merged: MoveState = .{ .reached = false };
        var reaches = false;
        for (matching.branches) |branch| {
            var branch_state = try start.clone(allocator);
            for (branch.first_name..branch.first_name + branch.name_count) |position| {
                branch_state.restore(.{ .root = .{ .element = .{ .statement = statement, .position = position } } });
            }
            const owners = try self.buildElementOwners(statement, branch.own, branch.first_name, branch.name_count);
            if (try self.checkMoveBlock(branch.body, &branch_state, null, owners, fallible)) {
                try merged.join(allocator, &branch_state);
                reaches = true;
            }
        }
        state.* = merged;
        return reaches;
    }

    fn checkMoveTail(self: *TypeChecker, statement: *const ast.Statement, state: *MoveState, fallible: Fallible) TypeError!bool {
        switch (statement.kind) {
            .value => |*expression| {
                if (!canFail(expression.*, fallible.operator)) return self.checkMoveStatement(statement, state);
                try self.checkMoveFallible(expression, state, fallible);
                if (expression.handed) try self.moveName(expression, state);
                return true;
            },
            .@"if" => return self.checkMoveIf(statement, state, fallible),
            .match => return self.checkMoveMatch(statement, state, fallible),
            else => return self.checkMoveStatement(statement, state),
        }
    }

    fn addOwner(self: *TypeChecker, statement: *const ast.Statement, name: []const u8, value_type: types.Type) TypeError!void {
        if (!self.canOwn(value_type)) return;
        const frame = &self.move_frames.items[self.move_frames.items.len - 1];
        try frame.owners.append(self.arena.allocator(), .{
            .root = .{ .local = statement },
            .name = name,
            .type = value_type,
            .location = statement.location,
        });
    }

    fn buildElementOwners(self: *TypeChecker, statement: *const ast.Statement, own: bool, first: usize, count: usize) TypeError![]const Owner {
        if (!own) return &.{};
        var owners: std.ArrayList(Owner) = .empty;
        const names = ast.extractElementNames(statement.*);
        for (first..first + count) |position| {
            const name = names[position];
            if (name.pointer or ast.isDiscardedName(name.name)) continue;
            const name_type = name.type orelse continue;
            if (!self.canOwn(name_type)) continue;
            try owners.append(self.arena.allocator(), .{
                .root = .{ .element = .{ .statement = statement, .position = position } },
                .name = name.name,
                .type = name_type,
                .location = name.location,
            });
        }
        return owners.items;
    }

    fn mergeMoveStates(self: *TypeChecker, state: *MoveState, state_reaches: bool, other: *MoveState, other_reaches: bool) TypeError!bool {
        if (!other_reaches) return state_reaches;
        if (!state_reaches) {
            state.* = other.*;
            return true;
        }
        try state.join(self.arena.allocator(), other);
        return true;
    }

    fn checkMoveLoop(
        self: *TypeChecker,
        statement: *const ast.Statement,
        conditional: bool,
        body: []const ast.Statement,
        else_body: ?[]const ast.Statement,
        owners: []const Owner,
        state: *MoveState,
    ) TypeError!void {
        const allocator = self.arena.allocator();
        var entry = try state.clone(allocator);
        var breaks: MoveState = .{ .reached = false };
        while (true) {
            var iteration = try entry.clone(allocator);
            if (conditional) try self.checkMoveCondition(statement, &iteration);
            try self.move_loops.append(allocator, .{ .statement = statement });
            const reaches = try self.checkMoveBlock(body, &iteration, statement, owners, null);
            const context = self.move_loops.pop().?;
            breaks = context.breaks;
            var ends = context.ends;
            if (reaches) try ends.join(allocator, &iteration);
            if (entry.contains(&ends)) break;
            try entry.join(allocator, &ends);
        }
        if (conditional) try self.checkMoveCondition(statement, &entry);
        if (isEndless(statement.*)) entry = .{ .reached = false };
        if (else_body) |block| {
            if (!try self.checkMoveBlock(block, &entry, null, &.{}, null)) entry = .{ .reached = false };
        }
        try entry.join(allocator, &breaks);
        state.* = entry;
    }

    fn checkMoveCondition(self: *TypeChecker, statement: *const ast.Statement, state: *MoveState) TypeError!void {
        const condition, const moved = switch (statement.kind) {
            .@"if" => |*conditional| .{ &conditional.condition, conditional.moved },
            .@"while" => |*loop| .{ &loop.condition, loop.moved },
            else => unreachable,
        };
        try self.checkMoveExpression(condition, state);
        if (moved) try self.moveName(condition, state);
        for (0..ast.extractElementNames(statement.*).len) |position| {
            state.restore(.{ .root = .{ .element = .{ .statement = statement, .position = position } } });
        }
    }

    fn checkMoveExits(self: *TypeChecker, innermost_kept: usize, failing: bool, state: *const MoveState, exit: MoveExit) TypeError!void {
        if (self.move_deferring) return;
        var exit_state = try self.runDeferred(innermost_kept, failing, state, exit);
        if (self.own_trusted or !exit_state.reached) return;
        var frame_index = self.move_frames.items.len;
        while (frame_index > innermost_kept) {
            frame_index -= 1;
            for (self.move_frames.items[frame_index].owners.items) |owner| {
                if (failing and owner.root == .parameter) {
                    try self.expectHeldParameter(owner, &exit_state, exit);
                    continue;
                }
                try self.expectConsumed(owner, &exit_state, exit);
            }
        }
    }

    fn runDeferred(self: *TypeChecker, innermost_kept: usize, failing: bool, state: *const MoveState, exit: MoveExit) TypeError!MoveState {
        self.move_deferring = true;
        defer self.move_deferring = false;
        var exit_state = try state.clone(self.arena.allocator());
        var frame_index = self.move_frames.items.len;
        while (frame_index > innermost_kept) {
            frame_index -= 1;
            const deferred = self.move_frames.items[frame_index].deferred.items;
            var position = deferred.len;
            while (position > 0) {
                position -= 1;
                if (deferred[position].on_error) {
                    if (!failing) continue;
                    if (try self.isDeferredHandedOver(deferred[position].statement, &exit_state)) {
                        if (self.move_skipped) |skipped| {
                            try skipped.append(self.arena.allocator(), deferred[position].statement);
                        } else try self.recordSkippedDefer(deferred[position].statement, exit.exit, &.{});
                        continue;
                    }
                }
                _ = try self.checkMoveStatement(deferred[position].statement, &exit_state);
            }
        }
        return exit_state;
    }

    fn isDeferredHandedOver(self: *TypeChecker, statement: *const ast.Statement, state: *const MoveState) TypeError!bool {
        var moved: std.ArrayList(*const ast.Expression) = .empty;
        try ast.collectStatementMoves(self.arena.allocator(), statement, &moved);
        for (moved.items) |expression| {
            const target = if (expression.kind == .address_of) expression.kind.address_of.* else expression.*;
            const place = try self.findPlace(target) orelse continue;
            if (state.isConsumed(place)) return true;
        }
        return false;
    }

    fn expectAgreedErrorDefers(self: *TypeChecker, expression: *const ast.Expression, paths: []const FailingPath) TypeError!void {
        const allocator = self.arena.allocator();
        for (self.move_frames.items) |frame| {
            for (frame.deferred.items) |deferred| {
                if (!deferred.on_error) continue;
                var moved: std.ArrayList(*const ast.Expression) = .empty;
                try ast.collectStatementMoves(allocator, deferred.statement, &moved);
                for (moved.items) |moved_expression| {
                    const target = if (moved_expression.kind == .address_of) moved_expression.kind.address_of.* else moved_expression.*;
                    const place = try self.findPlace(target) orelse continue;
                    var handed = false;
                    var held = false;
                    for (paths) |path| {
                        if (path.state.isConsumed(place)) {
                            handed = true;
                        } else held = true;
                    }
                    if (!handed or !held) continue;
                    const failure = self.fail(expression.kind.binary.operator_location, error.OwnNotConsumed);
                    const text = try renderPlace(allocator, self.findRootName(place.root), place);
                    const operator = if (expression.kind.binary.operator == .@"catch") "catch" else "orelse";
                    const format = "`{s}` is handed on with own in some branches that reach this {s} and still held in others, so its errdefer would both run and not run there; hand `{s}` on the same way in every branch that reaches the {s}, or before the if or match";
                    self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ text, operator, text, operator });
                    return failure;
                }
            }
        }
    }

    fn recordSkippedDefer(
        self: *TypeChecker,
        statement: *const ast.Statement,
        exit: ?*const ast.Expression,
        sources: []const *const ast.Expression,
    ) TypeError!void {
        const expression = exit orelse return;
        for (self.skipped_defers.items) |skipped| {
            if (skipped.statement == statement and skipped.exit == expression) return;
        }
        try self.skipped_defers.append(self.arena.allocator(), .{ .statement = statement, .exit = expression, .sources = sources });
    }

    fn expectHeldParameter(self: *TypeChecker, owner: Owner, state: *const MoveState, exit: MoveExit) TypeError!void {
        if (!state.hasMovedAround(.{ .root = owner.root })) return;
        const failure = self.fail(exit.location orelse owner.location, error.OwnParameterHandedOn);
        const format = "`{s}` is an own parameter and is handed on before the function fails {s}; where a function fails, its caller still holds what it passed, so `{s}` has to be held here";
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{ owner.name, describeExit(exit.kind), owner.name });
        return failure;
    }

    fn expectConsumed(self: *TypeChecker, owner: Owner, state: *const MoveState, exit: MoveExit) TypeError!void {
        const left = try self.findUnconsumed(state, .{ .root = owner.root }, owner.type) orelse return;
        const allocator = self.arena.allocator();
        const unendable_field = if (left.steps.len == 0 and !owner.pointer and !state.hasMovedAround(left)) try self.findUnendableField(owner.type) else null;
        if (unendable_field) |field_name| {
            const unendable = self.fail(exit.location orelse owner.location, error.OwnUnendable);
            const type_name = try ast.renderTypeName(allocator, self.program.modules, owner.type);
            const module_name = try std.mem.join(allocator, "::", self.program.modules[owner.type.@"struct".module].path);
            const format = "`{s}` from `{s}` can be held but not ended: its module provides no `Deinit` instance and no function that takes it over, and its private fields cannot be taken apart here; take them apart with `private` anyway, e.g. `own {s}.private.{s}`";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ type_name, module_name, owner.name, field_name });
            return unendable;
        }
        const failure = self.fail(exit.location orelse owner.location, error.OwnNotConsumed);
        const text = try renderPlace(allocator, owner.name, left);
        const where = describeExit(exit.kind);
        const hint = if (exit.kind == .failure) "; an errdefer that hands it on covers this exit" else "";
        self.failure.?.message = if (state.hasMovedAround(left))
            try std.fmt.allocPrint(allocator, "`{s}` is handed on with own on some paths but still holds what it owns {s} on another; hand it on along every path{s}", .{ text, where, hint })
        else if (left.steps.len > 0)
            try std.fmt.allocPrint(allocator, "`{s}` still holds what it owns {s}, and `{s}` cannot end it as a whole, since another of its parts has moved; hand `{s}` on with own{s}", .{ text, where, owner.name, text, hint })
        else if (owner.pointer)
            try std.fmt.allocPrint(allocator, "`{s}` is an own pointer, so this function is the last holder of what it points to, yet nothing of it is handed on {s}; hand on each of its parts with own, e.g. `own &{s}{s}`, or pass it on with `own {s}`", .{ text, where, text, try self.describeFirstPart(owner.type), text })
        else
            try std.fmt.allocPrint(allocator, "`{s}` still holds what it owns {s}; hand it on with own before then, e.g. `own {s}` or `own &{s}` to a call that ends it{s}", .{ text, where, text, text, hint });
        return failure;
    }

    fn findUnendableField(self: *TypeChecker, value_type: types.Type) TypeError!?[]const u8 {
        if (value_type != .@"struct") return null;
        const struct_type = value_type.@"struct";
        if (struct_type.module == self.module_index) return null;
        const owning = for (struct_type.fields) |field| {
            if (field.private and self.isOwningField(struct_type, field)) break field.name;
        } else return null;
        if (findMemoryTypeclass(self.program.modules, "Deinit")) |deinit| {
            if (try self.hasTypeclassInstance(deinit, value_type)) return null;
        }
        const module = self.program.modules[struct_type.module];
        for (0..module.declarations.len + module.instances.items.len) |index| {
            const declaration = ast.findDeclaration(module, index).*;
            const signature = switch (declaration.kind) {
                .function_definition => |definition| definition.signature,
                .function_declaration => |signature| signature,
                .constant_declaration, .struct_definition, .enum_definition, .typeclass_definition, .instance_declaration, .import => continue,
            };
            if (signature.private or signature.typeclass != null or signature.progress != .done or ast.isGeneric(signature)) continue;
            if (index < module.declarations.len and ast.isHidden(module, index)) continue;
            for (signature.parameters) |parameter| {
                if (!parameter.own or parameter.hidden) continue;
                if (std.meta.eql(types.followPointer(ast.extractType(parameter.type)), value_type)) return null;
            }
        }
        return owning;
    }

    fn describeFirstPart(self: *TypeChecker, value_type: types.Type) TypeError![]const u8 {
        if (value_type != .@"struct") return "";
        for (value_type.@"struct".fields) |field| {
            if (self.isOwningField(value_type.@"struct", field)) return std.fmt.allocPrint(self.arena.allocator(), ".{s}", .{field.name});
        }
        return "";
    }

    fn findUnconsumed(self: *TypeChecker, state: *const MoveState, place: ast.Place, value_type: types.Type) TypeError!?ast.Place {
        if (state.isConsumed(place)) return null;
        if (!state.hasConsumedWithin(place)) return place;
        const allocator = self.arena.allocator();
        switch (value_type) {
            .@"struct" => |struct_type| for (struct_type.fields) |field| {
                if (!self.isOwningField(struct_type, field)) continue;
                const part = try place.extend(allocator, .{ .field = field.name });
                if (try self.findUnconsumed(state, part, field.type)) |left| return left;
            },
            .array => |array| {
                if (!self.canOwn(array.element)) return null;
                for (0..array.length) |position| {
                    const part = try place.extend(allocator, .{ .element = position });
                    if (try self.findUnconsumed(state, part, array.element)) |left| return left;
                }
            },
            .tuple => |tuple| for (tuple.elements, 0..) |element, position| {
                if (!self.canOwn(element)) continue;
                const part = try place.extend(allocator, .{ .element = position });
                if (try self.findUnconsumed(state, part, element)) |left| return left;
            },
            .optional => |optional| return self.findUnconsumed(state, try place.extend(allocator, .value), optional.child),
            .number, .boolean, .void, .type, .@"enum", .slice, .pointer, .result, .function, .variable, .application => {},
        }
        return null;
    }

    fn isOwningField(self: *const TypeChecker, struct_type: types.Struct, field: types.Field) bool {
        if (struct_type.@"inline") return self.canOwn(field.type);
        return (field.own and self.canOwn(field.type)) or self.isOwningType(field.type);
    }

    fn checkMoveExpression(self: *TypeChecker, expression: *const ast.Expression, state: *MoveState) TypeError!void {
        const allocator = self.arena.allocator();
        switch (expression.kind) {
            .identifier => {
                const place = try self.findPlace(expression.*) orelse return;
                try self.expectUsable(place, expression.location, state);
            },
            .call => |*call| {
                if (call.callee == .member) try self.checkMoveExpression(call.callee.member.owner, state);
                try self.checkMoveArguments(call.arguments, state);
                if (call.with_value) |value| try self.checkMoveExpression(value, state);
                try self.applyMemoryPrimitive(call.*, state);
            },
            .method_call => |*call| {
                try self.checkMoveExpression(call.receiver, state);
                try self.checkMoveArguments(call.arguments, state);
                if (call.with_value) |value| try self.checkMoveExpression(value, state);
            },
            .composite_literal => |*literal| try self.checkMoveArguments(literal.elements, state),
            .case_literal => |*literal| try self.checkMoveArguments(literal.arguments, state),
            .member => |member| try self.checkMoveExpression(member.owner, state),
            .negation, .address_of, .dereference => |operand| try self.checkMoveExpression(operand, state),
            .unwrap => |operand| {
                if (try self.findPlace(expression.*)) |place| return self.expectUsable(place, expression.location, state);
                try self.checkMoveExpression(operand, state);
            },
            .unary => |unary| try self.checkMoveExpression(unary.operand, state),
            .field_access => |access| {
                if (try self.findPlace(expression.*)) |place| return self.expectUsable(place, expression.location, state);
                try self.checkMoveExpression(access.value, state);
            },
            .index => |indexing| {
                if (try self.findPlace(expression.*)) |place| return self.expectUsable(place, expression.location, state);
                try self.checkMoveExpression(indexing.value, state);
                try self.checkMoveExpression(indexing.index, state);
            },
            .slice => |slice| {
                try self.checkMoveExpression(slice.value, state);
                if (slice.start) |start| try self.checkMoveExpression(start, state);
                if (slice.end) |end| try self.checkMoveExpression(end, state);
            },
            .range => |range| {
                try self.checkMoveExpression(&range.start, state);
                if (range.end) |*end| try self.checkMoveExpression(end, state);
            },
            .@"try" => |operand| {
                var paths: std.ArrayList(FailingPath) = .empty;
                try self.checkMoveFallible(operand, state, .{ .paths = &paths, .operator = .@"try" });
                try self.checkMoveFailures(paths.items, .{ .kind = .failure, .location = expression.location, .exit = expression });
            },
            .binary => |binary| {
                if (binary.left.kind == .branching and (binary.operator == .@"catch" or binary.operator == .@"orelse")) {
                    return self.checkMoveCaught(expression, state);
                }
                try self.checkMoveExpression(binary.left, state);
                if (!isShortCircuitOperator(binary.operator)) return self.checkMoveExpression(binary.right, state);
                var other = try state.clone(allocator);
                try self.checkMoveExpression(binary.right, &other);
                if (binary.right.kind == .jump) return;
                try state.join(allocator, &other);
            },
            .jump, .branching => |statement| _ = try self.checkMoveStatement(statement, state),
            .integer_literal,
            .float_literal,
            .boolean_literal,
            .string_literal,
            .undefined,
            .null,
            .path_expression,
            .array_type,
            .inferred_type,
            .slice_type,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            => {},
        }
    }

    fn checkMoveFallible(self: *TypeChecker, expression: *const ast.Expression, state: *MoveState, fallible: Fallible) TypeError!void {
        const allocator = self.arena.allocator();
        if (expression.kind == .branching) {
            _ = try self.checkMoveTail(expression.kind.branching, state, fallible);
            return;
        }
        if (fallible.operator != .@"try") {
            try self.checkMoveExpression(expression, state);
            return fallible.paths.append(allocator, .{ .state = try state.clone(allocator), .source = expression });
        }
        const arguments, const with_value = switch (expression.kind) {
            .call => |*call| arguments: {
                if (call.callee == .member) try self.checkMoveExpression(call.callee.member.owner, state);
                break :arguments .{ call.arguments, call.with_value };
            },
            .method_call => |*call| arguments: {
                try self.checkMoveExpression(call.receiver, state);
                break :arguments .{ call.arguments, call.with_value };
            },
            else => {
                try fallible.paths.append(allocator, .{ .state = try state.clone(allocator), .source = expression });
                return self.checkMoveExpression(expression, state);
            },
        };
        for (arguments) |*argument| try self.checkMoveExpression(&argument.value, state);
        if (with_value) |value| try self.checkMoveExpression(value, state);
        try fallible.paths.append(allocator, .{ .state = try state.clone(allocator), .source = expression });
        for (arguments) |*argument| {
            if (argument.own) try self.moveName(&argument.value, state);
        }
    }

    fn checkMoveFailures(self: *TypeChecker, paths: []const FailingPath, exit: MoveExit) TypeError!void {
        const allocator = self.arena.allocator();
        const skipped = try allocator.alloc(std.ArrayList(*const ast.Statement), paths.len);
        const outer = self.move_skipped;
        defer self.move_skipped = outer;
        for (paths, skipped) |*path, *path_skipped| {
            path_skipped.* = .empty;
            self.move_skipped = path_skipped;
            try self.checkMoveExits(0, true, &path.state, exit);
        }
        self.move_skipped = outer;
        for (skipped, 0..) |path_skipped, index| {
            for (path_skipped.items) |statement| {
                if (anyContainsStatement(skipped[0..index], statement)) continue;
                var sources: std.ArrayList(*const ast.Expression) = .empty;
                for (paths, skipped) |path, other_skipped| {
                    if (containsStatement(other_skipped.items, statement)) try sources.append(allocator, path.source);
                }
                const conditional = if (sources.items.len == paths.len) &.{} else sources.items;
                try self.recordSkippedDefer(statement, exit.exit, conditional);
            }
        }
    }

    fn checkMoveCaught(self: *TypeChecker, expression: *const ast.Expression, state: *MoveState) TypeError!void {
        const allocator = self.arena.allocator();
        const binary = expression.kind.binary;
        var paths: std.ArrayList(FailingPath) = .empty;
        const operator: Fallible.Operator = if (binary.operator == .@"catch") .@"catch" else .@"orelse";
        try self.checkMoveFallible(binary.left, state, .{ .paths = &paths, .operator = operator });
        try self.expectAgreedErrorDefers(expression, paths.items);
        var other: MoveState = .{ .reached = false };
        for (paths.items) |*path| try other.join(allocator, &path.state);
        try self.checkMoveExpression(binary.right, &other);
        if (binary.right.kind == .jump) return;
        try state.join(allocator, &other);
    }

    fn returnsFallibleValue(self: *const TypeChecker, value: ast.Expression) bool {
        if (value.kind != .call and value.kind != .method_call and value.kind != .branching) return false;
        const value_type = value.type orelse return false;
        return value_type == .result and canHoldError(ast.extractType(self.signature.?.return_type));
    }

    fn checkMoveArguments(self: *TypeChecker, arguments: []const ast.Argument, state: *MoveState) TypeError!void {
        for (arguments) |*argument| try self.checkMoveExpression(&argument.value, state);
        for (arguments) |*argument| {
            if (argument.own) try self.moveName(&argument.value, state);
        }
    }

    fn applyMemoryPrimitive(self: *TypeChecker, call: ast.Call, state: *MoveState) TypeError!void {
        const primitive = self.findMemoryPrimitive(call) orelse return;
        if (call.arguments.len == 0) return;
        const source = &call.arguments[0].value;
        if (source.kind != .address_of) return;
        switch (primitive) {
            .move => try self.moveName(source, state),
            .take => {
                const place = try self.findPlace(source.kind.address_of.*) orelse return;
                try state.addConsumed(self.arena.allocator(), place);
            },
        }
    }

    fn findMemoryPrimitive(self: *const TypeChecker, call: ast.Call) ?MemoryPrimitive {
        const resolution = switch (call.callee) {
            .identifier => |identifier| identifier.resolution,
            .path_expression => |path_expression| path_expression.resolution,
            .member => null,
        } orelse return null;
        if (resolution != .function) return null;
        var function = resolution.function;
        var declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration).*;
        while (declaration.kind == .function_definition) {
            function = declaration.kind.function_definition.template orelse break;
            declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration).*;
        }
        if (!isMemoryModule(self.program.modules[function.module].path)) return null;
        const name = ast.extractFunctionSignature(declaration).name;
        if (std.mem.eql(u8, name, "move")) return .move;
        if (std.mem.eql(u8, name, "take")) return .take;
        return null;
    }

    fn moveName(self: *TypeChecker, expression: *const ast.Expression, state: *MoveState) TypeError!void {
        const moved = if (expression.kind == .address_of) expression.kind.address_of.* else expression.*;
        const place = try self.findPlace(moved) orelse return;
        if (!self.canOwnValue(moved)) return;
        try self.expectUsable(place, expression.location, state);
        try state.add(self.arena.allocator(), place);
    }

    fn expectUsable(self: *TypeChecker, place: ast.Place, location: token.Location, state: *const MoveState) TypeError!void {
        const moved = state.findMoved(place) orelse return;
        const allocator = self.arena.allocator();
        const name = self.findRootName(place.root);
        const text = try renderPlace(allocator, name, place);
        const moved_text = try renderPlace(allocator, name, moved);
        if (moved.contains(place)) {
            const failure = self.fail(location, error.OwnNameMoved);
            self.failure.?.message = if (moved.steps.len == place.steps.len)
                try std.fmt.allocPrint(allocator, "`{s}` has moved; give it a new value before using it again", .{text})
            else
                try std.fmt.allocPrint(allocator, "`{s}` has moved, and `{s}` with it; give `{s}` a new value before using it again", .{ moved_text, text, moved_text });
            return failure;
        }
        const failure = self.fail(location, error.OwnPartMoved);
        self.failure.?.message = try std.fmt.allocPrint(allocator, "`{s}` cannot be used as a whole, since its part `{s}` has moved; its other parts can still be used", .{ text, moved_text });
        return failure;
    }

    fn expectEndedVariable(self: *TypeChecker, target: ast.Expression, place: ast.Place, state: *const MoveState) TypeError!void {
        if (place.steps.len > 0 or !self.isOwnRoot(place.root)) return;
        const variable_type = self.findNameType(target);
        if (!self.canOwn(variable_type)) return;
        if (try self.findUnconsumed(state, place, variable_type) == null) return;
        const failure = self.fail(target.location, error.OwnVariableHeld);
        const format = "`{s}` still holds what it owns here; hand it on with own before giving it a new value, e.g. `{s}.deinit(own)`";
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{ target.kind.identifier.name, target.kind.identifier.name });
        return failure;
    }

    fn expectEmptyPart(self: *TypeChecker, place: ast.Place, location: token.Location, state: *const MoveState) TypeError!void {
        if (place.steps.len == 0) return;
        const owner = self.findMoveOwner(place.root) orelse return;
        const part_type = self.findOwningPartType(owner.type, place.steps) orelse return;
        if (try self.findUnconsumed(state, place, part_type) == null) return;
        const failure = self.fail(location, error.OwnPartHeld);
        const text = try renderPlace(self.arena.allocator(), owner.name, place);
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), "`{s}` still holds a value; end it or take it out first", .{text});
        return failure;
    }

    fn findMoveOwner(self: *const TypeChecker, root: ast.Resolution) ?Owner {
        for (self.move_frames.items) |frame| {
            for (frame.owners.items) |owner| {
                if (std.meta.eql(owner.root, root)) return owner;
            }
        }
        return null;
    }

    fn findOwningPartType(self: *const TypeChecker, root_type: types.Type, steps: []const ast.PartStep) ?types.Type {
        const part_type = findPlaceType(root_type, steps) orelse return null;
        const last = steps[steps.len - 1];
        if (last == .field) {
            const parent = findPlaceType(root_type, steps[0 .. steps.len - 1]).?;
            if (!self.isOwningField(parent.@"struct", findField(parent.@"struct".fields, last.field).?)) return null;
        }
        if (!self.canOwn(part_type)) return null;
        return part_type;
    }

    fn emptyWrittenParts(self: *TypeChecker, state: *MoveState, place: ast.Place, value: ast.Expression) TypeError!void {
        if (isEmptyValue(value)) return state.addConsumed(self.arena.allocator(), place);
        try self.emptyLiteralParts(state, place, value);
    }

    fn emptyLiteralParts(self: *TypeChecker, state: *MoveState, place: ast.Place, value: ast.Expression) TypeError!void {
        if (value.kind != .composite_literal) return;
        const value_type = value.type orelse return;
        const allocator = self.arena.allocator();
        for (value.kind.composite_literal.elements, 0..) |element, position| {
            const step: ast.PartStep = switch (value_type) {
                .@"struct" => |struct_type| step: {
                    if (element.name) |name| break :step .{ .field = name };
                    if (position >= struct_type.fields.len) return;
                    break :step .{ .field = struct_type.fields[position].name };
                },
                .array, .tuple => .{ .element = position },
                else => return,
            };
            if (!self.isOwningStep(value_type, step)) continue;
            const part = try place.extend(allocator, step);
            if (isEmptyValue(element.value)) {
                try state.addConsumed(allocator, part);
            } else try self.emptyLiteralParts(state, part, element.value);
        }
    }

    fn isOwningStep(self: *const TypeChecker, value_type: types.Type, step: ast.PartStep) bool {
        if (step == .field) {
            const field = findField(value_type.@"struct".fields, step.field) orelse return false;
            return self.isOwningField(value_type.@"struct", field);
        }
        const part_type = findStepType(value_type, step) orelse return false;
        return self.canOwn(part_type);
    }

    fn fillPart(self: *TypeChecker, state: *MoveState, place: ast.Place) TypeError!void {
        const owner = self.findMoveOwner(place.root) orelse return;
        const allocator = self.arena.allocator();
        var index: usize = 0;
        while (index < state.consumed.items.len) {
            const consumed = state.consumed.items[index];
            if (consumed.steps.len >= place.steps.len or !consumed.contains(place)) {
                index += 1;
                continue;
            }
            _ = state.consumed.swapRemove(index);
            var current = consumed;
            var current_type = findPlaceType(owner.type, consumed.steps) orelse continue;
            for (place.steps[consumed.steps.len..]) |step| {
                for (try self.collectOwningSteps(current_type)) |sibling| {
                    if (!sibling.eql(step)) try state.addConsumed(allocator, try current.extend(allocator, sibling));
                }
                current = try current.extend(allocator, step);
                current_type = findPlaceType(current_type, &.{step}) orelse break;
            }
        }
    }

    fn collectOwningSteps(self: *TypeChecker, value_type: types.Type) TypeError![]const ast.PartStep {
        const allocator = self.arena.allocator();
        var steps: std.ArrayList(ast.PartStep) = .empty;
        switch (value_type) {
            .@"struct" => |struct_type| for (struct_type.fields) |field| {
                if (self.isOwningField(struct_type, field)) try steps.append(allocator, .{ .field = field.name });
            },
            .array => |array| if (self.canOwn(array.element)) {
                for (0..array.length) |position| try steps.append(allocator, .{ .element = position });
            },
            .tuple => |tuple| for (tuple.elements, 0..) |element, position| {
                if (self.canOwn(element)) try steps.append(allocator, .{ .element = position });
            },
            .number, .boolean, .void, .type, .@"enum", .slice, .pointer, .optional, .result, .function, .variable, .application => {},
        }
        return steps.items;
    }

    fn expectWritablePlace(self: *TypeChecker, place: ast.Place, location: token.Location, state: *const MoveState) TypeError!void {
        for (state.moved.items) |moved| {
            if (moved.steps.len >= place.steps.len or !moved.contains(place)) continue;
            const allocator = self.arena.allocator();
            const name = self.findRootName(place.root);
            const failure = self.fail(location, error.OwnNameMoved);
            const moved_text = try renderPlace(allocator, name, moved);
            self.failure.?.message = try std.fmt.allocPrint(allocator, "`{s}` has moved, and `{s}` with it; give `{s}` a new value as a whole before writing to its parts", .{ moved_text, try renderPlace(allocator, name, place), moved_text });
            return failure;
        }
    }

    fn findNameType(self: *const TypeChecker, expression: ast.Expression) types.Type {
        return switch (expression.kind.identifier.resolution.?) {
            .local => |statement| switch (statement.kind) {
                .constant_declaration => |constant| ast.extractDeclaredType(constant.type, constant.value),
                .variable_declaration => |variable| ast.extractDeclaredType(variable.type, variable.value),
                else => expression.type.?,
            },
            .parameter => |index| ast.extractType(self.signature.?.parameters[index].type),
            .element => |element| ast.findElementName(element).type orelse expression.type.?,
            else => expression.type.?,
        };
    }

    fn findRootName(self: *const TypeChecker, root: ast.Resolution) []const u8 {
        return switch (root) {
            .local => |statement| switch (statement.kind) {
                .constant_declaration => |constant| constant.name,
                .variable_declaration => |variable| variable.name,
                else => "",
            },
            .parameter => |index| self.signature.?.parameters[index].name,
            .element => |element| ast.findElementName(element).name,
            else => "",
        };
    }

    fn findPlace(self: *TypeChecker, expression: ast.Expression) TypeError!?ast.Place {
        const allocator = self.arena.allocator();
        switch (expression.kind) {
            .identifier => |identifier| {
                const resolution = identifier.resolution orelse return null;
                return switch (resolution) {
                    .local, .parameter, .element => .{ .root = resolution },
                    else => null,
                };
            },
            .field_access => |access| {
                if (isSliceField(access)) return null;
                const value_type = access.value.type orelse return null;
                if (value_type == .pointer and !self.isOwnPointerName(access.value.*)) return null;
                if (value_type != .pointer and value_type != .@"struct") return null;
                const base = try self.findPlace(access.value.*) orelse return null;
                return try base.extend(allocator, .{ .field = access.field });
            },
            .index => |indexing| {
                if (!self.isInlineIndexing(indexing)) return null;
                const position = indexing.position orelse return null;
                const base = try self.findPlace(indexing.value.*) orelse return null;
                return try base.extend(allocator, .{ .element = position });
            },
            .unwrap => |operand| {
                const value_type = operand.type orelse return null;
                if (value_type != .optional) return null;
                const base = try self.findPlace(operand.*) orelse return null;
                return try base.extend(allocator, .value);
            },
            else => return null,
        }
    }

    fn isInlineIndexing(self: *const TypeChecker, indexing: ast.Index) bool {
        const value_type = indexing.value.type orelse return false;
        return switch (value_type) {
            .array, .tuple => true,
            .pointer => |pointer| !pointer.many and pointer.target == .array and self.isOwnPointerName(indexing.value.*),
            else => false,
        };
    }

    fn isOwnElementTarget(self: *const TypeChecker, target: ast.Expression) bool {
        if (target.kind != .index) return false;
        const container = target.kind.index.value.*;
        const container_type = container.type orelse return false;
        const element_type = target.type orelse return false;
        const inline_type = followPointer(container_type);
        if (inline_type != .array and inline_type != .tuple) return false;
        if (!self.canOwn(element_type)) return false;
        return self.isOwnName(container) or isOwnFieldTarget(container) or self.isOwnElementTarget(container);
    }

    fn isOwnPointerName(self: *const TypeChecker, expression: ast.Expression) bool {
        if (expression.kind != .identifier) return false;
        const resolution = expression.kind.identifier.resolution orelse return false;
        if (resolution != .parameter) return false;
        const parameters = self.signature.?.parameters;
        return resolution.parameter < parameters.len and isOwnPointerParameter(parameters[resolution.parameter]);
    }

    fn isOwnRoot(self: *const TypeChecker, resolution: ast.Resolution) bool {
        return switch (resolution) {
            .local => |statement| switch (statement.kind) {
                .constant_declaration => |constant| constant.own,
                .variable_declaration => |variable| variable.own,
                else => false,
            },
            .parameter => |index| index < self.signature.?.parameters.len and self.signature.?.parameters[index].own,
            .element => |element| ast.isOwnElement(element),
            else => false,
        };
    }

    fn isOwnedPart(self: *TypeChecker, expression: ast.Expression) TypeError!bool {
        if (!self.canOwnValue(expression)) return false;
        const place = try self.findPlace(expression) orelse return false;
        return place.steps.len > 0 and self.isOwnRoot(place.root);
    }

    fn isInlineOwnedPart(self: *TypeChecker, target: ast.Expression) TypeError!bool {
        if (target.kind != .field_access) return false;
        const value_type = target.kind.field_access.value.type orelse return false;
        const container = followPointer(value_type);
        if (container != .@"struct" or !container.@"struct".@"inline") return false;
        return self.isOwnedPart(target);
    }

    fn isOwnPlace(self: *TypeChecker, expression: ast.Expression) TypeError!bool {
        return self.isOwnName(expression) or try self.isOwnedPart(expression);
    }

    fn findUnknownIndex(self: *const TypeChecker, expression: ast.Expression) ?token.Location {
        var current = expression;
        var unknown: ?token.Location = null;
        while (true) {
            switch (current.kind) {
                .field_access => |access| {
                    const value_type = access.value.type orelse return null;
                    if (value_type == .pointer and !self.isOwnPointerName(access.value.*)) return null;
                    current = access.value.*;
                },
                .unwrap => |operand| current = operand.*,
                .index => |indexing| {
                    if (!self.isInlineIndexing(indexing)) return null;
                    if (indexing.position == null) unknown = indexing.index.location;
                    current = indexing.value.*;
                },
                .identifier => |identifier| {
                    const resolution = identifier.resolution orelse return null;
                    if (!self.isOwnRoot(resolution)) return null;
                    return unknown;
                },
                else => return null,
            }
        }
    }

    fn checkOwnReturnType(self: *TypeChecker, signature: ast.FunctionSignature) TypeError!void {
        if (!signature.return_own) return;
        const denoted = ast.extractType(signature.return_type);
        if (containsAnyVariable(denoted) or canHoldAllocation(denoted)) return;
        return self.fail(signature.return_type.location, error.OwnWithoutAllocation);
    }

    fn checkOwnStatements(self: *TypeChecker, statements: []ast.Statement, value_place: OwnPlace) TypeError!void {
        for (statements) |*statement| try self.checkOwnStatement(statement, value_place);
    }

    fn checkOwnStatement(self: *TypeChecker, statement: *ast.Statement, value_place: OwnPlace) TypeError!void {
        switch (statement.kind) {
            .noop, .@"break", .@"continue" => {},
            .@"return" => |*returned| {
                const value = if (returned.*) |*value| value else return;
                if (self.signature.?.return_own) {
                    if (value.handed) return self.checkOwnDestination(value, true, true, value.location);
                    if (!try self.isOwnPlace(value.*) and self.isCopiedOwningValue(value.*)) return self.fail(value.location, error.OwnValueCopied);
                    return self.checkOwnValue(value, .owned);
                }
                if (value.handed) return self.checkOwnDestination(value, false, true, value.location);
                if (self.isOwnName(value.*)) return self.fail(value.location, error.OwnNameReturned);
                try self.checkOwnValue(value, .copied);
            },
            .discard => |*expression| {
                if (self.isOwnName(expression.*) and self.canOwn(self.findNameType(expression.*))) {
                    const failure = self.fail(expression.location, error.OwnNameDiscarded);
                    const format = "`{s}` is declared own, and `_ =` would drop what it holds; hand it on with own instead, e.g. to a call that ends it";
                    self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{expression.kind.identifier.name});
                    return failure;
                }
                try self.checkOwnValue(expression, .plain);
            },
            .call => |*expression| try self.checkOwnValue(expression, .plain),
            .value => |*expression| try self.checkOwnBranchValue(expression, value_place),
            .constant_declaration => |*constant| {
                if (constant.with or constant.context) return;
                try self.checkOwnDestination(&constant.value, constant.own, constant.moved, constant.value.location);
            },
            .variable_declaration => |*variable| try self.checkOwnDestination(&variable.value, variable.own, variable.moved, variable.value.location),
            .tuple_declaration => |*declaration| try self.checkOwnNaming(&declaration.value, declaration.moved, declaration.names, declaration.own),
            .assignment => |*assignment| {
                try self.checkOwnValue(&assignment.target, .plain);
                const into_place = assignment.moved and isPlaceTarget(assignment.target);
                const owned = assignment.operator == null and (self.isOwnName(assignment.target) or into_place or isOwnFieldTarget(assignment.target) or self.isOwnElementTarget(assignment.target) or try self.isInlineOwnedPart(assignment.target));
                try self.checkOwnDestination(&assignment.value, owned, assignment.moved, assignment.value.location);
            },
            .@"if" => |*conditional| {
                conditional.moved = try self.checkOwnTest("if", &conditional.condition, conditional.marker, conditional.names, conditional.tuple, conditional.own);
                try self.checkOwnStatements(conditional.body, value_place);
                if (conditional.else_body) |body| try self.checkOwnStatements(body, value_place);
            },
            .@"while" => |*loop| {
                loop.moved = try self.checkOwnTest("while", &loop.condition, loop.marker, loop.names, loop.tuple, loop.own);
                try self.checkOwnStatements(loop.body, .plain);
                if (loop.else_body) |body| try self.checkOwnStatements(body, value_place);
            },
            .@"for" => |*loop| {
                switch (loop.sequence) {
                    .value => |*value| try self.checkOwnValue(value, .plain),
                    .range => |*range| {
                        try self.checkOwnValue(&range.start, .plain);
                        if (range.end) |*end| try self.checkOwnValue(end, .plain);
                    },
                }
                if (loop.iterator) |iteration| {
                    try self.checkCopiedElements(iteration, loop.names);
                } else try self.checkOwnBindings(loop.names);
                try self.checkOwnStatements(loop.body, .plain);
                if (loop.else_body) |body| try self.checkOwnStatements(body, value_place);
            },
            .match => |*matching| {
                try self.checkOwnMatch(matching);
                for (matching.branches) |branch| try self.checkOwnStatements(branch.body, value_place);
            },
            .@"defer" => |deferred| try self.checkOwnStatement(deferred.statement, .plain),
        }
    }

    fn checkOwnValue(self: *TypeChecker, expression: *ast.Expression, place: OwnPlace) TypeError!void {
        if (place != .owned and self.isOwnCall(expression.*)) return self.fail(expression.location, error.OwnResultMisplaced);
        if (place == .copied and self.isCopiedOwningValue(expression.*)) return self.fail(expression.location, error.OwnValueCopied);
        switch (expression.kind) {
            .call => |*call| {
                if (ast.extractResolution(call.callee) == .case) return self.checkOwnParts(expression.location, call.arguments, place);
                try self.checkOwnArguments(call.arguments, self.findCallParameters(call.*), findCalleeName(call.callee));
            },
            .@"try" => |operand| try self.checkOwnValue(operand, place),
            .binary => |*binary| {
                const passes = binary.operator == .@"orelse" or binary.operator == .@"catch";
                try self.checkOwnValue(binary.left, if (passes) place else .plain);
                try self.checkOwnValue(binary.right, if (passes) place else .plain);
            },
            .composite_literal => |*literal| {
                const value_type = findLiteralType(expression.type orelse return);
                if (value_type != .@"struct" or value_type.@"struct".@"inline") return self.checkOwnParts(expression.location, literal.elements, place);
                var carries = false;
                for (literal.elements, 0..) |*element, position| {
                    const field = findOwnField(value_type.@"struct".fields, element.name, position);
                    if (field != null and field.?.own) {
                        if (self.carriesOwned(element.*)) carries = true;
                        try self.checkOwnArgument(element);
                        continue;
                    }
                    if (element.own) return self.fail(element.location, error.OwnMarkerMisplaced);
                    try self.checkOwnValue(&element.value, .copied);
                }
                if (carries and place != .owned) return self.fail(expression.location, error.OwnResultMisplaced);
            },
            .case_literal => |*literal| try self.checkOwnParts(expression.location, literal.arguments, place),
            .branching => |statement| try self.checkOwnStatement(statement, place),
            .negation, .address_of, .dereference, .unwrap => |operand| try self.checkOwnValue(operand, .plain),
            .unary => |*unary| try self.checkOwnValue(unary.operand, .plain),
            .field_access => |*access| try self.checkOwnValue(access.value, .plain),
            .index => |*indexing| {
                try self.checkOwnValue(indexing.value, .plain);
                try self.checkOwnValue(indexing.index, .plain);
            },
            .slice => |*slice| {
                try self.checkOwnValue(slice.value, .plain);
                if (slice.start) |start| try self.checkOwnValue(start, .plain);
                if (slice.end) |end| try self.checkOwnValue(end, .plain);
            },
            .range => |range| {
                try self.checkOwnValue(&range.start, .plain);
                if (range.end) |*end| try self.checkOwnValue(end, .plain);
            },
            .jump => |statement| try self.checkOwnStatement(statement, .plain),
            .integer_literal,
            .float_literal,
            .boolean_literal,
            .string_literal,
            .undefined,
            .null,
            .identifier,
            .path_expression,
            .member,
            .method_call,
            .array_type,
            .inferred_type,
            .slice_type,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            => {},
        }
    }

    fn checkOwnBranchValue(self: *TypeChecker, value: *ast.Expression, place: OwnPlace) TypeError!void {
        if (place == .owned or value.handed) return self.checkOwnDestination(value, place == .owned, value.handed, value.location);
        try self.checkOwnValue(value, place);
    }

    fn checkOwnParts(self: *TypeChecker, location: token.Location, parts: []ast.Argument, place: OwnPlace) TypeError!void {
        var carries = false;
        for (parts) |*part| {
            if ((place == .owned or part.own) and self.canOwnValue(part.value)) {
                if (self.carriesOwned(part.*)) carries = true;
                try self.checkOwnArgument(part);
                continue;
            }
            if (part.own and place != .owned) return self.fail(part.location, error.OwnMarkerMisplaced);
            try self.checkOwnValue(&part.value, if (place == .owned) .owned else .copied);
        }
        if (carries and place != .owned) return self.fail(location, error.OwnResultMisplaced);
    }

    fn carriesOwned(self: *const TypeChecker, part: ast.Argument) bool {
        return (part.own and self.canOwnValue(part.value)) or self.isOwnCall(part.value);
    }

    fn checkOwnNaming(self: *TypeChecker, value: *ast.Expression, moved: bool, names: []const ast.ElementName, own: bool) TypeError!void {
        if (own) {
            try self.checkOwnDestination(value, true, moved, value.location);
            return self.checkOwnNames(value.*, names);
        }
        if (moved) return self.fail(value.location, error.OwnMarkerMisplaced);
        try self.checkOwnValue(value, .plain);
        if (self.isCopiedOwningValue(value.*)) try self.checkOwnBindings(names);
    }

    fn checkOwnTest(
        self: *TypeChecker,
        keyword: []const u8,
        value: *ast.Expression,
        marker: ?token.Location,
        names: []const ast.ElementName,
        tuple: bool,
        own: bool,
    ) TypeError!bool {
        if (marker) |location| return self.failMarkedTest(location, keyword, value.*, names, tuple);
        if (!own) {
            try self.checkOwnNaming(value, false, names, false);
            return false;
        }
        const consumes = try self.isConsumedTest(value.*);
        try self.checkOwnNaming(value, consumes, names, true);
        return consumes;
    }

    fn isConsumedTest(self: *TypeChecker, value: ast.Expression) TypeError!bool {
        return self.isOwnName(value) or try self.isOwnedPart(value);
    }

    fn failMarkedTest(
        self: *TypeChecker,
        location: token.Location,
        keyword: []const u8,
        value: ast.Expression,
        names: []const ast.ElementName,
        tuple: bool,
    ) TypeError {
        const failure = self.fail(location, error.OwnMarkerMisplaced);
        const allocator = self.arena.allocator();
        const text = try renderExpression(allocator, value) orelse return failure;
        var form: std.ArrayList(u8) = .empty;
        try form.appendSlice(allocator, keyword);
        try form.append(allocator, ' ');
        try form.appendSlice(allocator, text);
        if (names.len > 0) {
            try form.appendSlice(allocator, " as own ");
            if (tuple) try form.appendSlice(allocator, "{ ");
            for (names, 0..) |name, position| {
                if (position > 0) try form.appendSlice(allocator, ", ");
                if (name.pointer) try form.append(allocator, '*');
                try form.appendSlice(allocator, name.name);
            }
            if (tuple) try form.appendSlice(allocator, " }");
        }
        const format = "own is not written before the value {s} tests: a name tested with as own is taken over at the test; write `{s}`";
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ keyword, form.items });
        return failure;
    }

    fn checkOwnMatch(self: *TypeChecker, matching: *ast.Match) TypeError!void {
        const value = &matching.value;
        if (matching.marker) |location| return self.failMarkedTest(location, "match", value.*, &.{}, false);
        const owned = for (matching.branches) |branch| {
            if (branch.own) break true;
        } else false;
        if (!owned) return self.checkOwnNaming(value, false, matching.names, false);
        matching.moved = try self.isConsumedTest(value.*);
        try self.checkOwnDestination(value, true, matching.moved, value.location);
        if (!self.canOwnValue(value.*)) return;
        const value_type = value.type.?;
        const covered = try self.arena.allocator().alloc(bool, countMatchParts(value_type));
        @memset(covered, false);
        for (matching.branches) |branch| {
            const names = ast.extractBranchNames(matching.*, branch);
            const takes = self.coversOwningPart(value_type, branch, covered);
            if (branch.own) {
                try self.checkOwnNames(value.*, names);
                continue;
            }
            if (takes) try self.checkOwnNaming(value, false, names, false);
        }
    }

    fn coversOwningPart(self: *const TypeChecker, value_type: types.Type, branch: ast.Branch, covered: []bool) bool {
        var takes = false;
        if (branch.cases.len == 0) {
            for (covered, 0..) |done, part| {
                if (!done and self.canOwn(findMatchPart(value_type, part))) takes = true;
            }
            @memset(covered, true);
            return takes;
        }
        for (branch.cases) |case| {
            const part = findCasePart(value_type, case) orelse continue;
            covered[part] = true;
            if (self.canOwn(findMatchPart(value_type, part))) takes = true;
        }
        return takes;
    }

    fn checkOwnNames(self: *TypeChecker, value: ast.Expression, names: []const ast.ElementName) CheckError!void {
        if (!self.canOwnValue(value)) return;
        const held = self.isOwnCall(value) or self.isOwnName(value);
        for (names) |name| {
            if (!ast.isDiscardedName(name.name)) continue;
            const name_type = name.type orelse continue;
            if (self.isOwningType(name_type) or (held and self.canOwn(name_type))) return self.fail(name.location, error.OwnResultMisplaced);
        }
    }

    fn checkOwnBindings(self: *TypeChecker, names: []const ast.ElementName) TypeError!void {
        for (names) |name| {
            if (ast.isDiscardedName(name.name)) continue;
            const name_type = name.type orelse continue;
            if (self.isOwningType(name_type)) return self.fail(name.location, error.OwnValueCopied);
        }
    }

    fn checkCopiedElements(self: *TypeChecker, iteration: ast.Iteration, names: []const ast.ElementName) TypeError!void {
        for (names, 0..) |name, position| {
            if (ast.isDiscardedName(name.name) or !ast.isCopiedElement(iteration, name, position)) continue;
            if (self.isOwningType(name.type.?)) return self.fail(name.location, error.OwnValueCopied);
        }
    }

    fn checkOwnArguments(self: *TypeChecker, arguments: []ast.Argument, parameters: []const ast.TypedName, name: []const u8) TypeError!void {
        for (arguments, 0..) |*argument, position| {
            const own = position < parameters.len and parameters[position].own;
            if (own and argument.receiver) try self.expectHandedReceiver(argument.*, name);
            if (own and self.canOwnValue(argument.value)) {
                try self.expectHandedOver(argument.*, parameters[position]);
                try self.checkOwnArgument(argument);
                continue;
            }
            if (own) {
                try self.checkOwnValue(&argument.value, .owned);
                continue;
            }
            if (argument.own) return self.fail(argument.location, error.OwnMarkerMisplaced);
            try self.checkOwnValue(&argument.value, if (parameters.len == 0) .plain else .copied);
        }
    }

    fn expectHandedReceiver(self: *TypeChecker, argument: ast.Argument, name: []const u8) TypeError!void {
        const held = if (argument.value.kind == .address_of) argument.value.kind.address_of.* else argument.value;
        if (!self.canOwnValue(held)) return;
        const owned = try self.isOwnPlace(held);
        if (argument.own and owned) return;
        if (!argument.own and !owned and self.own_trusted) return;
        const allocator = self.arena.allocator();
        const text = try renderExpression(allocator, held) orelse "the receiver";
        if (argument.own) {
            const failure = self.fail(argument.location, error.OwnMarkerMisplaced);
            const format = "own cannot take `{s}`: `{s}` takes over its receiver, which has to be a name declared own, a part stored inline in one, or a part of what an own pointer parameter points to, e.g. `record.{s}(own)`";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ text, name, name });
            return failure;
        }
        if (owned) {
            const failure = self.fail(argument.location, error.OwnMarkerMissing);
            const format = "`{s}` takes over its receiver, and `{s}` is held by a name declared own; write own as the first argument to hand it on, e.g. `{s}.{s}(own)`";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ name, text, text, name });
            return failure;
        }
        const failure = self.fail(argument.location, error.OwnPointerNotOwned);
        const format = "`{s}` takes over its receiver, but `{s}` is not owned here; the receiver has to be a name declared own, a part stored inline in one, or a part of what an own pointer parameter points to, handed on as `record.{s}(own)`";
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ name, text, name });
        return failure;
    }

    fn checkOwnDestination(self: *TypeChecker, value: *ast.Expression, owned: bool, moved: bool, location: token.Location) TypeError!void {
        if ((owned or moved) and !self.canOwnValue(value.*)) return self.checkOwnValue(value, .owned);
        if (owned) return self.checkOwnAccepted(value, moved, location);
        if (moved and value.handed) return self.failMisplacedBranchMove(value.*);
        if (moved) return self.fail(location, error.OwnMarkerMisplaced);
        try self.checkOwnValue(value, .copied);
    }

    fn checkOwnArgument(self: *TypeChecker, argument: *ast.Argument) TypeError!void {
        return self.checkOwnAccepted(&argument.value, argument.own, argument.location);
    }

    fn checkOwnAccepted(self: *TypeChecker, value: *ast.Expression, moved: bool, location: token.Location) TypeError!void {
        const moved_value = if (value.kind == .address_of) value.kind.address_of.* else value.*;
        if (!self.canOwnValue(moved_value)) return self.checkOwnValue(value, .owned);
        if (moved) {
            if (self.isOwnName(moved_value) or try self.isOwnedPart(moved_value)) return;
            return self.failMisplacedMove(moved_value, location);
        }
        if (try self.isOwnPlace(moved_value)) {
            const failure = self.fail(value.location, error.OwnMarkerMissing);
            const text = try renderExpression(self.arena.allocator(), moved_value) orelse return failure;
            const format = "`{s}` is held by a name declared own; write own before it to hand it on, e.g. `own {s}`";
            self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{ text, text });
            return failure;
        }
        if (!self.own_trusted and !self.isAcceptedOwnValue(value.*)) {
            const failure = self.fail(value.location, error.OwnNeedsClone);
            const text = try renderExpression(self.arena.allocator(), value.*) orelse "this value";
            const format = "`{s}` is a view: this place owns its value, and a view cannot be moved into it; hand on a name declared own with own, or a copy made with clone, e.g. `try value.clone()`";
            self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{text});
            return failure;
        }
        try self.checkOwnValue(value, .owned);
    }

    fn failMisplacedBranchMove(self: *TypeChecker, value: ast.Expression) TypeError {
        const failure = self.fail(value.location, error.OwnMarkerMisplaced);
        const text = try renderExpression(self.arena.allocator(), value) orelse return failure;
        const format = "own before `{s}` hands it on to the place that takes the value of its if or match, and that place is not own; own goes before a branch's value only when the if or match gives the value of an own declaration, an own parameter or field, or the return of an own function, e.g. `else (_ as own rest) own rest` in `const own bytes = try match filesystem::read(path)`";
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{text});
        return failure;
    }

    fn failMisplacedMove(self: *TypeChecker, moved: ast.Expression, location: token.Location) TypeError {
        const allocator = self.arena.allocator();
        if (self.findUnknownIndex(moved)) |index_location| {
            const failure = self.fail(index_location, error.OwnPartIndexUnknown);
            const text = try renderExpression(allocator, moved) orelse return failure;
            const format = "`{s}` takes an element out of an inline array with an index known only at run time, so the compiler cannot tell which part has moved; use an index known at compile time";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{text});
            return failure;
        }
        const failure = self.fail(location, error.OwnMarkerMisplaced);
        const called = if (moved.kind == .@"try") moved.kind.@"try".* else moved;
        if (called.kind == .call) {
            const call = called.kind.call;
            if (call.arguments.len == 0 or !call.arguments[0].receiver) return failure;
            const receiver = call.arguments[0].value;
            const held = if (receiver.kind == .address_of) receiver.kind.address_of.* else receiver;
            const text = try renderExpression(allocator, held) orelse return failure;
            const name = findCalleeName(call.callee);
            const format = "own before a call hands on what the call gives; to hand `{s}` to `{s}`, which takes over its receiver, write own as the call's first argument, e.g. `{s}.{s}(own)`";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ text, name, text, name });
            return failure;
        }
        const text = try renderExpression(allocator, moved) orelse return failure;
        const format = "own cannot take `{s}`: own takes a name declared own or a part stored inline in one, e.g. `own record` or `own record.path`, and nothing reached through a pointer or a slice is such a part";
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{text});
        return failure;
    }

    fn expectHandedOver(self: *TypeChecker, argument: ast.Argument, parameter: ast.TypedName) TypeError!void {
        if (self.own_trusted or argument.own) return;
        const value = argument.value;
        const value_type = value.type orelse return;
        if (self.isOwnCall(value)) return;
        const allocator = self.arena.allocator();
        if (isOwnPointerParameter(parameter)) {
            if (value_type != .pointer or !self.canOwn(value_type.pointer.target)) return;
            const handed = if (value.kind == .address_of) value.kind.address_of.* else value;
            if (try self.isOwnPlace(handed)) return;
            const failure = self.fail(value.location, error.OwnPointerNotOwned);
            const text = try renderExpression(allocator, value) orelse "this pointer";
            const format = "`{s}` hands nothing over: the own pointer parameter `{s}` takes `own &name` for a name declared own, or `own &name.part` for a part of one, e.g. `own &record`";
            self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ text, parameter.name });
            return failure;
        }
    }

    fn isAcceptedOwnValue(self: *TypeChecker, expression: ast.Expression) bool {
        if (self.isOwnCall(expression) or isBranchingValue(expression)) return true;
        const value_type = expression.type orelse return true;
        if (!self.canOwn(value_type)) return true;
        return switch (expression.kind) {
            .undefined, .null => true,
            .composite_literal => |literal| {
                const literal_type = findLiteralType(value_type);
                if (literal_type == .slice or literal_type == .pointer) return literal.elements.len == 0;
                return true;
            },
            .case_literal => true,
            .call => |call| ast.extractResolution(call.callee) == .case,
            else => false,
        };
    }

    fn isOwnCall(self: *const TypeChecker, expression: ast.Expression) bool {
        return switch (expression.kind) {
            .call => |call| {
                const resolution = ast.extractResolution(call.callee);
                return switch (resolution) {
                    .function, .typeclass_function, .typeclass_method => self.extractSignature(resolution).return_own and self.canOwnValue(expression),
                    .parameter, .type, .constant, .local, .element, .case, .builtin => false,
                };
            },
            .@"try" => |operand| self.isOwnCall(operand.*),
            .binary => |binary| (binary.operator == .@"orelse" or binary.operator == .@"catch") and self.isOwnCall(binary.left.*),
            else => false,
        };
    }

    fn isCopiedOwningValue(self: *const TypeChecker, expression: ast.Expression) bool {
        const value_type = expression.type orelse return false;
        if (!self.isOwningType(value_type)) return false;
        return switch (expression.kind) {
            .identifier => |identifier| isStoredResolution(identifier.resolution),
            .path_expression => |path_expression| isStoredResolution(path_expression.resolution),
            .field_access, .index, .dereference, .unwrap => true,
            .@"try" => |operand| self.isCopiedOwningValue(operand.*),
            .binary => |binary| (binary.operator == .@"orelse" or binary.operator == .@"catch") and self.isCopiedOwningValue(binary.left.*),
            else => false,
        };
    }

    fn canOwnValue(self: *const TypeChecker, expression: ast.Expression) bool {
        const value_type = expression.type orelse return true;
        return self.canOwn(value_type);
    }

    fn canOwn(_: *const TypeChecker, value_type: types.Type) bool {
        return types.canOwn(value_type);
    }

    fn isOwnName(self: *const TypeChecker, expression: ast.Expression) bool {
        if (expression.kind != .identifier) return false;
        if (!self.canOwnValue(expression)) return false;
        return switch (expression.kind.identifier.resolution orelse return false) {
            .local => |statement| switch (statement.kind) {
                .constant_declaration => |constant| constant.own,
                .variable_declaration => |variable| variable.own,
                else => false,
            },
            .parameter => |index| index < self.signature.?.parameters.len and self.signature.?.parameters[index].own,
            .element => |element| ast.isOwnElement(element),
            else => false,
        };
    }

    fn findCallParameters(self: *const TypeChecker, call: ast.Call) []const ast.TypedName {
        const resolution = ast.extractResolution(call.callee);
        return switch (resolution) {
            .function, .typeclass_function, .typeclass_method => self.extractSignature(resolution).parameters,
            .parameter, .type, .constant, .local, .element, .case, .builtin => &.{},
        };
    }

    fn isOwningType(_: *const TypeChecker, value_type: types.Type) bool {
        return types.isOwning(value_type);
    }

    fn checkInlineRecursion(self: *TypeChecker) TypeError!void {
        const allocator = self.arena.allocator();
        for (self.program.modules, 0..) |module, module_index| {
            for (0..module.declarations.len + module.instances.items.len) |declaration_index| {
                const declaration = ast.findDeclaration(module, declaration_index);
                if (declaration.kind != .function_definition) continue;
                const definition = &declaration.kind.function_definition;
                if (!definition.signature.@"inline" or definition.check_progress != .done) continue;
                const start: ast.Resolution.Function = .{ .module = module_index, .declaration = declaration_index };
                var calls: std.ArrayList(FunctionCall) = .empty;
                try appendBlockCalls(allocator, &calls, definition.body);
                for (calls.items) |call| {
                    var visited: std.ArrayList(ast.Resolution.Function) = .empty;
                    if (!std.meta.eql(call.function, start) and !try self.reachesFunction(&visited, call.function, start)) continue;
                    self.module_index = module_index;
                    self.current_function = start;
                    return self.fail(call.location, error.InlineRecursion);
                }
            }
        }
    }

    fn reachesFunction(
        self: *TypeChecker,
        visited: *std.ArrayList(ast.Resolution.Function),
        from: ast.Resolution.Function,
        target: ast.Resolution.Function,
    ) std.mem.Allocator.Error!bool {
        for (visited.items) |earlier| {
            if (std.meta.eql(earlier, from)) return false;
        }
        const allocator = self.arena.allocator();
        try visited.append(allocator, from);
        const declaration = ast.findDeclaration(self.program.modules[from.module], from.declaration);
        if (declaration.kind != .function_definition) return false;
        var calls: std.ArrayList(FunctionCall) = .empty;
        try appendBlockCalls(allocator, &calls, declaration.kind.function_definition.body);
        for (calls.items) |call| {
            if (std.meta.eql(call.function, target)) return true;
            if (try self.reachesFunction(visited, call.function, target)) return true;
        }
        return false;
    }

    pub fn findCreatingCall(self: *const TypeChecker, function: ast.Resolution.Function) ?InstanceCall {
        for (self.instances.items) |instance| {
            if (std.meta.eql(instance.function, function)) return instance.call;
        }
        for (self.allocator_calls.items) |recorded| {
            if (std.meta.eql(recorded.function, function)) return recorded.call;
        }
        return null;
    }

    pub fn prepareFunction(self: *TypeChecker, function: ast.Resolution.Function) TypeError!void {
        errdefer if (self.failed_function == null) {
            self.failed_function = function;
        };
        const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
        const definition = &declaration.kind.function_definition;
        switch (definition.check_progress) {
            .done => return,
            .running => {
                self.module_index = function.module;
                return self.fail(declaration.location, error.DependencyLoop);
            },
            .pending => {},
        }
        if (definition.signature.@"inline" and ast.isMain(definition.signature)) {
            self.module_index = function.module;
            return self.fail(declaration.location, error.InlineMain);
        }
        if (definition.signature.private and ast.isMain(definition.signature)) {
            self.module_index = function.module;
            return self.fail(declaration.location, error.PrivateMain);
        }
        if (self.resolver) |*resolver| try resolver.resolve(resolver.context, function);
        definition.check_progress = .running;
        const caller_module_index = self.module_index;
        const caller_constraints = self.constraints;
        const caller_instance_depth = self.instance_depth;
        const caller_quiet_operations = self.quiet_operations;
        const caller_current_function = self.current_function;
        const caller_allocator_type = self.allocator_type;
        const caller_allocator_root = self.allocator_root;
        const caller_context_allocator = self.context_allocator;
        defer self.context_allocator = caller_context_allocator;
        self.context_allocator = null;
        defer self.current_function = caller_current_function;
        defer self.allocator_type = caller_allocator_type;
        defer self.allocator_root = caller_allocator_root;
        self.current_function = function;
        self.allocator_type = if (definition.allocator) |given| given.* else null;
        self.allocator_root = definition.allocator_root;
        defer self.module_index = caller_module_index;
        defer self.constraints = caller_constraints;
        defer self.instance_depth = caller_instance_depth;
        defer self.quiet_operations = caller_quiet_operations;
        self.module_index = function.module;
        self.constraints = definition.constraints;
        self.instance_depth = self.findInstanceDepth(function);
        self.quiet_operations = 0;
        try self.checkInferringFunction(definition);
        definition.check_progress = .done;
    }

    fn checkInferringFunction(self: *TypeChecker, definition: *ast.FunctionDefinition) TypeError!void {
        const caller_inferring = self.inferring;
        const caller_deferring = self.deferring;
        defer self.inferring = caller_inferring;
        defer self.deferring = caller_deferring;
        self.inferring = definition.signature.error_set;
        self.deferring = false;
        const error_set = definition.signature.error_set orelse return self.checkBody(definition);
        if (ast.extractType(definition.signature.return_type).result.error_set != error_set) return self.checkBody(definition);
        const allocator = self.arena.allocator();
        try self.inferring_functions.append(allocator, definition);
        errdefer _ = self.inferring_functions.pop();
        try self.checkBody(definition);
        _ = self.inferring_functions.pop();
        try self.completeGroup(definition);
        try self.completeErrorSet(definition);
    }

    fn checkBody(self: *TypeChecker, definition: *ast.FunctionDefinition) TypeError!void {
        if (definition.default_of) |typeclass| return self.checkDefault(definition.*, typeclass, definition.instance_arguments);
        return self.checkFunction(definition.*);
    }

    fn completeErrorSet(self: *TypeChecker, definition: *ast.FunctionDefinition) std.mem.Allocator.Error!void {
        const error_set = definition.signature.error_set.?;
        const value_type = ast.extractType(definition.signature.return_type).result.value;
        const result = try self.program.types.addResult(self.arena.allocator(), try self.combineErrorSets(error_set), value_type);
        definition.signature.return_type.denoted = .{ .result = result };
    }

    fn completeGroup(self: *TypeChecker, head: *ast.FunctionDefinition) TypeError!void {
        const allocator = self.arena.allocator();
        var members: std.ArrayList(*ast.FunctionDefinition) = .empty;
        for (self.groups.items) |grouped| {
            if (grouped.head != head or grouped.member == head) continue;
            if (std.mem.findScalar(*ast.FunctionDefinition, members.items, grouped.member) == null) try members.append(allocator, grouped.member);
        }
        if (members.items.len == 0 and !self.isGroupHead(head)) return;
        const caller_rechecking = self.rechecking;
        defer self.rechecking = caller_rechecking;
        self.rechecking = true;
        var sizes: std.ArrayList(usize) = .empty;
        while (true) {
            sizes.clearRetainingCapacity();
            try sizes.append(allocator, countInferred(head.signature.error_set.?));
            for (members.items) |member| try sizes.append(allocator, countInferred(member.signature.error_set.?));
            try self.restartGroup(members.items, false);
            try self.inferring_functions.append(allocator, head);
            errdefer _ = self.inferring_functions.pop();
            try self.checkBody(head);
            _ = self.inferring_functions.pop();
            const grown = for (members.items, sizes.items[1..]) |member, size| {
                if (countInferred(member.signature.error_set.?) != size) break true;
            } else countInferred(head.signature.error_set.?) != sizes.items[0];
            if (!grown) break;
        }
        try self.completeErrorSet(head);
        try self.restartGroup(members.items, true);
        const caller_inferring = self.inferring;
        defer self.inferring = caller_inferring;
        self.inferring = null;
        try self.checkBody(head);
    }

    fn isGroupHead(self: *const TypeChecker, head: *ast.FunctionDefinition) bool {
        for (self.groups.items) |grouped| {
            if (grouped.head == head) return true;
        }
        return false;
    }

    fn restartGroup(self: *TypeChecker, members: []const *ast.FunctionDefinition, complete: bool) std.mem.Allocator.Error!void {
        for (members) |member| {
            member.check_progress = .pending;
            if (complete) {
                try self.completeErrorSet(member);
                continue;
            }
            const value_type = ast.extractType(member.signature.return_type).result.value;
            const result = try self.program.types.addResult(self.arena.allocator(), member.signature.error_set.?, value_type);
            member.signature.return_type.denoted = .{ .result = result };
        }
    }

    fn combineErrorSets(self: *TypeChecker, error_set: *const types.Enum) std.mem.Allocator.Error!*const types.Enum {
        if (!types.hasWholeParts(error_set)) return self.program.types.addErrorCases(self.arena.allocator(), error_set.cases);
        const parts = error_set.parts;
        if (parts.len == 0) return self.findEmptyErrorSet();
        var combined = parts[0];
        for (parts[1..]) |part| combined = try self.program.types.addCombined(self.arena.allocator(), combined, part);
        return combined;
    }

    fn findEmptyErrorSet(self: *TypeChecker) std.mem.Allocator.Error!*const types.Enum {
        if (self.empty_error_set) |error_set| return error_set;
        const error_set = try self.arena.allocator().create(types.Enum);
        error_set.* = .{ .module = 0, .name = "", .kind = .error_set };
        self.empty_error_set = error_set;
        return error_set;
    }

    fn completeInferredErrorSet(self: *TypeChecker, resolution: ast.Resolution) TypeError!void {
        if (resolution != .function) return;
        const function = resolution.function;
        const declaration = ast.findDeclaration(self.program.modules[function.module], function.declaration);
        if (declaration.kind != .function_definition) return;
        const definition = &declaration.kind.function_definition;
        if (definition.pattern) return;
        const error_set = definition.signature.error_set orelse return;
        if (ast.extractType(definition.signature.return_type).result.error_set != error_set) return;
        if (definition.check_progress == .running) return self.recordGroup(definition);
        try self.prepareFunction(function);
    }

    fn recordGroup(self: *TypeChecker, head: *ast.FunctionDefinition) std.mem.Allocator.Error!void {
        const position = std.mem.findScalar(*ast.FunctionDefinition, self.inferring_functions.items, head) orelse return;
        const allocator = self.arena.allocator();
        try self.groups.append(allocator, .{ .head = head, .member = head });
        for (self.inferring_functions.items[position + 1 ..]) |member| try self.groups.append(allocator, .{ .head = head, .member = member });
    }

    fn recordInferredErrors(self: *TypeChecker, value_type: types.Type, expected: types.Type) std.mem.Allocator.Error!void {
        const inferring = self.inferring orelse return;
        if (expected != .result or expected.result.error_set != inferring) return;
        const error_set = findErrorSet(value_type) orelse return;
        const allocator = self.arena.allocator();
        var parts: std.ArrayList(*const types.Enum) = .empty;
        var cases: std.ArrayList(types.Case) = .empty;
        try parts.appendSlice(allocator, inferring.parts);
        try cases.appendSlice(allocator, inferring.cases);
        for (error_set.parts) |part| {
            if (std.mem.findScalar(*const types.Enum, parts.items, part) == null) try parts.append(allocator, part);
        }
        for (error_set.cases) |case| {
            if (!types.containsCase(inferring, case)) try cases.append(allocator, case);
        }
        inferring.parts = parts.items;
        inferring.cases = cases.items;
    }

    fn isInferring(self: *const TypeChecker, return_type: types.Type) bool {
        const inferring = self.inferring orelse return false;
        return return_type == .result and return_type.result.error_set == inferring;
    }

    pub fn isKnown(self: *TypeChecker, modules: []ast.Module, expression: ast.Expression) bool {
        self.program.modules = modules;
        self.evaluator.program = self.program;
        return self.evaluator.isKnown(expression);
    }

    pub fn evaluateKnown(
        self: *TypeChecker,
        modules: []ast.Module,
        module_index: usize,
        expression: *ast.Expression,
        expected: types.Type,
    ) TypeError!Value {
        self.program.modules = modules;
        const caller_module_index = self.module_index;
        const caller_compile_time = self.compile_time;
        self.module_index = module_index;
        self.compile_time = true;
        defer self.module_index = caller_module_index;
        defer self.compile_time = caller_compile_time;
        try self.checkExpression(&.{}, expression, expected);
        if (!self.evaluator.isKnown(expression.*)) return self.fail(expression.location, error.CannotEvaluate);
        return self.evaluateValue(expression);
    }

    pub fn checkKnown(
        self: *TypeChecker,
        modules: []ast.Module,
        module_index: usize,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        self.program.modules = modules;
        const caller_module_index = self.module_index;
        const caller_compile_time = self.compile_time;
        self.module_index = module_index;
        self.compile_time = true;
        defer self.module_index = caller_module_index;
        defer self.compile_time = caller_compile_time;
        try self.checkExpression(parameters, expression, expected);
    }

    pub fn evaluateChecked(self: *TypeChecker, module_index: usize, expression: *const ast.Expression) TypeError!Value {
        const caller_module_index = self.module_index;
        self.module_index = module_index;
        defer self.module_index = caller_module_index;
        if (!self.evaluator.isKnown(expression.*)) return self.fail(expression.location, error.CannotEvaluate);
        return self.evaluateValue(expression);
    }

    pub fn chooseCondition(
        self: *TypeChecker,
        modules: []ast.Module,
        module_index: usize,
        condition: *ast.Expression,
    ) TypeError!?bool {
        self.program.modules = modules;
        const caller_module_index = self.module_index;
        self.module_index = module_index;
        defer self.module_index = caller_module_index;
        try self.checkExpression(&.{}, condition, .boolean);
        return self.decideCondition(condition);
    }

    pub fn checkKnownConstant(
        self: *TypeChecker,
        modules: []ast.Module,
        module_index: usize,
        constant: *ast.ConstantDeclaration,
    ) TypeError!types.Type {
        self.program.modules = modules;
        const caller_module_index = self.module_index;
        const caller_compile_time = self.compile_time;
        self.module_index = module_index;
        self.compile_time = true;
        defer self.module_index = caller_module_index;
        defer self.compile_time = caller_compile_time;
        const written = if (constant.type) |*written| written else null;
        return self.checkDeclaredValue(&.{}, written, &constant.value);
    }

    fn checkDefault(
        self: *TypeChecker,
        function: ast.FunctionDefinition,
        typeclass: ast.Resolution.Typeclass,
        arguments: []const types.Argument,
    ) TypeError!void {
        const caller_module_index = self.module_index;
        const caller_constraints = self.constraints;
        self.module_index = typeclass.module;
        defer self.module_index = caller_module_index;
        defer self.constraints = caller_constraints;
        const constraint: ast.Constraint = .{ .typeclass = typeclass, .arguments = arguments };
        self.constraints = try self.expandConstraints(&.{constraint});
        try self.checkFunction(function);
    }

    fn expandConstraints(self: *TypeChecker, constraints: []const ast.Constraint) TypeError![]const ast.Constraint {
        const resolver = self.resolver orelse return self.arena.allocator().dupe(ast.Constraint, constraints);
        return resolver.expandConstraints(resolver.context, constraints);
    }

    fn buildOwnArguments(self: *TypeChecker, definition: ast.TypeclassDefinition) TypeError![]const types.Argument {
        const arguments = try self.arena.allocator().alloc(types.Argument, definition.parameters.len);
        for (definition.parameters, arguments, 0..) |parameter, *argument, index| {
            const variable: types.Variable = .{ .scope = .typeclass, .index = index };
            argument.* = if (parameter.arity == 0) .{ .type = .{ .variable = variable } } else .{ .constructor = .{ .variable = variable } };
        }
        return arguments;
    }

    fn checkFieldDefaults(self: *TypeChecker, struct_type: types.Struct) TypeError!void {
        const caller_module_index = self.module_index;
        const caller_compile_time = self.compile_time;
        const caller_return_type = self.return_type;
        self.module_index = struct_type.module;
        self.compile_time = true;
        self.return_type = null;
        defer self.module_index = caller_module_index;
        defer self.compile_time = caller_compile_time;
        defer self.return_type = caller_return_type;
        for (struct_type.fields) |field| {
            const default = field.default orelse continue;
            if (field.default_value.?.* != null) continue;
            try self.checkExpression(&.{}, default, field.type);
            self.prepareEvaluator();
            _ = self.evaluator.evaluateDefault(struct_type, field) catch |evaluate_error| {
                self.adoptEvaluatorFailure();
                return evaluate_error;
            };
        }
    }

    fn checkFunction(self: *TypeChecker, function: ast.FunctionDefinition) TypeError!void {
        const signature = function.signature;
        for (signature.parameters) |parameter| {
            if (types.isCompileTimeOnly(ast.extractType(parameter.type))) {
                return self.fail(parameter.location, error.TypeParameter);
            }
        }
        try self.checkParameterDefaults(signature.parameters);
        const caller_compile_time = self.compile_time;
        const caller_compile_time_function = self.compile_time_function;
        const caller_return_type = self.return_type;
        const caller_signature = self.signature;
        defer self.compile_time = caller_compile_time;
        defer self.compile_time_function = caller_compile_time_function;
        defer self.return_type = caller_return_type;
        defer self.signature = caller_signature;
        self.signature = &function.signature;
        self.compile_time_function = types.isCompileTimeOnly(ast.extractType(signature.return_type));
        self.compile_time = self.compile_time_function;
        self.return_type = ast.extractType(signature.return_type);
        if (ast.isMain(signature)) {
            if (!returnsNoValue(ast.extractType(signature.return_type))) {
                return self.fail(signature.return_type.location, error.MainHasReturnType);
            }
            if (signature.parameters.len > 0) {
                return self.fail(signature.parameters[0].location, error.MainHasParameters);
            }
        }

        try self.checkFunctionBody(signature, function.body);
        if (function.lenient) return;
        var trace: Trace = .{};
        const flow = try self.traceBlock(&trace, function.body, .reached);
        try self.checkDeferredUses(function.body);

        const return_type = signature.return_type;
        if (returnsNoValue(ast.extractType(return_type))) return;
        if (flow != .ended) return self.fail(return_type.location, error.MissingReturn);
    }

    fn checkFunctionBody(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        body: []ast.Statement,
    ) TypeError!void {
        const return_type = ast.extractType(signature.return_type);
        if (return_type == .void or body.len == 0) return self.checkBlock(signature, body);
        var production: Production = .{
            .expected = return_type,
            .result = true,
            .ends_with_void = isConvertible(.void, return_type),
        };
        const caller_production = self.production;
        self.production = &production;
        defer self.production = caller_production;
        const last = &body[body.len - 1];
        switch (last.kind) {
            .value, .@"if", .match => try self.prepareValueLine(last),
            .call => |expression| {
                if (!ast.isComptimeErrorCall(self.program.modules[self.module_index], expression)) {
                    last.kind = .{ .value = expression };
                }
            },
            .noop,
            .@"return",
            .discard,
            .constant_declaration,
            .tuple_declaration,
            .variable_declaration,
            .assignment,
            .@"while",
            .@"for",
            .@"defer",
            .@"break",
            .@"continue",
            => {},
        }
        try self.checkProducingBlock(signature, body, true);
    }

    fn prepareValueLine(self: *TypeChecker, statement: *ast.Statement) CheckError!void {
        switch (statement.kind) {
            .value, .@"return", .@"break", .@"continue" => {},
            .call => |expression| {
                if (ast.isComptimeErrorCall(self.program.modules[self.module_index], expression)) return;
                statement.kind = .{ .value = expression };
            },
            .@"if" => |*conditional| conditional.produces = true,
            .match => |*matching| matching.produces = true,
            .@"while", .@"for" => {
                if (self.endsWithVoid()) return;
                const production = self.production orelse return self.fail(statement.location, error.MissingBranchValue);
                if (!production.result or !isEndless(statement.*)) return self.fail(statement.location, error.MissingBranchValue);
            },
            .noop,
            .discard,
            .constant_declaration,
            .tuple_declaration,
            .variable_declaration,
            .assignment,
            .@"defer",
            => if (!self.endsWithVoid()) {
                const production = self.production orelse return self.fail(statement.location, error.MissingBranchValue);
                if (!production.combining) return self.fail(statement.location, error.MissingBranchValue);
                production.void_line = production.void_line orelse statement.location;
            },
        }
    }

    fn endsWithVoid(self: *const TypeChecker) bool {
        const production = self.production orelse return false;
        return production.ends_with_void;
    }

    fn checkBranching(
        self: *TypeChecker,
        expression: *ast.Expression,
        expected: ?types.Type,
    ) TypeError!types.Type {
        const statement = expression.kind.branching;
        var production: Production = .{ .expected = expected, .combining = statement.kind == .match };
        const caller_production = self.production;
        self.production = &production;
        defer self.production = caller_production;
        try self.prepareValueLine(statement);
        const signature = self.signature orelse &top_level_signature;
        try self.checkStatement(signature.*, statement);
        const value_type = try self.findProducedType(&production) orelse expected orelse {
            return self.fail(production.void_line orelse expression.location, if (production.void_line != null) error.MissingBranchValue else error.UnreachableCode);
        };
        if (production.void_line) |location| {
            if (value_type != .result or value_type.result.value != .void) return self.fail(location, error.MissingBranchValue);
        }
        if (statement.kind == .match) statement.kind.match.gives_void = production.void_line != null;
        expression.type = value_type;
        return value_type;
    }

    fn findProducedType(self: *TypeChecker, production: *const Production) CheckError!?types.Type {
        if (production.expected != null) return null;
        const mixed = production.mixed orelse {
            if (production.void_line == null) return production.found;
            const error_set = production.errors orelse return production.found;
            if (production.value != null) return production.found;
            return .{ .result = try self.program.types.addResult(self.arena.allocator(), error_set, .void) };
        };
        const value_type = production.value orelse if (production.void_line != null) types.Type.void else return self.fail(mixed, error.BranchTypeMismatch);
        const error_set = production.errors.?;
        return .{ .result = try self.program.types.addResult(self.arena.allocator(), error_set, value_type) };
    }

    fn recordProducedParts(
        self: *TypeChecker,
        production: *Production,
        location: token.Location,
        value_type: types.Type,
    ) CheckError!void {
        const allocator = self.arena.allocator();
        const error_set = findErrorSet(value_type);
        const value: ?types.Type = switch (value_type) {
            .result => |result| result.value,
            .@"enum" => |enumeration| if (enumeration.kind == .error_set) null else value_type,
            else => value_type,
        };
        if (value) |found| {
            if (production.value) |earlier| {
                if (!std.meta.eql(earlier, found)) return self.fail(location, error.BranchTypeMismatch);
            }
            production.value = found;
        }
        if (error_set) |found| {
            production.errors = if (production.errors) |earlier| try self.program.types.addCombined(allocator, earlier, found) else found;
        }
    }

    fn checkProducedValue(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        statement: *ast.Statement,
    ) TypeError!void {
        const expression = &statement.kind.value;
        const production = self.production orelse {
            if (expression.handed) return self.failMisplacedBranchMove(expression.*);
            if (expression.kind == .case_literal) return self.fail(expression.location, error.CaseWithoutKnownEnum);
            return self.fail(expression.location, error.UnusedValue);
        };
        if (production.expected) |expected| recordExpectedType(expression, expected);
        if (isCallOrTriedCall(expression.*)) {
            const value_type = try self.inferType(parameters, expression);
            if (value_type == .void) {
                if (production.result) {
                    statement.kind = .{ .call = expression.* };
                    return;
                }
                if (!production.combining) return self.fail(expression.location, error.MissingBranchValue);
                production.void_line = production.void_line orelse expression.location;
                statement.kind = .{ .call = expression.* };
                return;
            }
            try self.acceptProduced(production, expression.location, value_type);
        } else if (production.expected) |expected| {
            try self.checkExpression(parameters, expression, expected);
        } else {
            try self.acceptProduced(production, expression.location, try self.inferType(parameters, expression));
        }
        if (production.result) statement.kind = .{ .@"return" = expression.* };
    }

    fn acceptProduced(
        self: *TypeChecker,
        production: *Production,
        location: token.Location,
        value_type: types.Type,
    ) CheckError!void {
        if (production.expected) |expected| {
            try self.recordInferredErrors(value_type, expected);
            if (!isConvertible(value_type, expected)) return self.fail(location, error.TypeMismatch);
            return;
        }
        if (production.combining) try self.recordProducedParts(production, location, value_type);
        const found = production.found orelse {
            production.found = value_type;
            return;
        };
        if (std.meta.eql(found, value_type)) return;
        if (!production.combining) return self.fail(location, error.BranchTypeMismatch);
        production.mixed = production.mixed orelse location;
    }

    fn checkBranchBlock(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        statements: []ast.Statement,
        produces: bool,
    ) TypeError!void {
        if (!produces or statements.len == 0) return self.checkBlock(signature, statements);
        try self.prepareValueLine(&statements[statements.len - 1]);
        try self.checkProducingBlock(signature, statements, true);
    }

    fn traceBlock(
        self: *TypeChecker,
        trace: *Trace,
        statements: []const ast.Statement,
        entry: Flow,
    ) TypeError!Flow {
        var flow = entry;
        for (statements) |*statement| {
            if (flow == .ended) return self.fail(statement.location, error.UnreachableStatement);
            flow = try self.traceStatement(trace, statement, flow);
        }
        if (flow == .ended) return flow;
        var index = statements.len;
        while (index > 0) {
            index -= 1;
            const statement = statements[index];
            if (statement.kind != .@"defer") continue;
            flow = try self.traceStatement(trace, statement.kind.@"defer".statement, flow);
        }
        return flow;
    }

    fn traceStatement(
        self: *TypeChecker,
        trace: *Trace,
        statement: *const ast.Statement,
        flow: Flow,
    ) TypeError!Flow {
        var branchings: std.ArrayList(*ast.Statement) = .empty;
        try ast.collectStatementBranchings(self.arena.allocator(), &branchings, statement);
        for (branchings.items) |inner| {
            const produced = try self.traceStatement(trace, inner, flow);
            if (produced == .ended) return self.fail(statement.location, error.UnreachableCode);
        }
        var jumps: std.ArrayList(*ast.Statement) = .empty;
        try ast.collectStatementJumps(self.arena.allocator(), &jumps, statement);
        for (jumps.items) |jump| {
            if (jump.kind != .@"break") continue;
            mergeExit(trace, jump.kind.@"break".loop.?, flow);
        }
        switch (statement.kind) {
            .call => |expression| {
                if (ast.isComptimeErrorCall(self.program.modules[self.module_index], expression)) return .ended;
                return flow;
            },
            .noop, .discard, .constant_declaration, .tuple_declaration, .@"defer", .value => return flow,
            .variable_declaration, .assignment => return flow,
            .@"return", .@"continue" => return .ended,
            .@"break" => |jump| {
                mergeExit(trace, jump.loop.?, flow);
                return .ended;
            },
            .@"if" => |conditional| {
                if (conditional.known) |chosen| {
                    const block = if (chosen) conditional.body else conditional.else_body orelse &.{};
                    const kept = try self.traceBlock(trace, block, flow);
                    if (conditional.dropped_ends or conditional.produces) return kept;
                    return mergeFlows(kept, flow);
                }
                const body = try self.traceBlock(trace, conditional.body, flow);
                const else_body = conditional.else_body orelse return mergeFlows(body, flow);
                return mergeFlows(body, try self.traceBlock(trace, else_body, flow));
            },
            .@"for", .@"while" => return self.traceLoop(trace, statement, flow),
            .match => |matching| {
                var merged: Flow = .ended;
                for (matching.branches) |branch| {
                    merged = mergeFlows(merged, try self.traceBlock(trace, branch.body, flow));
                }
                return merged;
            },
        }
    }

    fn traceLoop(
        self: *TypeChecker,
        trace: *Trace,
        statement: *const ast.Statement,
        flow: Flow,
    ) TypeError!Flow {
        const body, const else_body = ast.extractBlocks(statement.*);
        try trace.exits.append(self.arena.allocator(), .{ .loop = statement });
        _ = try self.traceBlock(trace, body, flow);
        const exit = trace.exits.pop().?.flow;
        const finished: Flow = if (isEndless(statement.*)) .ended else flow;
        return mergeFlows(try self.traceBlock(trace, else_body, finished), exit);
    }

    fn checkDeferredUses(self: *TypeChecker, body: []const ast.Statement) TypeError!void {
        for (body) |*statement| {
            if (ast.findBranching(statement)) |inner| try self.checkDeferredUses(inner[0..1]);
            var blocks = ast.iterateBlocks(statement.*);
            while (blocks.next()) |block| try self.checkDeferredUses(block);
        }
        for (body, 0..) |*statement, index| {
            if (statement.kind != .variable_declaration) continue;
            var use = statement.kind.variable_declaration.deferred_use orelse continue;
            recordTargetUses(&use, statement, body[index + 1 ..]);
            if (!use.modified) return self.fail(statement.location, error.NeverModified);
            if (use.discard) |discard| {
                if (use.used) return self.fail(discard, error.PointlessDiscard);
            } else if (!use.used) {
                return self.fail(statement.location, error.UnusedVariable);
            }
        }
    }

    fn checkExternalFunction(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
    ) TypeError!void {
        if (ast.isMain(signature)) {
            return self.fail(location, error.MainIsExternal);
        }
        for (signature.parameters) |parameter| {
            if (types.isCompileTimeOnly(ast.extractType(parameter.type))) {
                return self.fail(parameter.location, error.TypeParameter);
            }
        }
        if (types.isCompileTimeOnly(ast.extractType(signature.return_type))) {
            return self.fail(signature.return_type.location, error.CompileTimeValue);
        }
        try self.checkParameterDefaults(signature.parameters);
    }

    fn checkStatement(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        statement: *ast.Statement,
    ) TypeError!void {
        const parameters = signature.parameters;
        const return_type = ast.extractType(signature.return_type);
        try self.expectReachableStatement(statement);
        switch (statement.kind) {
            .noop => {},
            .@"return" => try self.checkReturn(parameters, statement, return_type),
            .discard => |*expression| try self.checkDiscard(parameters, expression),
            .call => |*expression| {
                if (try self.checkStatementCall(parameters, expression) != .void) {
                    return self.fail(expression.location, error.UnusedResult);
                }
            },
            .constant_declaration => |*constant| {
                if (constant.context) {
                    const operand = try self.checkWithOperand(parameters, &constant.value);
                    self.context_allocator = .{ .statement = statement, .type = operand };
                    return;
                }
                if (constant.with and isContextReading(constant.*)) {
                    if (self.context_allocator) |context| {
                        if (context.type == null) {
                            self.trace = &.{};
                            return self.fail(statement.location, error.MissingAllocator);
                        }
                        context.statement.kind.constant_declaration.context_used = true;
                    }
                }
                if (constant.with and self.allocator_type == null and !isContextReading(constant.*)) return self.failUnsetAllocator(statement.location);
                if (ast.isAlias(constant.*)) return;
                const written = if (constant.type) |*written| written else null;
                const caller_compile_time = self.compile_time;
                const caller_rechecking = self.rechecking;
                self.compile_time = true;
                self.rechecking = caller_rechecking or constant.called_early;
                constant.called_early = false;
                defer self.compile_time = caller_compile_time;
                defer self.rechecking = caller_rechecking;
                const value_type = try self.checkDeclaredValue(parameters, written, &constant.value);
                if (self.compile_time_function) return;
                if (!types.isCompileTimeOnly(value_type)) return;
                const value = constant.value;
                if (!self.evaluator.isKnown(value)) return self.fail(value.location, error.CannotEvaluate);
                const cell = try self.arena.allocator().create(Value);
                cell.* = try self.evaluateValue(&value);
                constant.known = cell;
            },
            .tuple_declaration => |*declaration| {
                const value = &declaration.value;
                const value_type = try self.inferType(parameters, value);
                try self.checkElementNames(declaration.names, true, value_type, value.*, value.location);
            },
            .variable_declaration => |*variable| {
                const value = &variable.value;
                const written = if (variable.type) |*written| written else null;
                const value_type = try self.checkInitialValue(parameters, written, value);
                if (types.isCompileTimeOnly(value_type)) return self.fail(value.location, error.TypeVariable);
            },
            .assignment => |*assignment| {
                const target = &assignment.target;
                const operator = assignment.operator orelse {
                    const target_type = try self.inferType(parameters, target);
                    if (!isWritable(target.*)) return self.fail(target.location, error.NotWritable);
                    return self.checkExpression(parameters, &assignment.value, target_type);
                };
                const binary: ast.Binary = .{
                    .operator = operator.operator,
                    .operator_location = operator.location,
                    .left = target,
                    .right = &assignment.value,
                };
                const result_type = try self.checkBinary(parameters, binary, null);
                if (!isWritable(target.*)) return self.fail(target.location, error.NotWritable);
                if (!isConvertible(result_type, target.type.?)) {
                    return self.fail(operator.location, error.TypeMismatch);
                }
            },
            .@"if" => |*conditional| {
                if (conditional.produces and conditional.else_body == null and !self.endsWithVoid()) {
                    return self.fail(statement.location, error.ValueIfWithoutElse);
                }
                if (conditional.names.len > 0) {
                    try self.checkConditionNames(parameters, &conditional.condition, conditional.names, conditional.tuple);
                } else {
                    try self.checkExpression(parameters, &conditional.condition, .boolean);
                    if (conditional.known == null) {
                        if (try self.decideCondition(&conditional.condition)) |chosen| self.chooseBlock(conditional, chosen);
                    }
                }
                if (conditional.known != false) try self.checkBranchBlock(signature, conditional.body, conditional.produces);
                if (conditional.else_body) |else_body| try self.checkBranchBlock(signature, else_body, conditional.produces);
            },
            .@"while" => |*loop| {
                if (loop.names.len > 0) {
                    try self.checkConditionNames(parameters, &loop.condition, loop.names, loop.tuple);
                } else {
                    try self.checkExpression(parameters, &loop.condition, .boolean);
                }
                try self.checkBlock(signature, loop.body);
                if (loop.else_body) |else_body| try self.checkBlock(signature, else_body);
            },
            .@"for" => |*loop| {
                if (try self.checkSequence(parameters, &loop.sequence)) |value_type| {
                    if (value_type == .tuple) return self.fail(loop.sequence.value.location, error.NotSequence);
                    return self.checkIteratorLoop(signature, statement.location, loop, value_type);
                }
                const element_type = ast.extractElementType(loop.sequence);
                switch (loop.sequence) {
                    .value => |value| {
                        try self.checkElementNames(loop.names, loop.tuple, element_type, value, value.location);
                    },
                    .range => |range| {
                        try self.checkElementNames(loop.names, loop.tuple, element_type, null, range.start.location);
                    },
                }
                try self.checkBlock(signature, loop.body);
                if (loop.else_body) |else_body| try self.checkBlock(signature, else_body);
            },
            .match => |*matching| try self.checkMatch(signature, statement.location, matching),
            .@"defer" => |deferred| {
                if (deferred.on_error and !canHoldError(return_type) and !self.isInferring(return_type)) {
                    return self.fail(statement.location, error.ErrdeferWithoutError);
                }
                const caller_deferring = self.deferring;
                self.deferring = true;
                defer self.deferring = caller_deferring;
                try self.checkStatement(signature, deferred.statement);
            },
            .@"break", .@"continue" => {},
            .value => try self.checkProducedValue(parameters, statement),
        }
    }

    fn checkDiscard(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        if (expression.kind == .identifier) return;
        const value_type = if (isCallOrTriedCall(expression.*))
            try self.checkStatementCall(parameters, expression)
        else
            try self.inferType(parameters, expression);
        if (value_type == .void) return self.fail(expression.location, error.DiscardedVoid);
        if (canHoldError(value_type)) return self.fail(expression.location, error.DiscardedError);
    }

    fn expectReachableStatement(self: *TypeChecker, statement: *const ast.Statement) CheckError!void {
        const expressions = ast.extractExpressions(statement);
        for (expressions.items[0..expressions.count]) |expression| try self.expectReachable(expression);
        for (expressions.items[0..expressions.count]) |expression| {
            if (expression.kind != .jump) continue;
            const location = switch (statement.kind) {
                .@"if", .@"while", .@"for", .match => expression.location,
                else => statement.location,
            };
            return self.fail(location, error.UnreachableCode);
        }
    }

    fn expectReachable(self: *TypeChecker, expression: *const ast.Expression) CheckError!void {
        const allocator = self.arena.allocator();
        var parts: std.ArrayList(*const ast.Expression) = .empty;
        var end = expression.location;
        switch (expression.kind) {
            .integer_literal,
            .float_literal,
            .boolean_literal,
            .string_literal,
            .undefined,
            .null,
            .identifier,
            .path_expression,
            .member,
            .array_type,
            .slice_type,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            .branching,
            => return,
            .call => |call| {
                for (call.arguments) |*argument| try parts.append(allocator, &argument.value);
            },
            .method_call => |call| {
                try parts.append(allocator, call.receiver);
                for (call.arguments) |*argument| try parts.append(allocator, &argument.value);
                end = call.name_location;
            },
            .composite_literal => |literal| {
                for (literal.elements) |*element| try parts.append(allocator, &element.value);
            },
            .case_literal => |literal| {
                for (literal.arguments) |*argument| try parts.append(allocator, &argument.value);
            },
            .inferred_type => {},
            .binary => |binary| {
                try parts.append(allocator, binary.left);
                end = binary.operator_location;
                if (isShortCircuit(binary.operator)) {
                    try self.expectReachable(binary.right);
                } else {
                    try parts.append(allocator, binary.right);
                }
            },
            .unary => |unary| try parts.append(allocator, unary.operand),
            .negation, .address_of, .dereference, .unwrap, .@"try" => |operand| try parts.append(allocator, operand),
            .index => |indexing| {
                try parts.append(allocator, indexing.value);
                try parts.append(allocator, indexing.index);
            },
            .slice => |slice| {
                try parts.append(allocator, slice.value);
                if (slice.start) |start| try parts.append(allocator, start);
                if (slice.end) |slice_end| try parts.append(allocator, slice_end);
            },
            .field_access => |access| {
                try parts.append(allocator, access.value);
                end = access.field_location;
            },
            .range => |range| {
                try parts.append(allocator, &range.start);
                if (range.end) |*range_end| try parts.append(allocator, range_end);
            },
            .jump => |statement| {
                if (statement.kind == .@"return") {
                    if (statement.kind.@"return") |*value| try parts.append(allocator, value);
                }
            },
        }
        for (parts.items, 0..) |part, index| {
            try self.expectReachable(part);
            if (part.kind != .jump) continue;
            const location = if (index + 1 < parts.items.len) parts.items[index + 1].location else end;
            return self.fail(location, error.UnreachableCode);
        }
    }

    fn checkConditionNames(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        condition: *ast.Expression,
        names: []ast.ElementName,
        tuple: bool,
    ) TypeError!void {
        const condition_type = try self.inferType(parameters, condition);
        if (condition_type != .optional) return self.fail(condition.location, error.NotOptional);
        try self.checkElementNames(names, tuple, condition_type.optional.child, condition.*, condition.location);
    }

    fn checkStatementCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        if (expression.kind == .@"try") return self.inferType(parameters, expression);
        if (ast.isComptimeErrorCall(self.program.modules[self.module_index], expression.*)) {
            return self.checkComptimeError(parameters, expression);
        }
        return self.checkCall(parameters, expression);
    }

    fn checkMatch(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        matching: *ast.Match,
    ) TypeError!void {
        const value = &matching.value;
        const value_type = try self.inferType(signature.parameters, value);
        switch (value_type) {
            .@"enum" => |enumeration| try self.checkEnumMatch(signature, location, matching, enumeration),
            .result => |result| try self.checkResultMatch(signature, location, matching, result),
            .optional => |optional| try self.checkOptionalMatch(signature, location, matching, optional.child),
            .number => |number| {
                if (!isInteger(value_type)) return self.fail(value.location, error.NotMatchable);
                try self.checkIntegerMatch(signature, location, matching, number);
            },
            .boolean, .void, .type, .@"struct", .pointer, .array, .slice, .tuple, .function, .variable, .application => {
                return self.fail(value.location, error.NotMatchable);
            },
        }
    }

    fn checkEnumMatch(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        matching: *ast.Match,
        enumeration: *const types.Enum,
    ) TypeError!void {
        if (enumeration.cases.len == 0) return self.fail(location, error.UnreachableStatement);
        const covered = try self.arena.allocator().alloc(bool, enumeration.cases.len);
        @memset(covered, false);
        for (matching.branches) |*branch| {
            const names = ast.extractBranchNames(matching.*, branch.*);
            if (branch.cases.len == 0) {
                if (std.mem.findScalar(bool, covered, false) == null) return self.fail(branch.location, error.EmptyElse);
                if (branch.naming == .value) {
                    const remaining: types.Type = if (enumeration.kind == .error_set)
                        .{ .@"enum" = try self.findRemainingErrors(enumeration, covered) }
                    else
                        .{ .@"enum" = enumeration };
                    try self.checkRemainingNames(names, branch.tuple, remaining);
                }
                try self.coverRemaining(branch.location, covered);
            }
            for (branch.cases) |*case| try self.coverCase(enumeration, case, covered);
            switch (branch.naming) {
                .none => {},
                .payload => try self.checkPayloadNames(enumeration, branch, names, matching.value),
                .value => if (branch.cases.len > 0) {
                    if (enumeration.kind != .error_set) return self.fail(names[0].location, error.MisplacedValueName);
                    try self.checkErrorNames(enumeration, branch, names);
                },
            }
            try self.checkBranchBlock(signature, branch.body, matching.produces);
        }
        if (std.mem.findScalar(bool, covered, false) != null) return self.fail(location, error.MissingCase);
    }

    fn coverRemaining(self: *TypeChecker, location: token.Location, covered: []bool) CheckError!void {
        if (std.mem.findScalar(bool, covered, false) == null) return self.fail(location, error.EmptyElse);
        @memset(covered, true);
    }

    fn findRemainingErrors(self: *TypeChecker, error_set: *const types.Enum, covered: []const bool) CheckError!*const types.Enum {
        const allocator = self.arena.allocator();
        if (std.mem.findScalar(bool, covered, true) == null) return error_set;
        var remaining: std.ArrayList(types.Case) = .empty;
        for (error_set.cases, covered) |case, handled| {
            if (!handled) try remaining.append(allocator, case);
        }
        return self.program.types.addErrorCases(allocator, remaining.items);
    }

    fn checkRemainingNames(self: *TypeChecker, names: []ast.ElementName, tuple: bool, remaining: types.Type) TypeError!void {
        for (names) |name| {
            if (name.pointer) return self.fail(name.location, error.MisplacedValueName);
        }
        if (remaining == .void) return self.fail(names[0].location, error.CaseWithoutValue);
        try self.checkElementNames(names, tuple, remaining, null, names[0].location);
    }

    fn checkErrorNames(
        self: *TypeChecker,
        error_set: *const types.Enum,
        branch: *const ast.Branch,
        names: []ast.ElementName,
    ) TypeError!void {
        for (names) |name| {
            if (name.pointer) return self.fail(name.location, error.MisplacedValueName);
        }
        const case = error_set.cases[branch.cases[0].index.?];
        const narrowed = try self.program.types.addErrorCases(self.arena.allocator(), &.{case});
        try self.checkElementNames(names, branch.tuple, .{ .@"enum" = narrowed }, null, names[0].location);
    }

    fn coverCase(self: *TypeChecker, enumeration: *const types.Enum, case: *ast.BranchCase, covered: []bool) CheckError!void {
        if (case.range) return self.fail(case.pattern.location, error.MisplacedRange);
        const index = try self.findBranchCase(enumeration, case.pattern);
        if (covered[index]) return self.fail(case.pattern.location, error.DuplicateBranch);
        covered[index] = true;
        case.kind = .case;
        case.index = index;
    }

    fn checkPayloadNames(
        self: *TypeChecker,
        enumeration: *const types.Enum,
        branch: *ast.Branch,
        names: []ast.ElementName,
        value: ast.Expression,
    ) TypeError!void {
        const case = branch.cases[0];
        if (case.kind != .case) return self.fail(names[0].location, error.MisplacedValueName);
        const case_type = enumeration.cases[case.index.?].type orelse {
            return self.fail(names[0].location, error.CaseWithoutValue);
        };
        branch.tuple = case_type == .tuple;
        if (!branch.tuple and names.len != 1) return self.fail(names[1].location, error.NotTuple);
        try self.checkElementNames(names, branch.tuple, case_type, value, value.location);
    }

    fn findBranchCase(self: *TypeChecker, enumeration: *const types.Enum, name: ast.Expression) CheckError!usize {
        switch (name.kind) {
            .path_expression => |path_expression| {
                const resolution = path_expression.resolution.?;
                if (resolution != .case) return self.fail(name.location, error.UnknownCase);
                const tag = resolution.case.enumeration.cases[resolution.case.index].tag;
                for (enumeration.cases, 0..) |case, index| {
                    if (case.tag == tag) return index;
                }
                return self.fail(name.location, error.UnknownCase);
            },
            .identifier => |identifier| {
                var found: ?usize = null;
                for (enumeration.cases, 0..) |case, index| {
                    if (!std.mem.eql(u8, case.name, identifier.name)) continue;
                    if (found != null) return self.fail(name.location, error.AmbiguousCase);
                    found = index;
                }
                const index = found orelse return self.fail(name.location, error.UnknownCase);
                return index;
            },
            else => return self.fail(name.location, error.UnknownCase),
        }
    }

    fn checkResultMatch(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        matching: *ast.Match,
        result: *const types.Result,
    ) TypeError!void {
        const error_set = result.error_set;
        const covered = try self.arena.allocator().alloc(bool, error_set.cases.len);
        @memset(covered, false);
        var value_covered = false;
        for (matching.branches) |*branch| {
            const names = ast.extractBranchNames(matching.*, branch.*);
            if (branch.cases.len == 0) {
                const errors_left = std.mem.findScalar(bool, covered, false) != null;
                if (value_covered and !errors_left) return self.fail(branch.location, error.EmptyElse);
                if (branch.naming == .value) try self.checkRemainingNames(names, branch.tuple, try self.findRemainingResult(result, covered, value_covered));
                @memset(covered, true);
                value_covered = true;
            }
            for (branch.cases) |*case| {
                if (isErrorPattern(error_set, case.pattern)) {
                    try self.coverCase(error_set, case, covered);
                    continue;
                }
                try self.coverValue(signature, case, result.value, &value_covered);
            }
            switch (branch.naming) {
                .none => {},
                .payload => try self.checkPayloadNames(error_set, branch, names, matching.value),
                .value => if (branch.cases.len > 0) try self.checkValueNames(error_set, branch, names, result.value, matching.value),
            }
            try self.checkBranchBlock(signature, branch.body, matching.produces);
        }
        if (!value_covered or std.mem.findScalar(bool, covered, false) != null) return self.fail(location, error.MissingCase);
    }

    fn findRemainingResult(
        self: *TypeChecker,
        result: *const types.Result,
        covered: []const bool,
        value_covered: bool,
    ) CheckError!types.Type {
        const allocator = self.arena.allocator();
        const error_set = result.error_set;
        if (value_covered) return .{ .@"enum" = try self.findRemainingErrors(error_set, covered) };
        if (std.mem.findScalar(bool, covered, false) == null) return result.value;
        if (std.mem.findScalar(bool, covered, true) == null) return .{ .result = result };
        return .{ .result = try self.program.types.addResult(allocator, try self.findRemainingErrors(error_set, covered), result.value) };
    }

    fn coverValue(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        case: *ast.BranchCase,
        value_type: types.Type,
        covered: *bool,
    ) TypeError!void {
        if (case.range) return self.fail(case.pattern.location, error.MisplacedRange);
        const written = try self.evaluateCaseType(signature, &case.pattern);
        if (!std.meta.eql(written, value_type)) return self.fail(case.pattern.location, error.WrongCaseType);
        if (covered.*) return self.fail(case.pattern.location, error.DuplicateBranch);
        covered.* = true;
        case.kind = .value;
    }

    fn evaluateCaseType(self: *TypeChecker, signature: ast.FunctionSignature, pattern: *ast.Expression) TypeError!types.Type {
        if (isUnknownName(pattern.*)) return self.fail(pattern.location, error.UnknownCase);
        const caller_compile_time = self.compile_time;
        self.compile_time = true;
        defer self.compile_time = caller_compile_time;
        try self.checkExpression(signature.parameters, pattern, .type);
        if (!self.evaluator.isKnown(pattern.*)) return self.fail(pattern.location, error.CannotEvaluate);
        return (try self.evaluateValue(pattern)).type;
    }

    fn checkValueNames(
        self: *TypeChecker,
        error_set: ?*const types.Enum,
        branch: *const ast.Branch,
        names: []ast.ElementName,
        value_type: types.Type,
        value: ast.Expression,
    ) TypeError!void {
        if (branch.cases[0].kind == .case) return self.checkErrorNames(error_set.?, branch, names);
        if (branch.cases[0].kind != .value or value_type == .void) return self.fail(names[0].location, error.CaseWithoutValue);
        try self.checkElementNames(names, branch.tuple, value_type, value, value.location);
    }

    fn checkOptionalMatch(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        matching: *ast.Match,
        child: types.Type,
    ) TypeError!void {
        var null_covered = false;
        var value_covered = false;
        for (matching.branches) |*branch| {
            const names = ast.extractBranchNames(matching.*, branch.*);
            if (branch.cases.len == 0) {
                if (null_covered and value_covered) return self.fail(branch.location, error.EmptyElse);
                if (branch.naming == .value) {
                    try self.checkRemainingNames(names, branch.tuple, if (null_covered) child else matching.value.type.?);
                }
                null_covered = true;
                value_covered = true;
            }
            for (branch.cases) |*case| {
                if (case.pattern.kind != .null) {
                    try self.coverValue(signature, case, child, &value_covered);
                    continue;
                }
                if (case.range) return self.fail(case.pattern.location, error.MisplacedRange);
                if (null_covered) return self.fail(case.pattern.location, error.DuplicateBranch);
                null_covered = true;
                case.kind = .null;
            }
            switch (branch.naming) {
                .none => {},
                .payload => return self.fail(names[0].location, error.MisplacedValueName),
                .value => if (branch.cases.len > 0) try self.checkValueNames(null, branch, names, child, matching.value),
            }
            try self.checkBranchBlock(signature, branch.body, matching.produces);
        }
        if (!null_covered or !value_covered) return self.fail(location, error.MissingCase);
    }

    fn checkIntegerMatch(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        matching: *ast.Match,
        number: types.NumberType,
    ) TypeError!void {
        const minimum = Integer.findMinimum(number);
        const maximum = Integer.findMaximum(number);
        var covered: std.ArrayList(*const ast.BranchCase) = .empty;
        var has_else = false;
        for (matching.branches) |*branch| {
            const names = ast.extractBranchNames(matching.*, branch.*);
            if (branch.cases.len == 0) {
                if (coversRange(covered.items, minimum, maximum)) return self.fail(branch.location, error.EmptyElse);
                has_else = true;
            }
            for (branch.cases) |*case| {
                try self.boundCase(signature, case, .{ .number = number }, maximum);
                for (covered.items) |earlier| {
                    if (case.minimum.order(earlier.maximum) != .gt and earlier.minimum.order(case.maximum) != .gt) {
                        return self.fail(case.pattern.location, error.DuplicateBranch);
                    }
                }
                try covered.append(self.arena.allocator(), case);
            }
            if (branch.naming != .none) {
                if (branch.cases.len > 0) return self.fail(names[0].location, error.CaseWithoutValue);
                try self.checkRemainingNames(names, branch.tuple, .{ .number = number });
            }
            try self.checkBranchBlock(signature, branch.body, matching.produces);
        }
        if (!has_else and !coversRange(covered.items, minimum, maximum)) return self.fail(location, error.MissingCase);
    }

    fn boundCase(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        case: *ast.BranchCase,
        value_type: types.Type,
        maximum: Integer,
    ) TypeError!void {
        case.kind = .integer;
        case.minimum = try self.evaluateCaseInteger(signature, &case.pattern, value_type);
        if (!case.range) {
            case.maximum = case.minimum;
            return;
        }
        case.maximum = maximum;
        if (case.end) |*end| {
            const limit = try self.evaluateCaseInteger(signature, end, value_type);
            if (limit.order(case.minimum) != .gt) return self.fail(case.pattern.location, error.EmptyRange);
            case.maximum = limit.decrement();
        }
        if (case.maximum.order(case.minimum) == .lt) return self.fail(case.pattern.location, error.EmptyRange);
    }

    fn evaluateCaseInteger(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        expression: *ast.Expression,
        value_type: types.Type,
    ) TypeError!Integer {
        if (isUnknownName(expression.*)) return self.fail(expression.location, error.UnknownCase);
        try self.checkExpression(signature.parameters, expression, value_type);
        if (!self.evaluator.isKnown(expression.*)) return self.fail(expression.location, error.CannotEvaluate);
        return (try self.evaluateValue(expression)).integer;
    }

    fn decideCondition(self: *TypeChecker, condition: *const ast.Expression) TypeError!?bool {
        if (!self.evaluator.isKnown(condition.*)) return null;
        const value = self.evaluateValue(condition) catch |evaluate_error| {
            if (evaluate_error != error.CannotEvaluate and evaluate_error != error.ExternalCall) return evaluate_error;
            self.failure = null;
            self.failed_function = null;
            return null;
        };
        return value.boolean;
    }

    fn chooseBlock(self: *TypeChecker, conditional: *ast.If, chosen: bool) void {
        const condition = &conditional.condition;
        condition.kind = .{ .boolean_literal = chosen };
        conditional.known = chosen;
        const module = self.program.modules[self.module_index];
        if (chosen) {
            conditional.dropped_ends = ast.isEndingBlock(module, conditional.else_body orelse &.{});
            if (conditional.else_body != null) conditional.else_body = &.{};
        } else {
            conditional.dropped_ends = ast.isEndingBlock(module, conditional.body);
            conditional.body = &.{};
        }
    }

    fn checkElementNames(
        self: *TypeChecker,
        names: []ast.ElementName,
        tuple: bool,
        element_type: types.Type,
        container: ?ast.Expression,
        location: token.Location,
    ) TypeError!void {
        if (tuple) {
            if (element_type != .tuple) return self.fail(location, error.NotTuple);
            if (names.len != element_type.tuple.elements.len) {
                return self.fail(names[0].location, error.WrongNameCount);
            }
        }
        for (names, 0..) |*name, position| {
            const name_type = if (tuple) element_type.tuple.elements[position] else element_type;
            if (!name.pointer) {
                name.type = name_type;
                continue;
            }
            name.type = try self.checkElementAddress(name.location, name_type, container);
        }
    }

    fn checkElementAddress(
        self: *TypeChecker,
        location: token.Location,
        target: types.Type,
        container: ?ast.Expression,
    ) TypeError!types.Type {
        const value = container orelse return self.fail(location, error.NotAddressable);
        if (!isElementPlace(value)) return self.fail(location, error.NotAddressable);
        const pointer = try self.program.types.addPointer(self.arena.allocator(), .{
            .target = target,
            .many = false,
            .constant = !isElementWritable(value),
        });
        return .{ .pointer = pointer };
    }

    fn checkIteratorLoop(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        location: token.Location,
        loop: *ast.For,
        value_type: types.Type,
    ) TypeError!void {
        const sequence_location = loop.sequence.value.location;
        const iterable = self.findLanguageTypeclass("iterator", "Iterable") orelse return self.fail(sequence_location, error.NotSequence);
        const iterable_decided = [_]?types.Argument{.{ .type = value_type }};
        const iterator = (try self.findInstanceFunction(location, iterable, &iterable_decided, "iterator")) orelse {
            return self.fail(sequence_location, error.NotSequence);
        };
        const cursor_function = (try self.findInstanceFunction(location, iterable, &iterable_decided, "Cursor")).?;
        try self.prepareFunction(iterator);
        const cursor_type = try self.evaluateFunctionType(location, cursor_function);
        const typeclass = self.findLanguageTypeclass("iterator", "Iterator") orelse return self.fail(sequence_location, error.NotSequence);
        const decided = [_]?types.Argument{.{ .type = cursor_type }};
        const next = (try self.findInstanceFunction(location, typeclass, &decided, "next")) orelse {
            return self.fail(sequence_location, error.CursorNotIterator);
        };
        const element_function = (try self.findInstanceFunction(location, typeclass, &decided, "Element")).?;
        try self.prepareFunction(next);
        const element_type = try self.evaluateFunctionType(location, element_function);
        if (element_type != .tuple) return self.fail(location, error.ElementNotTuple);
        const elements = element_type.tuple.elements;
        const iteration: ast.Iteration = .{ .iterator = iterator, .cursor = cursor_type, .next = next, .element = element_type };
        loop.iterator = iteration;
        const count: usize = if (loop.tuple) loop.names.len else 1;
        if (count != elements.len or (!loop.tuple and loop.names.len != 1)) {
            return self.fail(loop.names[0].location, error.WrongNameCount);
        }
        for (loop.names, elements[0..loop.names.len], 0..) |*name, element, position| {
            const pointer = element == .pointer and !element.pointer.many;
            if (name.pointer and !pointer) return self.fail(name.location, error.PointerOverIterator);
            name.type = if (ast.isCopiedElement(iteration, name.*, position)) element.pointer.target else element;
        }
        try self.checkBlock(signature, loop.body);
        if (loop.else_body) |else_body| try self.checkBlock(signature, else_body);
    }

    fn findLanguageTypeclass(self: *const TypeChecker, module_name: []const u8, name: []const u8) ?ast.Resolution.Typeclass {
        for (self.program.modules, 0..) |module, module_index| {
            if (module.path.len != 2 or !std.mem.eql(u8, module.path[0], "mn") or !std.mem.eql(u8, module.path[1], module_name)) continue;
            for (module.declarations, 0..) |declaration, index| {
                if (declaration.kind != .typeclass_definition) continue;
                if (!std.mem.eql(u8, declaration.kind.typeclass_definition.name, name)) continue;
                return .{ .module = module_index, .declaration = index };
            }
        }
        return null;
    }

    fn evaluateFunctionType(
        self: *TypeChecker,
        location: token.Location,
        function: ast.Resolution.Function,
    ) TypeError!types.Type {
        const signature = ast.extractFunctionSignature(ast.findDeclaration(self.program.modules[function.module], function.declaration).*);
        var call: ast.Expression = .{
            .kind = .{ .call = .{ .callee = .{ .identifier = .{ .name = signature.name, .resolution = .{ .function = function } } }, .arguments = &.{} } },
            .type = .type,
            .location = location,
        };
        const value = try self.evaluateValue(&call);
        _ = &call;
        return value.type;
    }

    fn checkSequence(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        sequence: *ast.Sequence,
    ) TypeError!?types.Type {
        switch (sequence.*) {
            .range => |*range| {
                const bound_type: types.Type = .{ .number = .usize };
                try self.checkExactExpression(parameters, &range.start, bound_type);
                if (range.end == null) return null;
                const end = &range.end.?;
                try self.checkExactExpression(parameters, end, bound_type);
                if (!self.evaluator.isKnownWithoutCalls(end.*)) return null;
                const last = (try self.evaluateValue(end)).integer.unsigned;
                range.known_end = @intCast(last);
                if (!self.evaluator.isKnownWithoutCalls(range.start)) return null;
                const first = (try self.evaluateValue(&range.start)).integer.unsigned;
                if (first > last) return self.fail(range.start.location, error.ReversedRange);
                if (first == last) return self.fail(range.start.location, error.EmptyRange);
            },
            .value => |*value| {
                const value_type = try self.inferType(parameters, value);
                switch (value_type) {
                    .array, .slice => {},
                    .pointer => |pointer| {
                        if (pointer.many or pointer.target != .array) return value_type;
                    },
                    .number, .boolean, .void, .type, .@"struct", .@"enum", .optional, .result, .tuple, .function, .variable, .application => {
                        return value_type;
                    },
                }
            },
        }
        return null;
    }

    fn checkBlock(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        statements: []ast.Statement,
    ) TypeError!void {
        return self.checkProducingBlock(signature, statements, false);
    }

    fn checkProducingBlock(
        self: *TypeChecker,
        signature: ast.FunctionSignature,
        statements: []ast.Statement,
        produces: bool,
    ) TypeError!void {
        const production = self.production;
        self.production = null;
        defer self.production = production;
        const context_allocator = self.context_allocator;
        defer self.context_allocator = context_allocator;
        for (statements, 0..) |*statement, index| {
            const ends = statement.kind == .call and ast.isComptimeErrorCall(self.program.modules[self.module_index], statement.kind.call);
            if (ends and index + 1 < statements.len) return self.fail(statements[index + 1].location, error.UnreachableStatement);
            if (produces and index + 1 == statements.len) self.production = production;
            try self.checkStatement(signature, statement);
        }
    }

    fn checkInitialValue(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        written_type: ?*ast.Expression,
        value: *ast.Expression,
    ) TypeError!types.Type {
        if (value.kind != .undefined) {
            return self.checkDeclaredValue(parameters, written_type, value);
        }
        const written = written_type orelse {
            return self.fail(value.location, error.UnknownValueType);
        };
        if (isUnfinishedArray(written.*)) return self.fail(value.location, error.MissingLength);
        value.type = ast.extractType(written.*);
        return value.type.?;
    }

    fn checkExpression(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        const exact = self.exact_numbers;
        self.exact_numbers = false;
        defer self.exact_numbers = exact;
        recordExpectedType(expression, expected);
        if (expression.kind == .case_literal) try self.resolveCaseLiteral(expression, findLiteralType(expected));
        if (expected == .optional and takesExpectedType(expression.*)) {
            try self.checkExpression(parameters, expression, expected.optional.child);
            if (!isConvertible(expression.type.?, expected)) return self.fail(expression.location, error.TypeMismatch);
            return;
        }
        if (expected == .result and (takesExpectedType(expression.*) or expression.kind == .null)) {
            try self.checkExpression(parameters, expression, expected.result.value);
            if (!isConvertible(expression.type.?, expected)) return self.fail(expression.location, error.TypeMismatch);
            return;
        }
        const value_type: types.Type = switch (expression.kind) {
            .integer_literal, .float_literal, .boolean_literal, .string_literal => value_type: {
                try self.checkLiteral(expression.*, expected);
                break :value_type expected;
            },
            .negation => |operand| value_type: {
                try self.checkNegation(expression.location, operand, expected);
                break :value_type expected;
            },
            .binary => |binary| try self.checkBinary(parameters, binary, expected),
            .unary => |unary| try self.checkUnary(parameters, expression.location, unary, expected),
            .undefined => return self.fail(expression.location, error.UnexpectedUndefined),
            .null => value_type: {
                if (expected != .optional) return self.fail(expression.location, error.UnexpectedNull);
                break :value_type expected;
            },
            inline .identifier, .path_expression, .member => |name| value_type: {
                break :value_type try self.computeValueType(parameters, expression.location, name.resolution.?);
            },
            .call, .method_call => try self.checkCall(parameters, expression),
            .composite_literal => |literal| value_type: {
                const location = expression.location;
                break :value_type try self.checkCompositeLiteral(parameters, location, literal, expected);
            },
            .case_literal => unreachable,
            .inferred_type => return self.fail(expression.location, error.InferredTypeOutOfPlace),
            .array_type, .slice_type, .pointer_type, .optional_type, .tuple_type, .function_type, .struct_type => value_type: {
                if (expected != .type) return self.fail(expression.location, error.TypeMismatch);
                break :value_type expected;
            },
            .slice => try self.inferSliceType(parameters, expression),
            .field_access => try self.checkFieldAccess(parameters, expression),
            .index, .address_of, .dereference, .unwrap, .@"try", .range => try self.inferType(parameters, expression),
            .jump => try self.checkJumpValue(parameters, expression, expected),
            .branching => try self.checkBranching(expression, expected),
        };
        try self.recordInferredErrors(value_type, expected);
        if (!isConvertible(value_type, expected)) return self.fail(expression.location, error.TypeMismatch);
        if (exact and isWidened(value_type, expected)) return self.fail(expression.location, error.TypeMismatch);
        expression.type = value_type;
        try self.foldTypeComparison(expression);
        try self.checkKnownOperation(expression);
        try self.storeSliceLiteral(expression);
    }

    fn resolveCaseLiteral(self: *TypeChecker, expression: *ast.Expression, expected: types.Type) TypeError!void {
        const literal = expression.kind.case_literal;
        const is_enum = expected == .@"enum" and expected.@"enum".kind == .enumeration;
        if (!is_enum and expected != .@"struct") return self.fail(expression.location, error.CaseWithoutEnum);
        const allocator = self.arena.allocator();
        const type_name = if (is_enum) expected.@"enum".name else expected.@"struct".name;
        const path = try allocator.dupe([]const u8, &.{ type_name, literal.name });
        var name: ast.PathExpression = .{ .path = path };
        if (is_enum) {
            for (expected.@"enum".cases, 0..) |case, index| {
                if (!std.mem.eql(u8, case.name, literal.name)) continue;
                name.resolution = .{ .case = .{ .enumeration = expected.@"enum", .index = index } };
            }
        }
        if (name.resolution != null and literal.crossing) return self.failNeedlessPrivate(expression.location, literal.name, false);
        if (name.resolution != null and literal.called) {
            return self.failNamingType(expression.location, error.ParenthesizedCaseValue, "case {1s} of type {0s} carries its value in braces, not parentheses, e.g. `::{1s}{{ value }}`", type_name, literal.name);
        }
        if (name.resolution == null and literal.braced) {
            return self.failNamingType(expression.location, error.UnknownCase, "type {s} has no case {s}", type_name, literal.name);
        }
        if (name.resolution == null) name.resolution = .{ .function = try self.findLiteralFunction(expression, expected, type_name) };
        expression.kind = if (literal.called)
            .{ .call = .{ .callee = .{ .path_expression = name }, .arguments = literal.arguments, .with_value = literal.with_value } }
        else if (literal.braced)
            .{ .call = .{ .callee = .{ .path_expression = name }, .arguments = literal.arguments, .braces = .written } }
        else
            .{ .path_expression = name };
    }

    fn findLiteralFunction(
        self: *TypeChecker,
        expression: *const ast.Expression,
        expected: types.Type,
        type_name: []const u8,
    ) TypeError!ast.Resolution.Function {
        const literal = expression.kind.case_literal;
        const function = ast.findOwnMethod(self.program.modules, expected, literal.name) orelse {
            return self.failNamingType(expression.location, error.UnknownCase, "type {s} has no case or function {s}", type_name, literal.name);
        };
        try self.expectReachableFunction(expression.location, expected, function, .{ .name = literal.name, .crossed = literal.crossing });
        if (self.resolver) |*resolver| try resolver.resolve(resolver.context, function);
        const signature = self.extractSignature(.{ .function = function });
        if (signature.self_parameter != .none) {
            return self.failNamingType(expression.location, error.LiteralFunctionIsMethod, "function {1s} of type {0s} is a method, call it on a value", type_name, literal.name);
        }
        if (!try self.returnsExpected(function, &signature, expected)) {
            return self.failNamingType(expression.location, error.LiteralFunctionType, "function {1s} of type {0s} does not return that type", type_name, literal.name);
        }
        return function;
    }

    fn failNamingType(
        self: *TypeChecker,
        location: token.Location,
        check_error: CheckError,
        comptime format: []const u8,
        type_name: []const u8,
        name: []const u8,
    ) TypeError {
        const failure = self.fail(location, check_error);
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{ type_name, name });
        return failure;
    }

    fn returnsExpected(
        self: *TypeChecker,
        function: ast.Resolution.Function,
        signature: *const ast.FunctionSignature,
        expected: types.Type,
    ) TypeError!bool {
        var pattern = ast.extractType(signature.return_type);
        const count = signature.parameters.len + signature.declared.len;
        if (ast.isGeneric(signature.*)) {
            const resolver = &self.resolver.?;
            pattern = try resolver.resolveReturnPattern(resolver.context, function);
        }
        if (pattern == .result) pattern = pattern.result.value;
        if (pattern == .optional) pattern = pattern.optional.child;
        const assigned = try self.arena.allocator().alloc(?types.Argument, count);
        @memset(assigned, null);
        return types.matchType(pattern, expected, .function, assigned, true);
    }

    fn inferCaseLiteral(self: *TypeChecker, parameters: []const ast.TypedName, expression: *ast.Expression) TypeError!types.Type {
        const expected = expression.kind.case_literal.expected orelse return self.failUnknownType(expression);
        try self.resolveCaseLiteral(expression, findLiteralType(expected));
        return self.inferType(parameters, expression);
    }

    fn failUnknownType(self: *TypeChecker, expression: *const ast.Expression) CheckError {
        if (expression.kind == .case_literal) return self.fail(expression.location, error.CaseWithoutKnownEnum);
        return self.fail(expression.location, error.UnknownValueType);
    }

    fn storeSliceLiteral(self: *TypeChecker, expression: *ast.Expression) TypeError!void {
        if (expression.kind != .composite_literal or expression.type.? != .slice) return;
        const literal = &expression.kind.composite_literal;
        if (literal.elements.len == 0) return;
        const cell = try self.arena.allocator().create(Value);
        cell.* = try self.evaluateValue(expression);
        literal.known = cell;
    }

    fn foldTypeComparison(self: *TypeChecker, expression: *ast.Expression) TypeError!void {
        if (expression.kind != .binary) return;
        const binary = expression.kind.binary;
        if (binary.operator != .equal and binary.operator != .not_equal) return;
        const operand_type = binary.left.type orelse return;
        if (!types.isCompileTimeOnly(operand_type)) return;
        if (!self.evaluator.isKnown(expression.*)) return self.fail(expression.location, error.CannotEvaluate);
        const value = try self.evaluateValue(expression);
        expression.kind = .{ .boolean_literal = value.boolean };
    }

    fn checkKnownOperation(self: *TypeChecker, expression: *const ast.Expression) TypeError!void {
        switch (expression.kind) {
            .negation, .binary, .unary => try self.evaluateIfKnown(expression.*),
            .integer_literal,
            .float_literal,
            .boolean_literal,
            .string_literal,
            .undefined,
            .null,
            .identifier,
            .path_expression,
            .member,
            .call,
            .method_call,
            .address_of,
            .array_type,
            .composite_literal,
            .case_literal,
            .inferred_type,
            .slice_type,
            .index,
            .slice,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            .field_access,
            .dereference,
            .unwrap,
            .@"try",
            .range,
            .jump,
            .branching,
            => {},
        }
    }

    fn evaluateIfKnown(self: *TypeChecker, expression: ast.Expression) TypeError!void {
        if (self.quiet_operations > 0 or !self.evaluator.isKnownWithoutCalls(expression)) return;
        _ = self.evaluateValue(&expression) catch |evaluate_error| {
            if (evaluate_error != error.CannotEvaluate) return evaluate_error;
            self.failure = null;
            self.failed_function = null;
        };
    }

    fn evaluateValue(self: *TypeChecker, expression: *const ast.Expression) TypeError!Value {
        const caller_module_index = self.evaluator.module_index;
        const caller_steps = self.evaluator.steps;
        defer self.evaluator.module_index = caller_module_index;
        defer self.evaluator.steps = caller_steps;
        self.prepareEvaluator();
        self.evaluator.steps = 0;
        return self.evaluator.evaluate(expression) catch |evaluate_error| {
            self.adoptEvaluatorFailure();
            return evaluate_error;
        };
    }

    fn evaluateConstant(self: *TypeChecker, constant: ast.Resolution.Constant) TypeError!*Value {
        const caller_module_index = self.evaluator.module_index;
        const caller_steps = self.evaluator.steps;
        defer self.evaluator.module_index = caller_module_index;
        defer self.evaluator.steps = caller_steps;
        self.prepareEvaluator();
        self.evaluator.steps = 0;
        return self.evaluator.evaluateConstant(constant) catch |evaluate_error| {
            self.adoptEvaluatorFailure();
            return evaluate_error;
        };
    }

    fn prepareEvaluator(self: *TypeChecker) void {
        self.evaluator.program = self.program;
        self.evaluator.module_index = self.module_index;
        self.evaluator.preparer = .{
            .context = self,
            .prepare = prepareForEvaluator,
            .beginStruct = beginStructForEvaluator,
            .findOrigin = findOriginForEvaluator,
            .finishStruct = finishStructForEvaluator,
        };
        self.evaluator.failure = null;
    }

    fn adoptEvaluatorFailure(self: *TypeChecker) void {
        if (self.evaluator.failure) |failure| self.failure = failure;
    }

    fn prepareForEvaluator(context: *anyopaque, function: ast.Resolution.Function) AnalyzeError!void {
        const self: *TypeChecker = @ptrCast(@alignCast(context));
        return self.prepareFunction(function);
    }

    fn beginStructForEvaluator(context: *anyopaque, struct_type: *const ast.StructType) AnalyzeError!types.Type {
        const self: *TypeChecker = @ptrCast(@alignCast(context));
        const resolver = &self.resolver.?;
        var created = try resolver.beginStruct(resolver.context, struct_type);
        const origin = try self.arena.allocator().create(types.Origin);
        origin.* = .{};
        created.@"struct".origin = origin;
        return created;
    }

    fn findOriginForEvaluator(context: *anyopaque, function: ast.Resolution.Function) AnalyzeError!?types.Origin {
        const self: *TypeChecker = @ptrCast(@alignCast(context));
        const instance = for (self.instances.items) |instance| {
            if (std.meta.eql(instance.function, function)) break instance;
        } else return null;
        const arguments = try self.arena.allocator().alloc(types.Type, instance.arguments.len);
        for (instance.arguments, arguments) |argument, *argument_type| {
            if (argument.value != .type) return null;
            argument_type.* = argument.value.type;
        }
        return .{ .function = instance.template, .arguments = arguments };
    }

    fn finishStructForEvaluator(
        context: *anyopaque,
        struct_type: *const ast.StructType,
        value_type: types.Type,
        location: token.Location,
    ) AnalyzeError!void {
        const self: *TypeChecker = @ptrCast(@alignCast(context));
        const resolver = &self.resolver.?;
        try resolver.finishStruct(resolver.context, struct_type, value_type, location);
        const caller_module_index = self.evaluator.module_index;
        defer self.evaluator.module_index = caller_module_index;
        try self.checkFieldDefaults(value_type.@"struct");
    }

    fn decidesAlone(self: *TypeChecker, binary: ast.Binary) TypeError!bool {
        if (binary.operator == .@"catch") return false;
        if (!self.evaluator.isKnownWithoutCalls(binary.left.*)) return false;
        const left = self.evaluateValue(binary.left) catch |evaluate_error| {
            if (evaluate_error != error.CannotEvaluate) return evaluate_error;
            self.failure = null;
            self.failed_function = null;
            return false;
        };
        return switch (binary.operator) {
            .@"and" => !left.boolean,
            .@"or" => left.boolean,
            .@"orelse" => left.optional != null,
            .multiply,
            .divide,
            .remainder,
            .add,
            .subtract,
            .shift_left,
            .shift_right,
            .bitwise_and,
            .bitwise_exclusive_or,
            .bitwise_or,
            .combine,
            .result,
            .@"catch",
            .equal,
            .not_equal,
            .less_than,
            .less_than_or_equal,
            .greater_than,
            .greater_than_or_equal,
            => unreachable,
        };
    }

    fn checkCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        if (expression.kind == .method_call) try self.resolveMethodCall(parameters, expression);
        if (expression.kind.call.constructor != null) try self.resolveConstructorCall(parameters, expression);
        try self.fillDefaultArguments(expression);
        if (ast.extractResolution(expression.kind.call.callee) == .typeclass_method) {
            try self.resolveTypeclassCall(parameters, expression);
            try self.fillDefaultArguments(expression);
        }
        if (expression.kind.call.callee == .member) {
            const member = expression.kind.call.callee.member;
            if (member.typeclass_arguments.len > 0) expression.kind.call.typeclass_arguments = member.typeclass_arguments;
        }
        try self.addressLiteralArguments(&expression.kind.call);
        const call = expression.kind.call;
        if (call.with_value != null) try self.expectCallTakesAllocator(call);
        const value_type = switch (ast.extractResolution(call.callee)) {
            .function => try self.checkPreparedCall(parameters, expression),
            .typeclass_function => try self.checkTypeclassFunctionCall(parameters, expression),
            .typeclass_method => unreachable,
            .parameter, .local, .constant, .element => try self.checkValueCall(parameters, expression),
            .case => |case| try self.checkCaseCall(parameters, expression, case),
            .builtin => |builtin| try self.checkBuiltinCall(parameters, expression, builtin),
            .type => unreachable,
        };
        expression.type = value_type;
        return value_type;
    }

    fn fillDefaultArguments(self: *TypeChecker, expression: *ast.Expression) TypeError!void {
        const call = &expression.kind.call;
        const resolution = ast.extractResolution(call.callee);
        switch (resolution) {
            .function, .typeclass_function, .typeclass_method => {},
            .parameter, .type, .constant, .local, .element, .case, .builtin => return,
        }
        const call_parameters = self.extractSignature(resolution).parameters;
        if (call.arguments.len >= call_parameters.len) return;
        const allocator = self.arena.allocator();
        var arguments: std.ArrayList(ast.Argument) = .empty;
        try arguments.appendSlice(allocator, call.arguments);
        for (call_parameters[call.arguments.len..], call.arguments.len..) |parameter, position| {
            if (parameter.hidden) break;
            const constant = self.findParameterDefault(resolution, position) orelse break;
            try self.prepareParameterDefault(parameter, constant);
            const name: ast.Identifier = .{ .name = parameter.name, .resolution = .{ .constant = constant } };
            const value: ast.Expression = .{ .kind = .{ .identifier = name }, .location = expression.location };
            try arguments.append(allocator, .{ .name = null, .value = value, .location = expression.location });
        }
        call.arguments = arguments.items;
    }

    fn findParameterDefault(self: *const TypeChecker, resolution: ast.Resolution, position: usize) ?ast.Resolution.Constant {
        const signature = self.extractSignature(resolution);
        if (signature.parameters[position].default_constant) |constant| return constant;
        if (resolution != .function) return null;
        const modules = self.program.modules;
        const declaration = ast.findDeclaration(modules[resolution.function.module], resolution.function.declaration);
        if (declaration.kind != .function_definition) return null;
        const reference = declaration.kind.function_definition.instance orelse return null;
        const instance_declaration = modules[reference.module].declarations[reference.declaration].kind.instance_declaration;
        const typeclass = instance_declaration.resolved orelse return null;
        const definition = self.extractTypeclass(typeclass);
        const index = findTypeclassFunction(definition, signature.name) orelse return null;
        const expected = definition.functions[index].parameters;
        if (position >= expected.len) return null;
        return expected[position].default_constant;
    }

    fn prepareParameterDefault(self: *TypeChecker, parameter: ast.TypedName, constant: ast.Resolution.Constant) TypeError!void {
        const inherited = parameter.inherited_default orelse return self.prepareWrittenDefault(parameter, constant);
        if (!std.meta.eql(inherited.constant, constant)) return self.prepareWrittenDefault(parameter, constant);
        self.prepareWrittenDefault(parameter, constant) catch |check_error| {
            if (check_error == error.OutOfMemory) return check_error;
            return self.failUnfitInstanceDefault(parameter, inherited);
        };
    }

    fn failUnfitInstanceDefault(self: *TypeChecker, parameter: ast.TypedName, inherited: ast.InheritedDefault) TypeError {
        const allocator = self.arena.allocator();
        const failure = self.fail(parameter.type.location, error.UnfitInstanceDefault);
        const modules = self.program.modules;
        const constant = ast.findDeclaration(modules[inherited.constant.module], inherited.constant.declaration).kind.constant_declaration;
        const type_name = try ast.renderTypeName(allocator, modules, ast.extractType(constant.type.?));
        const format = "the default that `{s}` gives `{s}` does not fit `{s}`, the type this instance gives `{s}`";
        self.failure.?.module = modules[inherited.constant.module].path;
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ self.extractTypeclass(inherited.typeclass).name, parameter.name, type_name, parameter.name });
        return failure;
    }

    fn prepareWrittenDefault(self: *TypeChecker, parameter: ast.TypedName, constant: ast.Resolution.Constant) TypeError!void {
        const value_type = try self.checkConstant(constant);
        if (parameter.kind == .implicit and value_type != .tuple) {
            const declaration = ast.findDeclaration(self.program.modules[constant.module], constant.declaration);
            return self.fail(declaration.kind.constant_declaration.value.location, error.TypeMismatch);
        }
        _ = try self.evaluateConstant(constant);
    }

    fn checkParameterDefaults(self: *TypeChecker, parameters: []const ast.TypedName) TypeError!void {
        for (parameters) |parameter| {
            const constant = parameter.default_constant orelse continue;
            try self.prepareParameterDefault(parameter, constant);
        }
    }

    fn checkInstanceDefaults(self: *TypeChecker, module: ast.Module, index: usize) TypeError!void {
        const instance_declaration = module.declarations[index].kind.instance_declaration;
        const typeclass = instance_declaration.resolved orelse return;
        const definition = self.extractTypeclass(typeclass);
        for (module.declarations[index + 1 .. index + 1 + instance_declaration.functions]) |declaration| {
            const signature = declaration.kind.function_definition.signature;
            const position = findTypeclassFunction(definition, signature.name) orelse continue;
            for (signature.parameters, definition.functions[position].parameters) |parameter, expected| {
                const written = parameter.default orelse {
                    if (parameter.inherited_default) |inherited| try self.prepareParameterDefault(parameter, inherited.constant);
                    continue;
                };
                const constant = parameter.default_constant orelse continue;
                const location = written.location;
                const inherited = if (parameter.inherited_default) |inherited| inherited.constant else null;
                const expected_constant = expected.default_constant orelse inherited orelse {
                    return self.fail(location, error.InstanceDefaultMismatch);
                };
                try self.prepareParameterDefault(parameter, constant);
                try self.prepareParameterDefault(parameter, expected_constant);
                const value = try self.evaluateConstant(constant);
                const expected_value = try self.evaluateConstant(expected_constant);
                if (!self.evaluator.isSameKey(value.*, expected_value.*)) return self.fail(location, error.InstanceDefaultMismatch);
            }
        }
    }

    fn addressLiteralArguments(self: *TypeChecker, call: *ast.Call) TypeError!void {
        const resolution = ast.extractResolution(call.callee);
        if (resolution != .function and resolution != .typeclass_function) return;
        const call_parameters = self.extractSignature(resolution).parameters;
        for (call.arguments, 0..) |*argument, position| {
            if (position >= call_parameters.len) break;
            if (argument.value.kind != .string_literal) continue;
            const written = call_parameters[position].type;
            if (written.kind != .pointer_type or written.kind.pointer_type.many or !written.kind.pointer_type.constant) continue;
            const operand = try self.arena.allocator().create(ast.Expression);
            operand.* = argument.value;
            argument.value = .{ .kind = .{ .address_of = operand }, .location = operand.location, .implicit = true };
        }
    }

    fn resolveMethodCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        const method_call = expression.kind.method_call;
        const receiver = try self.inferType(parameters, method_call.receiver);
        const name = method_call.name;
        const lookup: MethodLookup = .{ .location = method_call.name_location, .name = name, .crossing = method_call.crossing, .parameters = parameters, .arguments = method_call.arguments, .receiver = method_call.receiver };
        const method = try self.findMethodFunction(&lookup, receiver);
        const signature = self.extractSignature(method.function);
        if (signature.self_parameter == .none) {
            return self.fail(method_call.name_location, error.NoSelf);
        }
        const handed = signature.parameters.len > 0 and signature.parameters[0].own;
        if (method_call.receiver_own and !handed) return self.failMarkedReceiver(method_call);
        const allocator = self.arena.allocator();
        const arguments = try allocator.alloc(ast.Argument, method_call.arguments.len + 1);
        arguments[0] = .{
            .name = null,
            .value = if (handed and signature.self_parameter != .value)
                try self.buildHandedReceiver(parameters, method_call.receiver, method.dereferenced)
            else if (method.addressed)
                try self.buildAddressedReceiver(parameters, method_call.receiver, method.reads_only)
            else
                try self.buildReceiver(parameters, method_call.receiver, method.dereferenced, signature),
            .location = method_call.receiver.location,
            .own = method_call.receiver_own,
            .receiver = handed,
        };
        @memcpy(arguments[1..], method_call.arguments);
        const callee: ast.Identifier = .{ .name = name, .resolution = method.function };
        const call: ast.Call = .{
            .callee = .{ .identifier = callee },
            .arguments = arguments,
            .typeclass_arguments = method.typeclass_arguments,
            .with_value = method_call.with_value,
        };
        expression.kind = .{ .call = call };
    }

    fn resolveConstructorCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        const call = &expression.kind.call;
        const constructor = call.constructor.?;
        const path = call.callee.path_expression.path;
        const name = path[path.len - 1];
        const allocator = self.arena.allocator();
        const resolver = &self.resolver.?;
        const signature = self.extractSignature(.{ .function = constructor });
        const count = signature.parameters.len;
        for (signature.parameters) |parameter| {
            if (parameter.kind != .type) return self.failUndecidedConstructor(expression, parameter.name);
        }
        const locations = try allocator.alloc(?token.Location, count);
        @memset(locations, null);
        var decided: []?types.Argument = &.{};
        if (count > 0) {
            const outcome = try resolver.resolveConstructorPatterns(resolver.context, constructor, name);
            const found = switch (outcome) {
                .unseen, .nested => return self.failHiddenConstructor(expression, outcome),
                .missing => return self.fail(expression.location, error.UnknownMethod),
                .found => |found| found,
            };
            decided = try allocator.alloc(?types.Argument, found.count);
            @memset(decided, null);
            const matched = try allocator.alloc(?types.Argument, found.count);
            for (call.arguments, 0..) |*argument, position| {
                if (position >= found.patterns.len) break;
                const pattern = found.patterns[position] orelse continue;
                try self.matchDeclaredArgument(parameters, argument, pattern, decided, matched);
                for (matched[0..count], locations) |current, *location| {
                    if (current != null and location.* == null) location.* = argument.location;
                }
            }
            for (signature.parameters, decided[0..count]) |parameter, one| {
                const argument = one orelse return self.failUndecidedConstructor(expression, parameter.name);
                if (argument != .type) return self.failUndecidedConstructor(expression, parameter.name);
            }
        }
        const arguments = try allocator.alloc(ast.Argument, count);
        for (arguments, decided[0..count], locations) |*argument, one, deciding| {
            const value_type = one.?.type;
            const location = deciding orelse expression.location;
            const identifier: ast.Identifier = .{ .name = "_", .resolution = .{ .type = value_type } };
            argument.* = .{ .name = null, .value = .{ .kind = .{ .identifier = identifier }, .location = location, .denoted = value_type }, .location = location };
        }
        const owner = try allocator.create(ast.Expression);
        const owner_callee: ast.PathExpression = .{ .path = path[0 .. path.len - 1], .resolution = .{ .function = constructor } };
        owner.* = .{ .kind = .{ .call = .{ .callee = .{ .path_expression = owner_callee }, .arguments = arguments } }, .location = expression.location };
        const crossings = call.callee.path_expression.crossings;
        const crossed = crossings.len > 0 and crossings[crossings.len - 1];
        const resolution = try resolver.resolveConstructorMember(resolver.context, self.current_function, self.module_index, owner, name, crossed, expression.location);
        call.callee = .{ .member = .{ .owner = owner, .name = name, .crossing = crossed, .resolution = resolution } };
        call.constructor = null;
    }

    fn failUndecidedConstructor(self: *TypeChecker, expression: *const ast.Expression, parameter_name: []const u8) TypeError {
        const allocator = self.arena.allocator();
        const failure = self.fail(expression.location, error.UndecidedConstructorArgument);
        const constructor = try renderConstructorName(allocator, expression.kind.call);
        const form = try self.renderConstructorForm(expression.kind.call);
        const format = "the arguments of the call do not decide `{s}` of `{s}`; write it out, e.g. `{s}`";
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ parameter_name, constructor, form });
        return failure;
    }

    fn failHiddenConstructor(self: *TypeChecker, expression: *const ast.Expression, reason: ConstructorPatterns) TypeError {
        const allocator = self.arena.allocator();
        const failure = self.fail(expression.location, error.HiddenConstructorSignature);
        const call = expression.kind.call;
        const constructor = try renderConstructorName(allocator, call);
        const name = findCalleeName(call.callee);
        const form = try self.renderConstructorForm(call);
        self.failure.?.message = switch (reason) {
            .unseen => try std.fmt.allocPrint(allocator, "the arguments of `{s}` are left out only when it gives, in its last line and with no other return, a struct written there or the type of another such function; write them out, e.g. `{s}`", .{ constructor, form }),
            .nested => try std.fmt.allocPrint(allocator, "a parameter of `{s}` names a declaration in the block of the struct that `{s}` gives, so the arguments of `{s}` cannot be left out; write them out, e.g. `{s}`", .{ name, constructor, constructor, form }),
            .missing, .found => unreachable,
        };
        return failure;
    }

    fn renderConstructorForm(self: *TypeChecker, call: ast.Call) TypeError![]const u8 {
        const allocator = self.arena.allocator();
        const signature = self.extractSignature(.{ .function = call.constructor.? });
        var names: std.ArrayList([]const u8) = .empty;
        for (signature.parameters) |parameter| try names.append(allocator, parameter.name);
        var arguments: std.ArrayList([]const u8) = .empty;
        for (call.arguments) |argument| {
            const rendered = try renderExpression(allocator, argument.value) orelse {
                arguments.clearRetainingCapacity();
                try arguments.append(allocator, "...");
                break;
            };
            try arguments.append(allocator, if (argument.own) try std.mem.concat(allocator, u8, &.{ "own ", rendered }) else rendered);
        }
        const constructor = try renderConstructorName(allocator, call);
        const parameter_list = try std.mem.join(allocator, ", ", names.items);
        const argument_list = try std.mem.join(allocator, ", ", arguments.items);
        return std.fmt.allocPrint(allocator, "{s}({s})::{s}({s})", .{ constructor, parameter_list, findCalleeName(call.callee), argument_list });
    }

    fn failMarkedReceiver(self: *TypeChecker, method_call: ast.MethodCall) TypeError {
        const allocator = self.arena.allocator();
        const failure = self.fail(method_call.receiver.location, error.ReceiverNotTakenOver);
        const receiver = try renderExpression(allocator, method_call.receiver.*) orelse "the value";
        const format = "`{s}` does not take over its receiver, so `{s}` is not handed to it with own, e.g. `{s}.{s}()`";
        self.failure.?.message = try std.fmt.allocPrint(allocator, format, .{ method_call.name, receiver, receiver, method_call.name });
        return failure;
    }

    fn resolveTypeclassCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        const call = &expression.kind.call;
        const callee_resolution: *?ast.Resolution = switch (call.callee) {
            inline else => |*name| &name.resolution,
        };
        const method = callee_resolution.*.?.typeclass_method;
        const signature = self.extractSignature(callee_resolution.*.?);
        const module = self.program.modules[self.module_index];
        if (!isTypeclassVisible(module, self.module_index, method.typeclass)) {
            return self.fail(expression.location, error.UnknownMethod);
        }
        if (!acceptsArgumentCount(signature, call.arguments.len)) {
            return self.fail(expression.location, error.ArgumentCountMismatch);
        }
        const definition = self.extractTypeclass(method.typeclass);
        const decided = try self.arena.allocator().alloc(?types.Argument, definition.parameters.len);
        @memset(decided, null);
        var deciding: ?token.Location = null;
        var read_only: ?usize = null;
        for (call.arguments, signature.parameters[0..call.arguments.len], 0..) |*argument, parameter, position| {
            if (parameter.kind != .run_time) continue;
            const parameter_type = ast.extractType(parameter.type);
            if (!types.containsVariable(parameter_type, .typeclass)) continue;
            if (parameter.default != null and !hasOwnType(argument.value)) continue;
            const argument_type = try self.inferType(parameters, &argument.value);
            if (parameter_type == .pointer and argument_type == .pointer) {
                const modifies = !parameter_type.pointer.constant;
                if (modifies and argument_type.pointer.constant) read_only = position;
            }
            if (!types.matchType(parameter_type, argument_type, .typeclass, decided, false)) {
                return self.fail(argument.location, error.TypeMismatch);
            }
            if (deciding == null) deciding = argument.location;
        }
        if (try self.decideTypeArguments(parameters, &definition, &signature, call.arguments, 0, decided)) |location| deciding = location;
        const location = deciding orelse return self.fail(expression.location, error.UndecidedInstance);
        const found = try self.findTypeclassMethod(location, method, decided, signature.name);
        if (read_only) |position| try self.expectReadOnlyParameter(found.resolution, position, call.arguments[position].location);
        callee_resolution.* = found.resolution;
        call.typeclass_arguments = found.typeclass_arguments;
    }

    fn decideTypeArguments(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        definition: *const ast.TypeclassDefinition,
        signature: *const ast.FunctionSignature,
        arguments: []ast.Argument,
        first: usize,
        decided: []?types.Argument,
    ) TypeError!?token.Location {
        var location: ?token.Location = null;
        for (arguments, signature.parameters[first..][0..arguments.len], first..) |*argument, parameter, position| {
            if (parameter.kind != .type) continue;
            const index = findTypeclassParameter(definition.*, parameter.name) orelse continue;
            if (argument.value.kind == .inferred_type) {
                try self.fillTypeArgument(&argument.value, ast.extractType(signature.return_type), position, signature.parameters.len);
            }
            decided[index] = .{ .type = try self.checkTypeArgument(parameters, &argument.value) };
            location = argument.location;
        }
        return location;
    }

    fn fillTemplateTypeArgument(
        self: *TypeChecker,
        template: ast.Resolution.Function,
        argument: *ast.Expression,
        position: usize,
    ) TypeError!void {
        const resolver = &self.resolver.?;
        const pattern = try resolver.resolveReturnPattern(resolver.context, template);
        const count = self.extractSignature(.{ .function = template }).parameters.len;
        try self.fillTypeArgument(argument, pattern, position, count);
    }

    fn fillTypeArgument(
        self: *TypeChecker,
        argument: *ast.Expression,
        return_type: types.Type,
        position: usize,
        count: usize,
    ) TypeError!void {
        const found = try self.findExpectedArgument(argument, return_type, position, count);
        argument.kind = .{ .identifier = .{ .name = "_", .resolution = .{ .type = found } } };
    }

    fn findExpectedArgument(
        self: *TypeChecker,
        argument: *const ast.Expression,
        return_type: types.Type,
        position: usize,
        count: usize,
    ) TypeError!types.Type {
        var expected = argument.kind.inferred_type.expected orelse return self.fail(argument.location, error.UnknownTypeArgument);
        var pattern = return_type;
        if (pattern == .result) pattern = pattern.result.value;
        if (expected == .result) expected = expected.result.value;
        if (pattern == .optional and expected != .optional) pattern = pattern.optional.child;
        const assigned = try self.arena.allocator().alloc(?types.Argument, count);
        @memset(assigned, null);
        if (!types.matchType(pattern, expected, .function, assigned, false)) return self.fail(argument.location, error.UnknownTypeArgument);
        const found = assigned[position] orelse return self.fail(argument.location, error.UnknownTypeArgument);
        return found.type;
    }

    fn extractTypeclass(self: *const TypeChecker, typeclass: ast.Resolution.Typeclass) ast.TypeclassDefinition {
        return self.program.modules[typeclass.module].declarations[typeclass.declaration].kind.typeclass_definition;
    }

    fn findTypeclassMethod(
        self: *TypeChecker,
        location: token.Location,
        method: ast.Resolution.TypeclassFunction,
        decided: []const ?types.Argument,
        name: []const u8,
    ) TypeError!Found {
        if (containsVariable(decided)) {
            for (self.constraints) |constraint| {
                if (!std.meta.eql(constraint.typeclass, method.typeclass)) continue;
                if (!matchesConstraint(constraint, decided)) continue;
                return .{ .resolution = .{ .typeclass_function = method }, .typeclass_arguments = constraint.arguments };
            }
            return self.fail(location, error.NoInstance);
        }
        const function = (try self.findInstanceFunction(location, method.typeclass, decided, name)) orelse {
            return self.fail(location, error.NoInstance);
        };
        return .{ .resolution = .{ .function = function } };
    }

    fn findInstanceFunction(
        self: *TypeChecker,
        location: token.Location,
        typeclass: ast.Resolution.Typeclass,
        decided: []const ?types.Argument,
        name: []const u8,
    ) TypeError!?ast.Resolution.Function {
        const modules = self.program.modules;
        const found = switch (try ast.findInstance(self.arena.allocator(), modules, self.program.types, typeclass, decided)) {
            .missing => return null,
            .missing_requirement => return self.fail(location, error.MissingRequiredInstance),
            .ambiguous => |pair| return self.failAmbiguous(location, pair),
            .undecided => return self.fail(location, error.UndecidedInstance),
            .found => |found| found,
        };
        const function = ast.findInstanceMember(modules, found.reference, name) orelse return null;
        const instance_declaration = modules[found.reference.module].declarations[found.reference.declaration];
        if (instance_declaration.kind.instance_declaration.parameters.len == 0) return function;
        const resolver = &self.resolver.?;
        return try resolver.instantiateInstanceFunction(resolver.context, function, found.assigned);
    }

    fn buildHandedReceiver(self: *TypeChecker, parameters: []const ast.TypedName, receiver: *ast.Expression, dereferenced: bool) TypeError!ast.Expression {
        if (dereferenced) return receiver.*;
        const operand = try self.arena.allocator().create(ast.Expression);
        operand.* = receiver.*;
        var address: ast.Expression = .{ .kind = .{ .address_of = operand }, .location = receiver.location, .handed = true };
        _ = try self.checkAddressOf(parameters, &address);
        return address;
    }

    fn buildAddressedReceiver(self: *TypeChecker, parameters: []const ast.TypedName, receiver: *ast.Expression, reads_only: bool) TypeError!ast.Expression {
        const operand = try self.arena.allocator().create(ast.Expression);
        operand.* = receiver.*;
        var address: ast.Expression = .{ .kind = .{ .address_of = operand }, .location = receiver.location, .implicit = reads_only };
        const address_type = try self.checkAddressOf(parameters, &address);
        if (address_type.pointer.constant and !reads_only) return self.fail(receiver.location, error.NotWritable);
        return address;
    }

    fn buildReceiver(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        receiver: *ast.Expression,
        dereferenced: bool,
        signature: ast.FunctionSignature,
    ) TypeError!ast.Expression {
        const pointer = signature.self_parameter != .value;
        const modifies = signature.self_parameter == .pointer;
        if (pointer == dereferenced) {
            if (modifies and receiver.type.?.pointer.constant) return self.fail(receiver.location, error.NotWritable);
            return receiver.*;
        }
        const operand = try self.arena.allocator().create(ast.Expression);
        operand.* = receiver.*;
        if (!pointer) return .{ .kind = .{ .dereference = operand }, .location = receiver.location };
        var address: ast.Expression = .{ .kind = .{ .address_of = operand }, .location = receiver.location, .implicit = !modifies };
        const address_type = try self.checkAddressOf(parameters, &address);
        if (modifies and address_type.pointer.constant) return self.fail(receiver.location, error.NotWritable);
        return address;
    }

    fn findMethodFunction(self: *TypeChecker, lookup: *const MethodLookup, receiver: types.Type) TypeError!Method {
        const location = lookup.location;
        if (try self.searchMethod(lookup, receiver)) |found| {
            return .{ .function = found.resolution, .dereferenced = false, .typeclass_arguments = found.typeclass_arguments };
        }
        if (receiver != .pointer) {
            if (!isWritable(lookup.receiver.*)) {
                const read_only = try self.program.types.addPointer(self.arena.allocator(), .{ .target = receiver, .many = false, .constant = true });
                if (try self.searchMethod(lookup, .{ .pointer = read_only })) |found| {
                    return .{ .function = found.resolution, .dereferenced = false, .addressed = true, .reads_only = true, .typeclass_arguments = found.typeclass_arguments };
                }
            }
            const pointer = try self.program.types.addPointer(self.arena.allocator(), .{ .target = receiver, .many = false, .constant = false });
            const addressed = (try self.searchMethod(lookup, .{ .pointer = pointer })) orelse {
                return self.fail(location, error.UnknownMethod);
            };
            return .{ .function = addressed.resolution, .dereferenced = false, .addressed = true, .typeclass_arguments = addressed.typeclass_arguments };
        }
        if (receiver.pointer.many) return self.fail(location, error.UnknownMethod);
        const found = (try self.searchMethod(lookup, receiver.pointer.target)) orelse {
            return self.fail(location, error.UnknownMethod);
        };
        return .{ .function = found.resolution, .dereferenced = true, .typeclass_arguments = found.typeclass_arguments };
    }

    fn searchMethod(self: *TypeChecker, lookup: *const MethodLookup, receiver: types.Type) TypeError!?Found {
        const location = lookup.location;
        if (try self.findConstraintMethod(lookup, receiver)) |found| return found;
        if (ast.findOwnMethod(self.program.modules, receiver, lookup.name)) |function| {
            try self.expectReachableFunction(location, receiver, function, buildMethodCrossing(lookup));
            return .{ .resolution = .{ .function = function } };
        }
        var found: ?Found = null;
        const module = self.program.modules[self.module_index];
        for (module.declarations, 0..) |declaration, index| {
            const typeclass: ast.Resolution.Typeclass = switch (declaration.kind) {
                .typeclass_definition => .{ .module = self.module_index, .declaration = index },
                .import => |import| import.typeclass orelse continue,
                .function_declaration,
                .function_definition,
                .constant_declaration,
                .struct_definition,
                .enum_definition,
                .instance_declaration,
                => continue,
            };
            const function = (try self.findTypeclassMethodFor(lookup, typeclass, receiver)) orelse continue;
            if (found) |earlier| {
                if (!std.meta.eql(earlier.resolution, function)) return self.fail(location, error.AmbiguousMethod);
            }
            found = .{ .resolution = function };
        }
        return found;
    }

    fn hasTypeclassInstance(self: *TypeChecker, typeclass: ast.Resolution.Typeclass, value_type: types.Type) TypeError!bool {
        const decided: []const ?types.Argument = &.{.{ .type = value_type }};
        return switch (try ast.findInstance(self.arena.allocator(), self.program.modules, self.program.types, typeclass, decided)) {
            .found => true,
            .missing, .missing_requirement, .ambiguous, .undecided => false,
        };
    }

    fn findTypeclassMethodFor(
        self: *TypeChecker,
        lookup: *const MethodLookup,
        typeclass: ast.Resolution.Typeclass,
        receiver: types.Type,
    ) TypeError!?ast.Resolution {
        const location = lookup.location;
        const name = lookup.name;
        const definition = self.extractTypeclass(typeclass);
        const position = findTypeclassFunction(definition, name) orelse return null;
        const signature = definition.functions[position];
        if (signature.self_parameter == .none) return null;
        try self.expectReachableTypeclassFunction(location, typeclass, position, buildMethodCrossing(lookup));
        const decided = try self.arena.allocator().alloc(?types.Argument, definition.parameters.len);
        @memset(decided, null);
        const first = types.followPointer(ast.extractType(signature.parameters[0].type));
        decided[first.variable.index] = .{ .type = receiver };
        if (hasTypeclassTypeParameter(definition, signature)) return self.findSelectedMethod(lookup, typeclass, &definition, &signature, decided);
        const function = (try self.findInstanceFunction(location, typeclass, decided, name)) orelse return null;
        return .{ .function = function };
    }

    fn findSelectedMethod(
        self: *TypeChecker,
        lookup: *const MethodLookup,
        typeclass: ast.Resolution.Typeclass,
        definition: *const ast.TypeclassDefinition,
        signature: *const ast.FunctionSignature,
        decided: []?types.Argument,
    ) TypeError!?ast.Resolution {
        switch (try ast.findInstance(self.arena.allocator(), self.program.modules, self.program.types, typeclass, decided)) {
            .missing => return null,
            .missing_requirement => return self.fail(lookup.location, error.MissingRequiredInstance),
            .found, .ambiguous, .undecided => {},
        }
        if (!acceptsArgumentCount(signature.*, lookup.arguments.len + 1)) return self.fail(lookup.location, error.ArgumentCountMismatch);
        const location = (try self.decideTypeArguments(lookup.parameters, definition, signature, lookup.arguments, 1, decided)) orelse lookup.location;
        const function = (try self.findInstanceFunction(location, typeclass, decided, lookup.name)) orelse return self.fail(location, error.NoInstance);
        return .{ .function = function };
    }

    fn findConstraintMethod(self: *TypeChecker, lookup: *const MethodLookup, receiver: types.Type) TypeError!?Found {
        const location = lookup.location;
        const name = lookup.name;
        var mentioned = false;
        for (self.constraints) |constraint| {
            if (!mentionsReceiver(constraint, receiver)) continue;
            mentioned = true;
            const definition = self.extractTypeclass(constraint.typeclass);
            const position = findTypeclassFunction(definition, name) orelse continue;
            const signature = definition.functions[position];
            if (signature.self_parameter == .none) continue;
            try self.expectReachableTypeclassFunction(location, constraint.typeclass, position, buildMethodCrossing(lookup));
            const first = types.followPointer(ast.extractType(signature.parameters[0].type));
            const argument = constraint.arguments[first.variable.index];
            if (argument != .type or !std.meta.eql(argument.type, receiver)) continue;
            if (!isConcreteArguments(constraint.arguments)) {
                const method: ast.Resolution.TypeclassFunction = .{ .typeclass = constraint.typeclass, .function = position };
                return .{ .resolution = .{ .typeclass_function = method }, .typeclass_arguments = constraint.arguments };
            }
            const function = (try self.findTypeclassMethodFor(lookup, constraint.typeclass, receiver)) orelse continue;
            return .{ .resolution = function };
        }
        const abstract = types.containsVariable(receiver, .function) or types.containsVariable(receiver, .typeclass);
        if (mentioned and abstract) return self.fail(location, error.UnknownMethod);
        return null;
    }

    fn expectInstance(
        self: *TypeChecker,
        location: token.Location,
        typeclass: ast.Resolution.Typeclass,
        value_type: types.Type,
    ) TypeError!void {
        return self.expectDecidedInstance(location, typeclass, &.{.{ .type = value_type }});
    }

    fn expectParameterInstance(
        self: *TypeChecker,
        location: token.Location,
        parameter: ast.TypedName,
        value_type: types.Type,
    ) TypeError!void {
        return self.expectDecidedInstance(location, parameter.constraint.?, try self.buildParameterDecided(parameter, value_type));
    }

    fn buildParameterDecided(self: *TypeChecker, parameter: ast.TypedName, value_type: types.Type) std.mem.Allocator.Error![]const ?types.Argument {
        const allocator = self.arena.allocator();
        const arguments = try ast.fillConstraintArguments(allocator, parameter, value_type);
        const decided = try allocator.alloc(?types.Argument, arguments.len);
        for (arguments, decided) |argument, *slot| slot.* = argument;
        return decided;
    }

    fn expectDecidedInstance(
        self: *TypeChecker,
        location: token.Location,
        typeclass: ast.Resolution.Typeclass,
        decided: []const ?types.Argument,
    ) TypeError!void {
        if (containsVariable(decided)) {
            for (self.constraints) |constraint| {
                if (std.meta.eql(constraint.typeclass, typeclass) and matchesConstraint(constraint, decided)) return;
            }
            return self.fail(location, error.NoInstance);
        }
        switch (try ast.findInstance(self.arena.allocator(), self.program.modules, self.program.types, typeclass, decided)) {
            .missing => return self.fail(location, error.NoInstance),
            .missing_requirement => return self.fail(location, error.MissingRequiredInstance),
            .found, .ambiguous, .undecided => {},
        }
    }

    fn extractSignature(self: *const TypeChecker, function: ast.Resolution) ast.FunctionSignature {
        const modules = self.program.modules;
        return switch (function) {
            .function => |resolved| {
                return ast.extractFunctionSignature(ast.findDeclaration(modules[resolved.module], resolved.declaration).*);
            },
            .typeclass_function, .typeclass_method => |resolved| {
                const typeclass = resolved.typeclass;
                const definition = modules[typeclass.module].declarations[typeclass.declaration].kind.typeclass_definition;
                return definition.functions[resolved.function];
            },
            .parameter, .type, .constant, .local, .element, .case, .builtin => unreachable,
        };
    }

    fn checkBuiltinCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        builtin: ast.Builtin,
    ) TypeError!types.Type {
        const arguments = expression.kind.call.arguments;
        const count: usize = switch (builtin) {
            .size, .alignment, .length, .@"error" => 1,
            .convert, .truncate, .cast, .@"align", .join, .add_wrapping, .subtract_wrapping, .multiply_wrapping => 2,
        };
        if (arguments.len != count) return self.fail(expression.location, error.ArgumentCountMismatch);
        for (arguments) |argument| {
            if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
        }
        if (builtin == .@"align") return self.checkAlign(parameters, expression);
        if (builtin == .@"error") return self.fail(expression.location, error.ComptimeErrorAsValue);
        if (ast.findWrappingOperator(builtin)) |operator| return self.checkWrapping(parameters, expression, operator);
        const type_argument = &arguments[0].value;
        if (type_argument.kind == .inferred_type) try self.fillBuiltinTypeArgument(type_argument, builtin);
        const target = try self.checkTypeArgument(parameters, type_argument);
        switch (builtin) {
            .length => {
                if (target != .tuple) return self.fail(type_argument.location, error.NotTupleType);
                return .{ .number = .usize };
            },
            .join => {
                if (target != .tuple) return self.fail(type_argument.location, error.NotTupleType);
                const other = &arguments[1].value;
                if (try self.checkTypeArgument(parameters, other) != .tuple) return self.fail(other.location, error.NotTupleType);
                return .type;
            },
            .size, .alignment => {
                if (types.isCompileTimeOnly(target) or target == .function) {
                    return self.fail(type_argument.location, error.NoLayout);
                }
                return .{ .number = .usize };
            },
            .convert, .truncate => {
                if (target != .number) return self.fail(type_argument.location, error.ExpectedNumber);
                const value = &arguments[1].value;
                const value_type = if (takesExpectedType(value.*)) value_type: {
                    try self.checkExpression(parameters, value, target);
                    break :value_type target;
                } else try self.inferType(parameters, value);
                if (value_type != .number) return self.fail(value.location, error.ExpectedNumber);
                if (builtin == .truncate) {
                    if (!isInteger(target)) return self.fail(type_argument.location, error.ExpectedInteger);
                    if (!isInteger(value_type)) return self.fail(value.location, error.ExpectedInteger);
                }
                expression.type = target;
                if (self.evaluator.isKnown(expression.*)) _ = try self.evaluateValue(expression);
                return target;
            },
            .cast => {
                if (!isDataPointer(target)) return self.fail(type_argument.location, error.ExpectedPointer);
                const value = &arguments[1].value;
                const value_type = try self.inferType(parameters, value);
                if (!isDataPointer(value_type)) return self.fail(value.location, error.ExpectedPointer);
                expression.type = target;
                return target;
            },
            .@"align", .@"error", .add_wrapping, .subtract_wrapping, .multiply_wrapping => unreachable,
        }
    }

    fn checkWrapping(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        operator: ast.BinaryOperator,
    ) TypeError!types.Type {
        const arguments = expression.kind.call.arguments;
        const binary: ast.Binary = .{
            .operator = operator,
            .operator_location = expression.location,
            .left = &arguments[0].value,
            .right = &arguments[1].value,
        };
        const operand_type = try self.checkOperands(parameters, binary, null);
        if (!isInteger(operand_type)) return self.fail(expression.location, error.NotInteger);
        expression.type = operand_type;
        return operand_type;
    }

    fn checkComptimeError(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const argument = &expression.kind.call.arguments[0].value;
        const allocator = self.arena.allocator();
        const text_type: types.Type = .{ .slice = try self.program.types.addSlice(allocator, .{ .number = .u8 }, true) };
        const caller_compile_time = self.compile_time;
        self.compile_time = true;
        defer self.compile_time = caller_compile_time;
        try self.checkExpression(parameters, argument, text_type);
        if (!self.evaluator.isKnown(argument.*)) return self.fail(argument.location, error.CannotEvaluate);
        const value = try self.evaluateValue(argument);
        const message = self.evaluator.readText(allocator, argument.location, value) catch |read_error| {
            self.adoptEvaluatorFailure();
            return read_error;
        };
        const comptime_error = self.fail(expression.location, error.ComptimeError);
        self.failure.?.message = message;
        return comptime_error;
    }

    fn checkAlign(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const arguments = expression.kind.call.arguments;
        const pointer = &arguments[0].value;
        const pointer_type = try self.inferType(parameters, pointer);
        if (!isDataPointer(pointer_type) or !pointer_type.pointer.many) {
            return self.fail(pointer.location, error.ExpectedManyPointer);
        }
        try self.checkExpression(parameters, &arguments[1].value, .{ .number = .usize });
        expression.type = pointer_type;
        return pointer_type;
    }

    fn fillBuiltinTypeArgument(self: *TypeChecker, argument: *ast.Expression, builtin: ast.Builtin) TypeError!void {
        if (builtin != .convert and builtin != .truncate and builtin != .cast) return self.fail(argument.location, error.UnknownTypeArgument);
        const expected = argument.kind.inferred_type.expected orelse return self.fail(argument.location, error.UnknownTypeArgument);
        const target = if (expected == .result) expected.result.value else expected;
        argument.kind = .{ .identifier = .{ .name = "_", .resolution = .{ .type = target } } };
    }

    fn checkTypeArgument(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        argument: *ast.Expression,
    ) TypeError!types.Type {
        try self.checkExpression(parameters, argument, .type);
        if (!self.evaluator.isKnown(argument.*)) return self.fail(argument.location, error.CannotEvaluate);
        const value_type = (try self.evaluateValue(argument)).type;
        argument.denoted = value_type;
        return value_type;
    }

    fn checkCaseCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        case: ast.Resolution.Case,
    ) TypeError!types.Type {
        const payload = case.enumeration.cases[case.index].type orelse {
            return self.fail(expression.location, error.CaseWithoutValue);
        };
        if (expression.kind.call.braces == .written) try self.gatherCaseValue(expression, payload);
        const call = expression.kind.call;
        if (call.arguments.len != 1) return self.fail(expression.location, error.ArgumentCountMismatch);
        const argument = &call.arguments[0];
        if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
        try self.checkExpression(parameters, &argument.value, payload);
        return .{ .@"enum" = case.enumeration };
    }

    fn gatherCaseValue(self: *TypeChecker, expression: *ast.Expression, payload: types.Type) CheckError!void {
        const call = &expression.kind.call;
        call.braces = .gathered;
        if (payload != .tuple) {
            if (call.arguments.len != 1) return self.fail(expression.location, error.CaseValueCount);
            return;
        }
        const location = if (call.arguments.len > 0) call.arguments[0].location else expression.location;
        const value: ast.Expression = .{ .kind = .{ .composite_literal = .{ .type = null, .elements = call.arguments } }, .location = location };
        call.arguments = try self.arena.allocator().dupe(ast.Argument, &.{.{ .name = null, .value = value, .location = location }});
    }

    fn checkPreparedCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const resolution = ast.extractResolution(expression.kind.call.callee);
        if (self.isGenericFunction(resolution)) try self.instantiateCall(parameters, expression, resolution.function);
        try self.resolveAllocatorCall(parameters, expression);
        try self.completeInferredErrorSet(ast.extractResolution(expression.kind.call.callee));
        return self.checkFunctionCall(parameters, expression);
    }

    fn isGenericFunction(self: *const TypeChecker, resolution: ast.Resolution) bool {
        return ast.isGeneric(self.extractSignature(resolution));
    }

    fn checkFunctionCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const call = expression.kind.call;
        const callee = self.extractSignature(ast.extractResolution(call.callee));
        if (callee.progress == .running) return self.fail(expression.location, error.DependencyLoop);
        if (types.isCompileTimeOnly(ast.extractType(callee.return_type))) {
            if (!self.compile_time) return self.fail(expression.location, error.CompileTimeValue);
        }
        if (ast.isMain(callee)) {
            return self.fail(expression.location, error.MainCalled);
        }
        if (call.arguments.len != callee.parameters.len) {
            return self.fail(expression.location, error.ArgumentCountMismatch);
        }
        for (call.arguments, callee.parameters) |*argument, parameter| {
            if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
            if (parameter.hidden and argument.value.kind == .address_of and argument.value.kind.address_of.kind == .composite_literal) continue;
            const parameter_type = try self.substituteTypeclass(ast.extractType(parameter.type), call.typeclass_arguments);
            try self.checkExpression(parameters, &argument.value, parameter_type);
        }
        expression.kind.call.@"inline" = callee.@"inline" and ast.extractResolution(call.callee) == .function;
        return self.substituteTypeclass(ast.extractType(callee.return_type), call.typeclass_arguments);
    }

    fn substituteTypeclass(self: *TypeChecker, value_type: types.Type, arguments: []const types.Argument) TypeError!types.Type {
        if (arguments.len == 0) return value_type;
        return types.substitute(self.arena.allocator(), self.program.types, value_type, arguments, .typeclass);
    }

    fn expectCallTakesAllocator(self: *TypeChecker, call: ast.Call) TypeError!void {
        const resolution = ast.extractResolution(call.callee);
        if (resolution == .function or resolution == .typeclass_function) return;
        return self.fail(call.with_value.?.location, error.AllocatorNotNeeded);
    }

    fn checkTypeclassFunctionCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const signature = self.extractSignature(ast.extractResolution(expression.kind.call.callee));
        if (ast.isGeneric(signature)) return self.checkGenericTypeclassCall(parameters, expression);
        return self.checkFunctionCall(parameters, expression);
    }

    fn checkGenericTypeclassCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const call = expression.kind.call;
        const callee = self.extractSignature(ast.extractResolution(call.callee));
        if (call.arguments.len != callee.parameters.len) return self.fail(expression.location, error.ArgumentCountMismatch);
        const allocator = self.arena.allocator();
        const assigned = try allocator.alloc(?types.Argument, callee.parameters.len + callee.declared.len);
        @memset(assigned, null);
        for (call.arguments, callee.parameters, 0..) |*argument, parameter, position| {
            if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
            if (parameter.kind == .type) {
                if (argument.value.kind == .inferred_type) {
                    const return_pattern = try self.substituteTypeclass(ast.extractType(callee.return_type), call.typeclass_arguments);
                    try self.fillTypeArgument(&argument.value, return_pattern, position, assigned.len);
                }
                const caller_compile_time = self.compile_time;
                self.compile_time = true;
                defer self.compile_time = caller_compile_time;
                try self.checkExpression(parameters, &argument.value, .type);
                if (!self.evaluator.isKnown(argument.value)) return self.fail(argument.location, error.CannotEvaluate);
                assigned[position] = .{ .type = (try self.evaluateValue(&argument.value)).type };
                continue;
            }
            const own_variables = try self.renameCalleeVariables(ast.extractType(parameter.type));
            const written = try self.substituteTypeclass(own_variables, call.typeclass_arguments);
            var pattern = try self.substituteAssigned(written, assigned);
            if (types.containsVariable(pattern, .declared)) {
                const argument_type = try self.adaptToPattern(pattern, try self.inferType(parameters, &argument.value));
                if (!types.matchType(pattern, argument_type, .declared, assigned, false)) return self.fail(argument.location, error.TypeMismatch);
                pattern = try self.substituteAssigned(written, assigned);
            }
            try self.checkExpression(parameters, &argument.value, pattern);
        }
        const return_variables = try self.renameCalleeVariables(ast.extractType(callee.return_type));
        const return_type = try self.substituteTypeclass(return_variables, call.typeclass_arguments);
        return self.substituteAssigned(return_type, assigned);
    }

    fn renameCalleeVariables(self: *TypeChecker, value_type: types.Type) TypeError!types.Type {
        return types.renameScope(self.arena.allocator(), self.program.types, value_type, .function, .declared);
    }

    fn substituteAssigned(self: *TypeChecker, value_type: types.Type, assigned: []const ?types.Argument) TypeError!types.Type {
        const allocator = self.arena.allocator();
        const arguments = try allocator.alloc(types.Argument, assigned.len);
        for (assigned, arguments, 0..) |one, *argument, index| {
            argument.* = one orelse .{ .type = .{ .variable = .{ .scope = .declared, .index = index } } };
        }
        return types.substitute(allocator, self.program.types, value_type, arguments, .declared);
    }

    fn instantiateCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        template: ast.Resolution.Function,
    ) TypeError!void {
        var bounds: std.ArrayList(Bound) = .empty;
        var arguments: std.ArrayList(ast.Argument) = .empty;
        try self.bindCallArguments(parameters, expression, template, &bounds, &arguments);
        const instance = try self.findInstance(expression.location, template, bounds.items);
        const call = &expression.kind.call;
        switch (call.callee) {
            inline else => |*name| name.resolution = .{ .function = instance },
        }
        call.arguments = arguments.items;
    }

    fn bindCallArguments(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        template: ast.Resolution.Function,
        bounds: *std.ArrayList(Bound),
        arguments: *std.ArrayList(ast.Argument),
    ) TypeError!void {
        const call = &expression.kind.call;
        const signature = self.extractSignature(.{ .function = template });
        if (call.arguments.len != signature.parameters.len) {
            return self.fail(expression.location, error.ArgumentCountMismatch);
        }
        const allocator = self.arena.allocator();
        const resolver = &self.resolver.?;
        for (call.arguments, signature.parameters, 0..) |*argument, parameter, position| {
            if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
            const parameter_type: types.Type = switch (parameter.kind) {
                .run_time => {
                    try arguments.append(allocator, argument.*);
                    continue;
                },
                .any => {
                    const argument_type = try self.inferType(parameters, &argument.value);
                    try bounds.append(allocator, .{ .type = .type, .value = .{ .type = argument_type } });
                    try arguments.append(allocator, argument.*);
                    continue;
                },
                .implicit => {
                    const argument_type = try self.inferType(parameters, &argument.value);
                    const bound = try self.checkImplicitArgument(argument, parameter, argument_type);
                    try bounds.append(allocator, .{ .type = .type, .value = .{ .type = bound } });
                    try arguments.append(allocator, argument.*);
                    continue;
                },
                .type => type_parameter: {
                    if (argument.value.kind == .inferred_type) try self.fillTemplateTypeArgument(template, &argument.value, position);
                    break :type_parameter .type;
                },
                .compile_time => try resolver.resolveParameterType(resolver.context, template, position, bounds.items),
            };
            const caller_compile_time = self.compile_time;
            self.compile_time = true;
            defer self.compile_time = caller_compile_time;
            try self.checkExpression(parameters, &argument.value, parameter_type);
            if (!self.evaluator.isKnown(argument.value)) return self.fail(argument.location, error.RuntimeArgument);
            const value = try self.evaluateValue(&argument.value);
            for (parameter.resolved_requirements) |requirement| {
                if (requirement.arguments.len == 0) try self.expectInstance(argument.location, requirement.typeclass, value.type);
            }
            try bounds.append(allocator, .{ .type = parameter_type, .value = value });
        }
        try self.inferDeclaredTypes(parameters, expression, template, bounds);
        try self.expectArgumentRequirements(expression, template, bounds.items);
    }

    fn expectArgumentRequirements(
        self: *TypeChecker,
        expression: *const ast.Expression,
        template: ast.Resolution.Function,
        bounds: []const Bound,
    ) TypeError!void {
        const signature = self.extractSignature(.{ .function = template });
        const allocator = self.arena.allocator();
        const parameter_count = signature.parameters.len;
        const assigned = try allocator.alloc(?types.Argument, parameter_count + signature.declared.len);
        @memset(assigned, null);
        var bound_index: usize = 0;
        for (signature.parameters, 0..) |parameter, index| {
            if (parameter.kind == .run_time) continue;
            if (parameter.kind == .type) assigned[index] = .{ .type = bounds[bound_index].value.type };
            bound_index += 1;
        }
        for (signature.declared, 0..) |_, position| {
            assigned[parameter_count + position] = .{ .type = bounds[bound_index].value.type };
            bound_index += 1;
        }
        for (signature.parameters, expression.kind.call.arguments, 0..) |parameter, argument, index| {
            if (parameter.kind != .type) continue;
            try self.expectRequirementsWithArguments(argument.location, parameter.resolved_requirements, assigned[index].?, assigned);
        }
        for (signature.declared, 0..) |declared, position| {
            try self.expectRequirementsWithArguments(expression.location, declared.resolved_requirements, assigned[parameter_count + position].?, assigned);
        }
    }

    fn expectRequirementsWithArguments(
        self: *TypeChecker,
        location: token.Location,
        requirements: []const ast.Requirement,
        value: types.Argument,
        assigned: []const ?types.Argument,
    ) TypeError!void {
        for (requirements) |requirement| {
            if (requirement.arguments.len == 0) continue;
            const decided = try ast.decideRequirement(self.arena.allocator(), self.program.types, requirement, value, assigned, .function) orelse continue;
            try self.expectDecidedInstance(location, requirement.typeclass, decided);
        }
    }

    fn inferDeclaredTypes(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        template: ast.Resolution.Function,
        bounds: *std.ArrayList(Bound),
    ) TypeError!void {
        const signature = self.extractSignature(.{ .function = template });
        if (signature.declared.len == 0) return;
        const allocator = self.arena.allocator();
        const resolver = &self.resolver.?;
        const decided = try allocator.alloc(?types.Argument, signature.declared.len);
        @memset(decided, null);
        const found = try allocator.alloc(?types.Argument, signature.declared.len);
        for (expression.kind.call.arguments, signature.parameters, 0..) |*argument, parameter, position| {
            if (parameter.kind != .run_time) continue;
            const pattern = try resolver.resolveDeclaredPattern(resolver.context, template, position, bounds.items);
            try self.matchDeclaredArgument(parameters, argument, pattern, decided, found);
        }
        for (signature.declared, decided) |declared, one| {
            const argument = one orelse return self.fail(expression.location, error.TypeMismatch);
            for (declared.resolved_requirements) |requirement| {
                if (requirement.arguments.len == 0) try self.expectInstance(expression.location, requirement.typeclass, argument.type);
            }
            try bounds.append(allocator, .{ .type = .type, .value = .{ .type = argument.type } });
        }
    }

    fn matchDeclaredArgument(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        argument: *ast.Argument,
        pattern: types.Type,
        decided: []?types.Argument,
        found: []?types.Argument,
    ) TypeError!void {
        @memset(found, null);
        if (!types.containsVariable(pattern, .declared)) return;
        const argument_type = try self.adaptToPattern(pattern, try self.inferType(parameters, &argument.value));
        if (!types.matchType(pattern, argument_type, .declared, found, false)) return self.fail(argument.location, error.TypeMismatch);
        for (found, decided) |one, *earlier| {
            const current = one orelse continue;
            const previous = earlier.* orelse {
                earlier.* = current;
                continue;
            };
            if (!std.meta.eql(previous, current)) return self.fail(argument.location, error.ConflictingDeclaredType);
        }
    }

    fn adaptToPattern(self: *TypeChecker, pattern: types.Type, argument_type: types.Type) TypeError!types.Type {
        if (pattern != .slice or argument_type != .pointer or argument_type.pointer.many) return argument_type;
        const target = argument_type.pointer.target;
        if (target != .array) return argument_type;
        const slice = try self.program.types.addSlice(self.arena.allocator(), target.array.element, argument_type.pointer.constant);
        return .{ .slice = slice };
    }

    fn checkImplicitArgument(
        self: *TypeChecker,
        argument: *const ast.Argument,
        parameter: ast.TypedName,
        argument_type: types.Type,
    ) TypeError!types.Type {
        if (parameter.type.kind != .pointer_type) {
            try self.expectParameterInstance(argument.location, parameter, argument_type);
            return argument_type;
        }
        if (argument_type != .pointer or argument_type.pointer.many) return self.fail(argument.location, error.TypeMismatch);
        const target = argument_type.pointer.target;
        try self.expectParameterInstance(argument.location, parameter, target);
        const constant = parameter.type.kind.pointer_type.constant or argument_type.pointer.constant;
        if (constant and !parameter.type.kind.pointer_type.constant and !try self.instanceOnlyReads(parameter, target)) {
            return self.fail(argument.location, error.NotWritable);
        }
        const pointer = try self.program.types.addPointer(self.arena.allocator(), .{ .target = target, .many = false, .constant = constant });
        return .{ .pointer = pointer };
    }

    fn instanceOnlyReads(self: *TypeChecker, parameter: ast.TypedName, target: types.Type) TypeError!bool {
        const decided = try self.buildParameterDecided(parameter, target);
        if (containsVariable(decided)) return false;
        const found = switch (try ast.findInstance(self.arena.allocator(), self.program.modules, self.program.types, parameter.constraint.?, decided)) {
            .found => |found| found,
            .missing, .missing_requirement, .ambiguous, .undecided => return false,
        };
        return self.program.modules[found.reference.module].declarations[found.reference.declaration].kind.instance_declaration.only_reads;
    }

    fn expectReadOnlyParameter(self: *TypeChecker, resolution: ast.Resolution, position: usize, location: token.Location) TypeError!void {
        if (resolution != .function) return self.fail(location, error.NotWritable);
        const written = self.extractSignature(resolution).parameters[position].type;
        if (written.kind != .pointer_type or !written.kind.pointer_type.constant) return self.fail(location, error.NotWritable);
    }

    fn findInstance(
        self: *TypeChecker,
        location: token.Location,
        template: ast.Resolution.Function,
        arguments: []const Bound,
    ) TypeError!ast.Resolution.Function {
        var number: usize = 1;
        const name = findFunctionName(self.program.modules, template);
        for (self.instances.items) |instance| {
            if (instance.template.module == template.module and std.mem.eql(u8, findFunctionName(self.program.modules, instance.template), name)) number += 1;
            if (!std.meta.eql(instance.template, template)) continue;
            const same = for (instance.arguments, arguments) |one, two| {
                if (!self.evaluator.isSameKey(one.value, two.value)) break false;
            } else true;
            if (same) return instance.function;
        }
        var depth = self.instance_depth + 1;
        if (self.evaluator.findCurrentFunction()) |current| depth = @max(depth, self.findInstanceDepth(current) + 1);
        if (depth > instance_limit) return self.fail(location, error.InstanceDepth);
        const resolver = &self.resolver.?;
        const pattern = containsBoundVariable(arguments);
        const function = try resolver.instantiate(resolver.context, template, arguments, number, pattern);
        try self.instances.append(self.arena.allocator(), .{
            .template = template,
            .arguments = arguments,
            .function = function,
            .depth = depth,
            .call = .{ .module = self.module_index, .location = location, .caller = self.current_function },
        });
        if (!pattern) try self.created.append(self.arena.allocator(), function);
        try resolver.resolve(resolver.context, function);
        return function;
    }

    fn findInstanceDepth(self: *const TypeChecker, function: ast.Resolution.Function) usize {
        for (self.instances.items) |instance| {
            if (std.meta.eql(instance.function, function)) return instance.depth;
        }
        return 0;
    }

    fn checkValueCall(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const call = expression.kind.call;
        const resolution = ast.extractResolution(call.callee);
        const callee_type = try self.computeValueType(parameters, expression.location, resolution);
        if (callee_type != .pointer or callee_type.pointer.target != .function) {
            return self.fail(expression.location, error.NotCallable);
        }
        const function = callee_type.pointer.target.function;
        if (call.arguments.len != function.parameters.len) {
            return self.fail(expression.location, error.ArgumentCountMismatch);
        }
        for (call.arguments, function.parameters) |*argument, parameter_type| {
            if (argument.name != null) return self.fail(argument.location, error.NamedArgument);
            try self.checkExpression(parameters, &argument.value, parameter_type);
        }
        return function.return_type;
    }

    fn checkFieldAccess(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const access = expression.kind.field_access;
        const value_type = try self.inferType(parameters, access.value);
        const struct_type = switch (followPointer(value_type)) {
            .@"struct" => |struct_type| struct_type,
            .slice => |slice| {
                if (access.crossing) return self.failNeedlessPrivate(access.field_location, access.field, false);
                return self.checkSliceField(expression, slice);
            },
            .array => |array| {
                if (access.crossing) return self.failNeedlessPrivate(access.field_location, access.field, false);
                return self.checkArrayField(parameters, expression, array);
            },
            .number, .boolean, .void, .type, .@"enum", .pointer, .optional, .result, .tuple, .function, .variable, .application => {
                return self.fail(access.field_location, error.NoFields);
            },
        };
        const field = findField(struct_type.fields, access.field) orelse {
            return self.fail(access.field_location, error.UnknownField);
        };
        const hidden = field.private and struct_type.module != self.module_index;
        if (access.crossing and !hidden) return self.failNeedlessPrivate(access.field_location, field.name, field.private);
        if (hidden and !access.crossing) {
            const allocator = self.arena.allocator();
            const type_name = try ast.renderTypeName(allocator, self.program.modules, .{ .@"struct" = struct_type });
            const way_out = if (try renderExpression(allocator, access.value.*)) |base|
                try std.fmt.allocPrint(allocator, "{s}.private.{s}", .{ base, field.name })
            else
                try std.fmt.allocPrint(allocator, ".private.{s}", .{field.name});
            const failure = self.fail(access.field_location, error.PrivateField);
            self.failure.?.message = try std.fmt.allocPrint(allocator, "`{s}` is a private field of `{s}`; write `{s}` to use it anyway", .{ field.name, type_name, way_out });
            return failure;
        }
        expression.type = field.type;
        return field.type;
    }

    fn checkSliceField(self: *TypeChecker, expression: *ast.Expression, slice: *const types.Slice) TypeError!types.Type {
        const access = expression.kind.field_access;
        const field_type: types.Type = if (std.mem.eql(u8, access.field, "length"))
            .{ .number = .usize }
        else if (std.mem.eql(u8, access.field, "pointer"))
            .{ .pointer = try self.program.types.addPointer(self.arena.allocator(), .{
                .target = slice.element,
                .many = true,
                .constant = slice.constant,
            }) }
        else
            return self.fail(access.field_location, error.UnknownField);
        expression.type = field_type;
        return field_type;
    }

    fn checkArrayField(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        array: *const types.Array,
    ) TypeError!types.Type {
        const access = expression.kind.field_access;
        if (!std.mem.eql(u8, access.field, "length")) return self.fail(access.field_location, error.UnknownField);
        const length_type: types.Type = .{ .number = .usize };
        expression.type = length_type;
        if (containsCall(access.value.*)) return length_type;
        markMeasured(parameters, access.value.*);
        const text = try std.fmt.allocPrint(self.arena.allocator(), "{d}", .{array.length});
        expression.kind = .{ .integer_literal = .{ .text = text, .suffix = "usize" } };
        return length_type;
    }

    fn inferType(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        switch (expression.kind) {
            .undefined => return self.fail(expression.location, error.UnexpectedUndefined),
            .null => return self.fail(expression.location, error.UnexpectedNull),
            .integer_literal, .float_literal, .boolean_literal, .string_literal => {
                const value_type = try self.computeLiteralType(expression.location, expression.*);
                try self.checkLiteral(expression.*, value_type);
                expression.type = value_type;
                return value_type;
            },
            inline .identifier, .path_expression, .member => |name| {
                const value_type = try self.computeValueType(parameters, expression.location, name.resolution.?);
                expression.type = value_type;
                return value_type;
            },
            .call, .method_call => return self.checkCall(parameters, expression),
            .negation => |operand| {
                const value_type = try self.computeLiteralType(expression.location, operand.*);
                try self.checkNegation(expression.location, operand, value_type);
                expression.type = value_type;
                try self.checkKnownOperation(expression);
                return value_type;
            },
            .binary => |binary| {
                const value_type = try self.checkBinary(parameters, binary, null);
                expression.type = value_type;
                try self.foldTypeComparison(expression);
                try self.checkKnownOperation(expression);
                return value_type;
            },
            .unary => |unary| {
                const value_type = try self.checkUnary(parameters, expression.location, unary, null);
                expression.type = value_type;
                try self.checkKnownOperation(expression);
                return value_type;
            },
            .address_of => return self.checkAddressOf(parameters, expression),
            .composite_literal => |literal| {
                const written = literal.type orelse return self.inferTupleLiteral(parameters, expression);
                const value_type = ast.extractType(written.*);
                const location = expression.location;
                _ = try self.checkCompositeLiteral(parameters, location, literal, value_type);
                expression.type = value_type;
                return value_type;
            },
            .case_literal => return self.inferCaseLiteral(parameters, expression),
            .inferred_type => return self.fail(expression.location, error.InferredTypeOutOfPlace),
            .array_type, .slice_type, .pointer_type, .optional_type, .tuple_type, .function_type, .struct_type => {
                expression.type = .type;
                return .type;
            },
            .index => return self.checkIndex(parameters, expression),
            .slice => return self.inferSliceType(parameters, expression),
            .field_access => return self.checkFieldAccess(parameters, expression),
            .dereference => return self.checkDereference(parameters, expression),
            .unwrap => return self.checkUnwrap(parameters, expression),
            .@"try" => return self.checkTry(parameters, expression),
            .range => return self.checkRange(parameters, expression),
            .jump => return self.checkJumpValue(parameters, expression, .void),
            .branching => return self.checkBranching(expression, null),
        }
    }

    fn checkRange(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const range = expression.kind.range;
        const bound_type: types.Type = .{ .number = .usize };
        try self.checkExactExpression(parameters, &range.start, bound_type);
        if (range.end) |*end| {
            try self.checkExactExpression(parameters, end, bound_type);
            if (self.evaluator.isKnownWithoutCalls(range.start) and self.evaluator.isKnownWithoutCalls(end.*)) {
                const first = (try self.evaluateValue(&range.start)).integer.unsigned;
                const last = (try self.evaluateValue(end)).integer.unsigned;
                if (first > last) return self.fail(range.start.location, error.ReversedRange);
            }
        }
        expression.type = range.type.?;
        return range.type.?;
    }

    fn checkBinary(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        context: ?types.Type,
    ) TypeError!types.Type {
        const location = binary.operator_location;
        switch (binary.operator) {
            .@"and", .@"or" => {
                try self.checkExpression(parameters, binary.left, .boolean);
                const decided = try self.decidesAlone(binary);
                if (decided) self.quiet_operations += 1;
                defer if (decided) {
                    self.quiet_operations -= 1;
                };
                try self.checkExpression(parameters, binary.right, .boolean);
                return .boolean;
            },
            .combine, .result => {
                try self.checkExpression(parameters, binary.left, .type);
                try self.checkExpression(parameters, binary.right, .type);
                return .type;
            },
            .shift_left, .shift_right => {
                const value_type = try self.checkOperand(parameters, binary.left, context);
                try self.checkExactExpression(parameters, binary.right, .{ .number = .usize });
                if (!isInteger(value_type)) return self.fail(location, error.NotInteger);
                return value_type;
            },
            .@"orelse" => return self.checkOrElse(parameters, binary),
            .@"catch" => return self.checkCatch(parameters, binary),
            .equal, .not_equal => {
                if (ast.isNullComparison(binary)) return self.checkNullComparison(parameters, binary);
                const operand_type = try self.checkOperands(parameters, binary, null);
                if (!isEquatable(operand_type)) return self.fail(location, error.NotEquatable);
                return .boolean;
            },
            .less_than, .less_than_or_equal, .greater_than, .greater_than_or_equal => {
                const operand_type = try self.checkOperands(parameters, binary, null);
                if (!isOrdered(operand_type)) return self.fail(location, error.NotOrdered);
                return .boolean;
            },
            .add, .subtract => return self.checkAdditive(parameters, binary, context),
            .multiply, .divide => {
                const operand_type = try self.checkOperands(parameters, binary, context);
                if (operand_type != .number) return self.fail(location, error.NotNumeric);
                return operand_type;
            },
            .remainder, .bitwise_and, .bitwise_exclusive_or, .bitwise_or => {
                const operand_type = try self.checkOperands(parameters, binary, context);
                if (!isInteger(operand_type)) return self.fail(location, error.NotInteger);
                return operand_type;
            },
        }
    }

    fn checkOrElse(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
    ) TypeError!types.Type {
        const optional_type = try self.inferType(parameters, binary.left);
        if (optional_type != .optional) return self.fail(binary.left.location, error.NotOptional);
        const child = optional_type.optional.child;
        const fallback = binary.right;
        const decided = try self.decidesAlone(binary);
        if (decided) self.quiet_operations += 1;
        defer if (decided) {
            self.quiet_operations -= 1;
        };
        if (!hasOwnType(fallback.*)) {
            if (fallback.kind == .null and child != .optional) {
                try self.checkExpression(parameters, fallback, optional_type);
                return optional_type;
            }
            try self.checkExactExpression(parameters, fallback, child);
            return child;
        }
        const fallback_type = try self.inferType(parameters, fallback);
        if (isWidened(fallback_type, child)) return self.fail(fallback.location, error.TypeMismatch);
        if (isConvertible(fallback_type, child)) return child;
        if (isConvertible(fallback_type, optional_type)) return optional_type;
        return self.fail(fallback.location, error.TypeMismatch);
    }

    fn checkCatch(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
    ) TypeError!types.Type {
        const result_type = try self.inferType(parameters, binary.left);
        if (result_type != .result) return self.fail(binary.left.location, error.NotResult);
        const value_type = result_type.result.value;
        const decided = try self.decidesAlone(binary);
        if (decided) self.quiet_operations += 1;
        defer if (decided) {
            self.quiet_operations -= 1;
        };
        try self.checkExactExpression(parameters, binary.right, value_type);
        return value_type;
    }

    fn checkNullComparison(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
    ) TypeError!types.Type {
        const left_is_null = binary.left.kind == .null;
        const operand = if (left_is_null) binary.right else binary.left;
        const null_operand = if (left_is_null) binary.left else binary.right;
        if (operand.kind == .null) return self.fail(binary.left.location, error.UnknownValueType);
        const operand_type = try self.inferType(parameters, operand);
        try self.checkExpression(parameters, null_operand, operand_type);
        return .boolean;
    }

    fn checkAdditive(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        context: ?types.Type,
    ) TypeError!types.Type {
        const location = binary.operator_location;
        const left_type = try self.inferOwnType(parameters, binary.left);
        if (left_type) |known| {
            if (known == .pointer) return self.checkPointerArithmetic(parameters, binary, known);
        }
        const right_type = try self.inferOwnType(parameters, binary.right);
        if (right_type) |known| {
            if (known == .pointer and binary.operator == .add) {
                return self.checkOffsetPlusPointer(parameters, binary, left_type, known);
            }
        }
        const operand_type = try self.matchOperands(parameters, binary, left_type, right_type, context);
        if (operand_type != .number) return self.fail(location, error.NotNumeric);
        return operand_type;
    }

    fn checkOffsetPlusPointer(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        offset_type: ?types.Type,
        pointer_type: types.Type,
    ) TypeError!types.Type {
        try self.expectArithmeticPointer(binary.operator_location, pointer_type);
        const usize_type: types.Type = .{ .number = .usize };
        const known = offset_type orelse {
            try self.checkExactExpression(parameters, binary.left, usize_type);
            return pointer_type;
        };
        if (!std.meta.eql(known, usize_type)) {
            return self.fail(binary.left.location, error.TypeMismatch);
        }
        return pointer_type;
    }

    fn checkPointerArithmetic(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        pointer_type: types.Type,
    ) TypeError!types.Type {
        const location = binary.operator_location;
        try self.expectArithmeticPointer(location, pointer_type);
        const offset_type: types.Type = .{ .number = .usize };
        if (binary.operator == .add or !hasOwnType(binary.right.*)) {
            try self.checkExactExpression(parameters, binary.right, offset_type);
            return pointer_type;
        }
        const right_type = try self.inferType(parameters, binary.right);
        if (right_type != .pointer) {
            if (!std.meta.eql(right_type, offset_type)) {
                return self.fail(binary.right.location, error.TypeMismatch);
            }
            return pointer_type;
        }
        if (unifyTypes(pointer_type, right_type) == null) {
            return self.fail(location, error.MismatchedOperands);
        }
        return .{ .number = .isize };
    }

    fn expectArithmeticPointer(
        self: *TypeChecker,
        location: token.Location,
        pointer_type: types.Type,
    ) TypeError!void {
        const pointer = pointer_type.pointer;
        if (!pointer.many) return self.fail(location, error.SinglePointerArithmetic);
        if (isZeroSized(pointer.target)) return self.fail(location, error.ZeroSizedPointerArithmetic);
    }

    fn checkOperands(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        context: ?types.Type,
    ) TypeError!types.Type {
        const left_type = try self.inferOwnType(parameters, binary.left);
        const right_type = try self.inferOwnType(parameters, binary.right);
        return self.matchOperands(parameters, binary, left_type, right_type, context);
    }

    fn inferOwnType(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!?types.Type {
        if (!hasOwnType(expression.*)) return null;
        return try self.inferType(parameters, expression);
    }

    fn matchOperands(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        binary: ast.Binary,
        left_type: ?types.Type,
        right_type: ?types.Type,
        context: ?types.Type,
    ) TypeError!types.Type {
        const left = binary.left;
        const right = binary.right;
        if (left_type) |known_left| {
            const known_right = right_type orelse {
                try self.checkOperandExpression(parameters, right, known_left);
                return known_left;
            };
            return unifyTypes(known_left, known_right) orelse {
                return self.fail(binary.operator_location, error.MismatchedOperands);
            };
        }
        if (right_type) |known_right| {
            try self.checkOperandExpression(parameters, left, known_right);
            return known_right;
        }
        const operand_type = context orelse return self.failUnknownType(left);
        try self.checkOperandExpression(parameters, left, operand_type);
        try self.checkOperandExpression(parameters, right, operand_type);
        return operand_type;
    }

    fn checkOperand(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        operand: *ast.Expression,
        context: ?types.Type,
    ) TypeError!types.Type {
        if (hasOwnType(operand.*)) return self.inferType(parameters, operand);
        const operand_type = context orelse return self.failUnknownType(operand);
        try self.checkOperandExpression(parameters, operand, operand_type);
        return operand_type;
    }

    fn checkOperandExpression(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        operand: *ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        if (expected == .optional and takesExpectedType(operand.*)) return self.fail(operand.location, error.TypeMismatch);
        try self.checkExactExpression(parameters, operand, expected);
    }

    fn checkExactExpression(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        self.exact_numbers = true;
        try self.checkExpression(parameters, expression, expected);
    }

    fn checkUnary(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        location: token.Location,
        unary: ast.Unary,
        context: ?types.Type,
    ) TypeError!types.Type {
        if (unary.operator == .not) {
            try self.checkExpression(parameters, unary.operand, .boolean);
            return .boolean;
        }
        const operand_type = try self.checkOperand(parameters, unary.operand, context);
        if (unary.operator == .bitwise_not) {
            if (!isInteger(operand_type)) return self.fail(location, error.NotInteger);
            return operand_type;
        }
        if (operand_type != .number) return self.fail(location, error.NotNumeric);
        if (!isSigned(operand_type.number)) return self.fail(location, error.NegatedUnsigned);
        return operand_type;
    }

    fn checkAddressOf(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const operand = expression.kind.address_of;
        if (findFunction(operand.*)) |function| return self.checkFunctionAddress(expression, function);
        const target = try self.inferType(parameters, operand);
        const static = expression.implicit and operand.kind == .string_literal;
        if (!isPlace(operand.*) and !static) return self.fail(operand.location, error.NotAddressable);
        const pointer = try self.program.types.addPointer(self.arena.allocator(), .{
            .target = target,
            .many = false,
            .constant = static or (!isWritable(operand.*) and !(expression.handed and isOwnConstant(operand.*))),
        });
        expression.type = .{ .pointer = pointer };
        return expression.type.?;
    }

    fn checkFunctionAddress(
        self: *TypeChecker,
        expression: *ast.Expression,
        function: ast.Resolution,
    ) TypeError!types.Type {
        const operand = expression.kind.address_of;
        if (function == .function and ast.isGeneric(self.extractSignature(function))) {
            return self.fail(operand.location, error.GenericValue);
        }
        if (function == .function and try self.needsAllocator(function.function)) {
            return self.fail(operand.location, error.AllocatorFunctionAddress);
        }
        if (function == .function and self.extractSignature(function).@"inline") {
            return self.fail(operand.location, error.InlineValue);
        }
        try self.completeInferredErrorSet(function);
        operand.type = try self.computeFunctionType(function);
        const pointer = try self.program.types.addPointer(self.arena.allocator(), .{
            .target = operand.type.?,
            .many = false,
            .constant = false,
        });
        expression.type = .{ .pointer = pointer };
        return expression.type.?;
    }

    fn inferTupleLiteral(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const elements = expression.kind.composite_literal.elements;
        if (hasNames(elements)) return self.fail(expression.location, error.UnknownValueType);
        const element_types = try self.arena.allocator().alloc(types.Type, elements.len);
        for (elements, element_types) |*element, *element_type| {
            if (!hasOwnType(element.value)) return self.failUnknownType(&element.value);
            element_type.* = try self.inferType(parameters, &element.value);
        }
        const value_type: types.Type = .{ .tuple = try self.program.types.addTuple(self.arena.allocator(), element_types) };
        expression.type = value_type;
        return value_type;
    }

    fn checkCompositeLiteral(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        location: token.Location,
        literal: ast.CompositeLiteral,
        expected: types.Type,
    ) TypeError!types.Type {
        const literal_type = if (literal.type) |written| ast.extractType(written.*) else expected;
        switch (literal_type) {
            .array => |array| {
                if (hasNames(literal.elements)) return self.fail(location, error.NotAStruct);
                if (literal.elements.len != array.length) {
                    return self.fail(location, error.WrongLength);
                }
                for (literal.elements) |*element| {
                    try self.checkExpression(parameters, &element.value, array.element);
                }
            },
            .tuple => |tuple| {
                if (hasNames(literal.elements)) return self.fail(location, error.NotAStruct);
                if (literal.elements.len != tuple.elements.len) {
                    return self.fail(location, error.WrongTupleLength);
                }
                for (literal.elements, tuple.elements) |*element, element_type| {
                    try self.checkExpression(parameters, &element.value, element_type);
                }
            },
            .@"struct" => |struct_type| {
                try self.checkConstruction(parameters, location, literal.elements, struct_type);
            },
            .slice => |slice| {
                if (literal.type != null) return self.fail(location, error.UnexpectedBraces);
                if (literal.elements.len > 0 and !slice.constant) return self.fail(location, error.UnexpectedBraces);
                if (hasNames(literal.elements)) return self.fail(location, error.NotAStruct);
                for (literal.elements) |*element| {
                    try self.checkExpression(parameters, &element.value, slice.element);
                    if (!self.evaluator.isKnown(element.value)) return self.fail(element.value.location, error.CannotEvaluate);
                }
            },
            .number, .boolean, .void, .type, .@"enum", .pointer, .optional, .result, .function, .variable, .application => {
                return self.fail(location, error.UnexpectedBraces);
            },
        }
        return literal_type;
    }

    fn checkConstruction(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        location: token.Location,
        elements: []ast.Argument,
        struct_type: types.Struct,
    ) TypeError!void {
        try self.expectCrossedFields(location, elements, struct_type);
        for (elements, 0..) |*element, index| {
            const name = element.name orelse try self.expandShorthand(element);
            const field = findField(struct_type.fields, name) orelse {
                const type_name = try ast.renderTypeName(self.arena.allocator(), self.program.modules, .{ .@"struct" = struct_type });
                return self.failNamingType(element.location, error.UnknownField, "`{s}` has no field `{s}`", type_name, name);
            };
            if (ast.findArgument(elements, name) != index) {
                return self.fail(element.location, error.RepeatedField);
            }
            try self.checkExpression(parameters, &element.value, field.type);
        }
        for (struct_type.fields) |field| {
            if (ast.findArgument(elements, field.name) != null) continue;
            const default = field.default orelse return self.fail(location, error.MissingField);
            if (default.type == null) try self.checkFieldDefaults(struct_type);
        }
    }

    fn expectCrossedFields(self: *TypeChecker, location: token.Location, elements: []const ast.Argument, struct_type: types.Struct) TypeError!void {
        const foreign = struct_type.module != self.module_index;
        for (struct_type.fields) |field| {
            const element = findElement(elements, field.name);
            const crossed = if (element) |found| found.crossing else false;
            if (crossed and !(foreign and field.private)) return self.failNeedlessPrivate(element.?.location, field.name, field.private);
            if (foreign and field.private and !crossed) return self.failPrivateFieldLiteral(location, struct_type, field.name);
        }
    }

    fn failPrivateFieldLiteral(self: *TypeChecker, location: token.Location, struct_type: types.Struct, field_name: []const u8) TypeError {
        const allocator = self.arena.allocator();
        const value_type: types.Type = .{ .@"struct" = struct_type };
        const type_name = try ast.renderTypeName(allocator, self.program.modules, value_type);
        const failure = self.fail(location, error.PrivateFieldLiteral);
        const reason = if (try self.findBuilder(value_type)) |builder|
            try std.fmt.allocPrint(allocator, "`{s}` has a private field, so it is built through its functions, e.g. `{s}::{s}()`", .{ type_name, type_name, builder })
        else
            try std.fmt.allocPrint(allocator, "`{s}` has a private field, so it is built through the functions of `{s}`", .{ type_name, try std.mem.join(allocator, "::", self.program.modules[struct_type.module].path) });
        self.failure.?.message = try std.fmt.allocPrint(allocator, "{s}; write `{{ private.{s} = ... }}` to build it anyway", .{ reason, field_name });
        return failure;
    }

    fn findBuilder(self: *TypeChecker, value_type: types.Type) TypeError!?[]const u8 {
        const module = self.program.modules[value_type.@"struct".module];
        for (0..module.declarations.len + module.instances.items.len) |index| {
            const declaration = ast.findDeclaration(module, index).*;
            if (declaration.kind != .function_definition) continue;
            const signature = declaration.kind.function_definition.signature;
            const written = signature.receiver orelse continue;
            if (signature.typeclass != null or signature.private or signature.self_parameter != .none or signature.progress != .done) continue;
            if (!std.meta.eql(ast.extractType(written), value_type)) continue;
            const returned = ast.extractType(signature.return_type);
            const built = switch (returned) {
                .optional => |optional| optional.child,
                .result => |result| result.value,
                else => returned,
            };
            if (std.meta.eql(built, value_type)) return signature.name;
        }
        return null;
    }

    fn expandShorthand(self: *TypeChecker, element: *ast.Argument) TypeError![]const u8 {
        if (element.value.kind != .identifier) return self.fail(element.location, error.MissingFieldName);
        element.name = element.value.kind.identifier.name;
        return element.name.?;
    }

    fn expectReachableFunction(
        self: *TypeChecker,
        location: token.Location,
        receiver: types.Type,
        function: ast.Resolution.Function,
        crossing: Crossing,
    ) TypeError!void {
        const allocator = self.arena.allocator();
        const module = self.program.modules[function.module];
        const declaration = ast.findDeclaration(module, function.declaration).*;
        if (function.module != self.module_index) {
            if (ast.findTypeDeclaration(module, receiver)) |index| {
                if (ast.isHidden(module, index)) {
                    const way_out = try renderHiddenPath(allocator, module, index, ast.extractFunctionSignature(declaration).name);
                    return self.failPrivate(location, try ast.renderTypeName(allocator, self.program.modules, receiver), function.module, way_out);
                }
            }
        }
        if (!try self.isRefused(location, function.module, ast.isPrivate(declaration), crossing)) return;
        const name = try std.mem.concat(allocator, u8, &.{ try ast.renderTypeName(allocator, self.program.modules, receiver), "::", ast.extractFunctionSignature(declaration).name });
        return self.failPrivate(location, name, function.module, try renderCrossing(allocator, crossing));
    }

    fn expectReachableTypeclassFunction(
        self: *TypeChecker,
        location: token.Location,
        typeclass: ast.Resolution.Typeclass,
        position: usize,
        crossing: Crossing,
    ) TypeError!void {
        const definition = self.extractTypeclass(typeclass);
        const signature = definition.functions[position];
        if (!try self.isRefused(location, typeclass.module, signature.private, crossing)) return;
        const allocator = self.arena.allocator();
        const name = try std.mem.concat(allocator, u8, &.{ definition.name, "::", signature.name });
        return self.failPrivate(location, name, typeclass.module, try renderCrossing(allocator, crossing));
    }

    fn isRefused(self: *TypeChecker, location: token.Location, module_index: usize, private: bool, crossing: Crossing) TypeError!bool {
        const hidden = private and module_index != self.module_index;
        if (crossing.crossed and !hidden) return self.failNeedlessPrivate(location, crossing.name, private);
        return hidden and !crossing.crossed;
    }

    fn failPrivate(self: *TypeChecker, location: token.Location, name: []const u8, module_index: usize, way_out: []const u8) TypeError {
        const allocator = self.arena.allocator();
        const module_name = try std.mem.join(allocator, "::", self.program.modules[module_index].path);
        const failure = self.fail(location, error.PrivateDeclaration);
        self.failure.?.message = try std.fmt.allocPrint(allocator, "`{s}` is private to `{s}`; write `{s}` to use it anyway", .{ name, module_name, way_out });
        return failure;
    }

    fn failNeedlessPrivate(self: *TypeChecker, location: token.Location, name: []const u8, private: bool) TypeError {
        const reason = if (private) "is private to this module, which uses it without `private`" else "is not private, so `private` before it crosses nothing";
        const failure = self.fail(location, error.NeedlessPrivate);
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), "`{s}` {s}; remove the word", .{ name, reason });
        return failure;
    }

    fn checkIndex(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const indexing = expression.kind.index;
        const index = indexing.index;
        const index_type: types.Type = .{ .number = .usize };
        const element_type = switch (try self.inferType(parameters, indexing.value)) {
            .array => |array| try self.checkArrayIndex(parameters, expression, array),
            .tuple => |tuple| element: {
                const position = try self.checkTupleIndex(parameters, index, tuple);
                expression.kind.index.position = position;
                break :element tuple.elements[position];
            },
            .slice => |slice| element: {
                try self.checkExactExpression(parameters, index, index_type);
                break :element slice.element;
            },
            .pointer => |pointer| element: {
                if (pointer.many) {
                    try self.checkExactExpression(parameters, index, index_type);
                    break :element pointer.target;
                }
                if (pointer.target != .array) {
                    return self.fail(expression.location, error.NotIndexable);
                }
                break :element try self.checkArrayIndex(parameters, expression, pointer.target.array);
            },
            .type => element: {
                const value = indexing.value;
                if (!self.evaluator.isKnown(value.*)) return self.fail(value.location, error.CannotEvaluate);
                const indexed = (try self.evaluateValue(value)).type;
                if (indexed != .tuple) return self.fail(value.location, error.NotTupleType);
                const position = try self.checkTupleIndex(parameters, index, indexed.tuple);
                expression.kind.index.position = position;
                break :element .type;
            },
            .number, .boolean, .void, .@"struct", .@"enum", .optional, .result, .function, .variable, .application => {
                return self.fail(expression.location, error.NotIndexable);
            },
        };
        expression.type = element_type;
        return element_type;
    }

    fn checkArrayIndex(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        array: *const types.Array,
    ) TypeError!types.Type {
        const index = expression.kind.index.index;
        try self.checkExactExpression(parameters, index, .{ .number = .usize });
        if (array.length == 0) return self.fail(index.location, error.IndexOutOfRange);
        try self.expectLoopFits(index, array);
        if (!self.evaluator.isKnownWithoutCalls(index.*)) return array.element;
        const position = (try self.evaluateValue(index)).integer.unsigned;
        if (position >= array.length) return self.fail(index.location, error.IndexOutOfRange);
        expression.kind.index.position = @intCast(position);
        return array.element;
    }

    fn expectLoopFits(self: *TypeChecker, index: *const ast.Expression, array: *const types.Array) TypeError!void {
        if (index.kind != .identifier) return;
        const resolution = index.kind.identifier.resolution orelse return;
        if (resolution != .element or resolution.element.statement.kind != .@"for") return;
        const sequence = resolution.element.statement.kind.@"for".sequence;
        if (sequence != .range) return;
        const end = sequence.range.known_end orelse return;
        if (end <= array.length) return;
        const failure = self.fail(index.location, error.RangeOutsideArray);
        const format = "the range of this loop ends at {d}, past the length {d} of the array";
        self.failure.?.message = try std.fmt.allocPrint(self.arena.allocator(), format, .{ end, array.length });
        return failure;
    }

    fn checkTupleIndex(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        index: *ast.Expression,
        tuple: *const types.Tuple,
    ) TypeError!u64 {
        try self.checkExactExpression(parameters, index, .{ .number = .usize });
        if (!self.evaluator.isKnown(index.*)) return self.fail(index.location, error.UnknownTupleIndex);
        const position = (try self.evaluateValue(index)).integer.unsigned;
        if (position >= tuple.elements.len) return self.fail(index.location, error.IndexOutOfRange);
        return @intCast(position);
    }

    fn inferSliceType(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const slice = expression.kind.slice;
        const value = slice.value;
        const element: types.Type, const constant: bool = switch (try self.inferType(parameters, value)) {
            .array => |array| array: {
                if (!isPlace(value.*)) return self.fail(value.location, error.SlicedTemporary);
                break :array .{ array.element, !isWritable(value.*) };
            },
            .slice => |sliced| .{ sliced.element, sliced.constant },
            .pointer => |pointer| pointer: {
                if (pointer.many) {
                    if (slice.end == null) return self.fail(expression.location, error.MissingEnd);
                    break :pointer .{ pointer.target, pointer.constant };
                }
                if (pointer.target != .array) {
                    return self.fail(value.location, error.NotSliceable);
                }
                break :pointer .{ pointer.target.array.element, pointer.constant };
            },
            .number, .boolean, .void, .type, .@"struct", .@"enum", .optional, .result, .tuple, .function, .variable, .application => {
                return self.fail(value.location, error.NotSliceable);
            },
        };
        const bound_type: types.Type = .{ .number = .usize };
        if (slice.start) |start| try self.checkExactExpression(parameters, start, bound_type);
        if (slice.end) |end| try self.checkExactExpression(parameters, end, bound_type);
        const allocator = self.arena.allocator();
        const slice_type = try self.program.types.addSlice(allocator, element, constant);
        expression.type = .{ .slice = slice_type };
        return expression.type.?;
    }

    fn checkDereference(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const pointer = switch (try self.inferType(parameters, expression.kind.dereference)) {
            .pointer => |pointer| pointer,
            .number, .boolean, .void, .type, .@"struct", .@"enum", .array, .slice, .optional, .result, .tuple, .function, .variable, .application => {
                return self.fail(expression.location, error.NotAPointer);
            },
        };
        if (pointer.target == .function) return self.fail(expression.location, error.FunctionDereferenced);
        if (pointer.target == .void) return self.fail(expression.location, error.VoidDereferenced);
        expression.type = pointer.target;
        return pointer.target;
    }

    fn checkUnwrap(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        const optional_type = try self.inferType(parameters, expression.kind.unwrap);
        if (optional_type != .optional) return self.fail(expression.location, error.NotOptional);
        expression.type = optional_type.optional.child;
        return expression.type.?;
    }

    fn checkTry(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!types.Type {
        if (self.deferring) return self.fail(expression.location, error.TryInDefer);
        const operand = expression.kind.@"try";
        const result_type = try self.inferType(parameters, operand);
        if (result_type != .result) return self.fail(operand.location, error.NotResult);
        const return_type = self.return_type orelse return self.fail(expression.location, error.TryWithoutResult);
        if (return_type != .result) return self.fail(expression.location, error.TryWithoutResult);
        try self.recordInferredErrors(result_type, return_type);
        const error_set = result_type.result.error_set;
        if (error_set.cases.len > 0 and !types.isEnumPart(error_set, return_type.result.error_set)) {
            return self.fail(expression.location, error.UnheldError);
        }
        expression.type = result_type.result.value;
        return expression.type.?;
    }

    fn checkJumpValue(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
        value_type: types.Type,
    ) TypeError!types.Type {
        try self.checkJump(parameters, expression);
        expression.type = value_type;
        return value_type;
    }

    fn checkJump(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        expression: *ast.Expression,
    ) TypeError!void {
        if (self.deferring) return self.fail(expression.location, error.JumpInDefer);
        const statement = expression.kind.jump;
        switch (statement.kind) {
            .@"return" => {
                const return_type = self.return_type orelse return self.fail(statement.location, error.ReturnOutsideFunction);
                try self.checkReturn(parameters, statement, return_type);
            },
            .@"break" => |jump| if (jump.loop == null) return self.fail(statement.location, error.BreakOutsideLoop),
            .@"continue" => |jump| if (jump.loop == null) return self.fail(statement.location, error.ContinueOutsideLoop),
            else => unreachable,
        }
    }

    fn checkReturn(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        statement: *ast.Statement,
        return_type: types.Type,
    ) TypeError!void {
        if (self.return_type == null) return self.fail(statement.location, error.ReturnOutsideFunction);
        if (statement.kind.@"return") |*value| {
            if (return_type == .void) return self.fail(value.location, error.UnexpectedReturnValue);
            return self.checkExpression(parameters, value, return_type);
        }
        if (!returnsNoValue(return_type)) return self.fail(statement.location, error.MissingReturnValue);
    }

    fn computeValueType(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        location: token.Location,
        resolution: ast.Resolution,
    ) TypeError!types.Type {
        return switch (resolution) {
            .parameter => |index| ast.extractType(parameters[index].type),
            .type => .type,
            .constant => |constant| self.computeConstantType(constant),
            .local => |statement| switch (statement.kind) {
                .constant_declaration => |constant| ast.extractDeclaredType(constant.type, constant.value),
                .variable_declaration => |variable| ast.extractDeclaredType(variable.type, variable.value),
                .noop,
                .@"return",
                .discard,
                .call,
                .tuple_declaration,
                .assignment,
                .@"if",
                .@"while",
                .@"for",
                .match,
                .@"defer",
                .@"break",
                .@"continue",
                .value,
                => unreachable,
            },
            .element => |element| ast.findElementName(element).type.?,
            .function, .typeclass_function, .typeclass_method, .builtin => self.fail(location, error.FunctionUsedAsValue),
            .case => |case| {
                if (case.enumeration.cases[case.index].type != null) return self.fail(location, error.CaseNeedsValue);
                return .{ .@"enum" = case.enumeration };
            },
        };
    }

    fn computeConstantType(self: *TypeChecker, constant: ast.Resolution.Constant) TypeError!types.Type {
        return self.checkConstant(constant);
    }

    fn computeFunctionType(self: *TypeChecker, function: ast.Resolution) TypeError!types.Type {
        const signature = self.extractSignature(function);
        const allocator = self.arena.allocator();
        const parameters = try allocator.alloc(types.Type, signature.parameters.len);
        for (signature.parameters, parameters) |parameter, *parameter_type| {
            parameter_type.* = ast.extractType(parameter.type);
        }
        const return_type = ast.extractType(signature.return_type);
        const function_type = try self.program.types.addFunction(allocator, parameters, return_type);
        return .{ .function = function_type };
    }

    fn checkConstant(self: *TypeChecker, constant: ast.Resolution.Constant) TypeError!types.Type {
        const module = self.program.modules[constant.module];
        const declaration = &ast.findDeclaration(module, constant.declaration).kind.constant_declaration;
        const caller_module_index = self.module_index;
        const caller_constraints = self.constraints;
        const caller_return_type = self.return_type;
        self.module_index = constant.module;
        self.constraints = &.{};
        self.return_type = null;
        defer self.module_index = caller_module_index;
        defer self.constraints = caller_constraints;
        defer self.return_type = caller_return_type;
        const written = if (declaration.type) |*written| written else null;
        const caller_compile_time = self.compile_time;
        self.compile_time = true;
        defer self.compile_time = caller_compile_time;
        return self.checkDeclaredValue(&.{}, written, &declaration.value);
    }

    fn checkDeclaredValue(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        written_type: ?*ast.Expression,
        value: *ast.Expression,
    ) TypeError!types.Type {
        if (value.type) |value_type| {
            if (!self.rechecking) {
                const written = written_type orelse return value_type;
                return ast.extractType(written.*);
            }
        }
        const written = written_type orelse return self.inferType(parameters, value);
        if (isUnfinishedArray(written.*)) return self.completeArrayType(parameters, written, value);
        const expected = ast.extractType(written.*);
        try self.checkExpression(parameters, value, expected);
        return expected;
    }

    fn completeArrayType(
        self: *TypeChecker,
        parameters: []const ast.TypedName,
        written: *ast.Expression,
        value: *ast.Expression,
    ) TypeError!types.Type {
        if (value.kind == .undefined) return self.fail(value.location, error.MissingLength);
        const array_type = &written.kind.array_type;
        const value_type = try self.inferType(parameters, value);
        if (value_type != .array) return self.fail(value.location, error.MissingLength);
        const element = ast.extractType(array_type.element.*);
        if (!std.meta.eql(value_type.array.element, element)) {
            return self.fail(value.location, error.TypeMismatch);
        }
        value.type = value_type;
        array_type.value = value_type;
        return value_type;
    }

    fn computeLiteralType(
        self: *TypeChecker,
        location: token.Location,
        expression: ast.Expression,
    ) TypeError!types.Type {
        return switch (expression.kind) {
            .integer_literal, .float_literal => |literal| {
                const suffix = literal.suffix orelse {
                    return self.fail(location, error.UnknownValueType);
                };
                const number = types.findNumberType(suffix) orelse {
                    return self.fail(location, error.UnknownSuffix);
                };
                return .{ .number = number };
            },
            .boolean_literal => .boolean,
            .string_literal => {
                const allocator = self.arena.allocator();
                const slice = try self.program.types.addSlice(allocator, .{ .number = .u8 }, true);
                return .{ .slice = slice };
            },
            .undefined,
            .null,
            .identifier,
            .path_expression,
            .member,
            .call,
            .method_call,
            .negation,
            .binary,
            .unary,
            .address_of,
            .array_type,
            .composite_literal,
            .case_literal,
            .inferred_type,
            .slice_type,
            .index,
            .slice,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            .field_access,
            .dereference,
            .unwrap,
            .@"try",
            .range,
            .jump,
            .branching,
            => unreachable,
        };
    }

    fn checkLiteral(
        self: *TypeChecker,
        expression: ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        switch (expression.kind) {
            .integer_literal => |literal| {
                try self.checkInteger(expression.location, literal, expected, false);
            },
            .float_literal => |literal| try self.checkFloat(expression.location, literal, expected),
            .boolean_literal => {
                if (expected != .boolean) {
                    return self.fail(expression.location, error.TypeMismatch);
                }
            },
            .string_literal => {
                const text_type = try self.computeLiteralType(expression.location, expression);
                if (!isConvertible(text_type, expected)) {
                    return self.fail(expression.location, error.TypeMismatch);
                }
            },
            .undefined,
            .null,
            .identifier,
            .path_expression,
            .member,
            .call,
            .method_call,
            .negation,
            .binary,
            .unary,
            .address_of,
            .array_type,
            .composite_literal,
            .case_literal,
            .inferred_type,
            .slice_type,
            .index,
            .slice,
            .pointer_type,
            .optional_type,
            .tuple_type,
            .function_type,
            .struct_type,
            .field_access,
            .dereference,
            .unwrap,
            .@"try",
            .range,
            .jump,
            .branching,
            => unreachable,
        }
    }

    fn checkNegation(
        self: *TypeChecker,
        location: token.Location,
        operand: *ast.Expression,
        expected: types.Type,
    ) TypeError!void {
        switch (operand.kind) {
            .integer_literal => |literal| try self.checkInteger(location, literal, expected, true),
            .float_literal => |literal| try self.checkFloat(location, literal, expected),
            else => unreachable,
        }
        operand.type = expected;
    }

    fn checkInteger(
        self: *TypeChecker,
        location: token.Location,
        literal: token.NumberLiteral,
        expected: types.Type,
        negative: bool,
    ) TypeError!void {
        const number = try self.expectNumber(location, literal, expected);
        const maximum = computeIntegerMaximum(number) orelse {
            return self.fail(location, error.TypeMismatch);
        };
        if (negative and !isSigned(number)) return self.fail(location, error.NegativeUnsigned);
        const value = std.fmt.parseInt(u128, literal.text, 0) catch {
            return self.fail(location, error.LiteralOutOfRange);
        };
        const limit = if (negative) maximum + 1 else maximum;
        if (value > limit) return self.fail(location, error.LiteralOutOfRange);
    }

    fn checkFloat(
        self: *TypeChecker,
        location: token.Location,
        literal: token.NumberLiteral,
        expected: types.Type,
    ) TypeError!void {
        const number = try self.expectNumber(location, literal, expected);
        const fits = switch (number) {
            .f16 => fitsFloat(f16, literal.text),
            .f32 => fitsFloat(f32, literal.text),
            .f64 => fitsFloat(f64, literal.text),
            .f128 => fitsFloat(f128, literal.text),
            else => return self.fail(location, error.TypeMismatch),
        };
        if (!fits) return self.fail(location, error.LiteralOutOfRange);
    }

    fn expectNumber(
        self: *TypeChecker,
        location: token.Location,
        literal: token.NumberLiteral,
        expected: types.Type,
    ) TypeError!types.NumberType {
        const number = switch (expected) {
            .number => |number| number,
            .boolean, .void, .type, .@"struct", .@"enum", .array, .slice, .pointer, .optional, .result, .tuple, .function, .variable, .application => {
                return self.fail(location, error.TypeMismatch);
            },
        };
        const suffix = literal.suffix orelse return number;
        const suffix_type = types.findNumberType(suffix) orelse {
            return self.fail(location, error.UnknownSuffix);
        };
        if (suffix_type != number) return self.fail(location, error.TypeMismatch);
        return number;
    }

    fn failAmbiguous(self: *TypeChecker, location: token.Location, pair: [2]ast.InstanceReference) TypeError {
        const failure = self.fail(location, error.AmbiguousInstance);
        const allocator = self.arena.allocator();
        const modules = self.program.modules;
        self.failure.?.message = try std.fmt.allocPrint(allocator, "more than one instance fits and neither is more specific: {s} and {s}", .{ try ast.renderInstance(allocator, modules, pair[0]), try ast.renderInstance(allocator, modules, pair[1]) });
        return failure;
    }

    fn fail(self: *TypeChecker, location: token.Location, check_error: CheckError) CheckError {
        self.failure = .{
            .module = self.program.modules[self.module_index].path,
            .location = location,
            .message = describeError(check_error),
        };
        return check_error;
    }
};

pub const TypeError = AnalyzeError;

pub const CheckError = error{
    OutOfMemory,
    ValueIfWithoutElse,
    MissingBranchValue,
    BranchTypeMismatch,
    UnusedValue,
    DependencyLoop,
    TypeMismatch,
    LiteralOutOfRange,
    NegativeUnsigned,
    MissingReturnValue,
    UnexpectedReturnValue,
    MissingReturn,
    MainHasReturnType,
    MainHasParameters,
    MainCalled,
    MainIsExternal,
    ArgumentCountMismatch,
    InstanceDefaultMismatch,
    UnfitInstanceDefault,
    UnusedResult,
    DiscardedVoid,
    TypeVariable,
    TypeParameter,
    CompileTimeValue,
    RuntimeArgument,
    GenericValue,
    InstanceDepth,
    UnexpectedUndefined,
    UnreachableStatement,
    UnexpectedNull,
    NotSliceable,
    SlicedTemporary,
    MissingEnd,
    NotIndexable,
    IndexOutOfRange,
    UnknownTupleIndex,
    NotAddressable,
    MissingLength,
    CannotEvaluate,
    NotAPointer,
    NotOptional,
    SinglePointerArithmetic,
    ZeroSizedPointerArithmetic,
    NotWritable,
    NeverModified,
    UnusedVariable,
    PointlessDiscard,
    WrongLength,
    WrongTupleLength,
    UnexpectedBraces,
    NotCallable,
    FunctionUsedAsValue,
    FunctionDereferenced,
    VoidDereferenced,
    ExpectedPointer,
    ExpectedManyPointer,
    ComptimeError,
    NeedsAllocator,
    AllocatorNotNeeded,
    NotAllocator,
    AllocatorNeedsPointer,
    MissingAllocator,
    OwnResultMisplaced,
    OwnNeedsClone,
    OwnMarkerMissing,
    OwnMarkerMisplaced,
    ReceiverNotTakenOver,
    OwnNameReturned,
    OwnValueCopied,
    OwnNameMoved,
    OwnWithoutAllocation,
    OwnPartMoved,
    OwnPartIndexUnknown,
    OwnPointerNotOwned,
    OwnNotConsumed,
    OwnNameDiscarded,
    OwnParameterHandedOn,
    OwnVariableHeld,
    OwnPartHeld,
    AllocatorFunctionAddress,
    ComptimeErrorAsValue,
    InlineMain,
    PrivateMain,
    PrivateField,
    PrivateFieldLiteral,
    PrivateDeclaration,
    NeedlessPrivate,
    OwnUnendable,
    InlineValue,
    InlineRecursion,
    UnknownMethod,
    AmbiguousMethod,
    NoSelf,
    UndecidedInstance,
    UndecidedConstructorArgument,
    HiddenConstructorSignature,
    AmbiguousInstance,
    MissingRequiredInstance,
    UnknownSuffix,
    UnknownValueType,
    CaseWithoutEnum,
    ParenthesizedCaseValue,
    CaseValueCount,
    CaseWithoutKnownEnum,
    UnknownTypeArgument,
    LiteralFunctionIsMethod,
    LiteralFunctionType,
    InferredTypeOutOfPlace,
    NoFields,
    UnknownField,
    NamedArgument,
    NotAStruct,
    MissingFieldName,
    RepeatedField,
    MissingField,
    NotNumeric,
    NotInteger,
    NotEquatable,
    NotOrdered,
    NegatedUnsigned,
    MismatchedOperands,
    NotSequence,
    ReversedRange,
    NotTuple,
    WrongNameCount,
    NoInstance,
    CaseNeedsValue,
    CaseWithoutValue,
    NotMatchable,
    WrongCaseType,
    MisplacedRange,
    MisplacedValueName,
    EmptyRange,
    RangeOutsideArray,
    UnknownCase,
    AmbiguousCase,
    DuplicateBranch,
    EmptyElse,
    MissingCase,
    NotResult,
    TryWithoutResult,
    UnheldError,
    DiscardedError,
    TryInDefer,
    JumpInDefer,
    UnreachableCode,
    ReturnOutsideFunction,
    BreakOutsideLoop,
    ContinueOutsideLoop,
    ConflictingDeclaredType,
    ErrdeferWithoutError,
    NoLayout,
    ExpectedNumber,
    ExpectedInteger,
    NotTupleType,
    ElementNotTuple,
    PointerOverIterator,
    CursorNotIterator,
};

fn describeError(check_error: CheckError) []const u8 {
    return switch (check_error) {
        error.OutOfMemory => "out of memory",
        error.DependencyLoop => "value depends on itself at compile time",
        error.TypeMismatch => "value does not match the expected type",
        error.LiteralOutOfRange => "literal out of range for its type",
        error.NegativeUnsigned => "unsigned types cannot hold negative numbers",
        error.MissingReturnValue => "missing return value",
        error.UnexpectedReturnValue => "void function cannot return a value",
        error.MissingReturn => "every path must end with a return",
        error.ValueIfWithoutElse => "an if used as a value needs an else",
        error.MissingBranchValue => "this line gives no value, but the block must end with one",
        error.BranchTypeMismatch => "every block must give the same type; write the type to convert them",
        error.UnusedValue => "this value is unused; only the last line of a value block or of a function with a return type gives a value",
        error.MainHasReturnType => "main returns nothing or a result without a value, e.g. E!void",
        error.MainHasParameters => "main cannot have parameters",
        error.MainCalled => "main cannot be called",
        error.MainIsExternal => "main cannot be external",
        error.ArgumentCountMismatch => "wrong number of arguments",
        error.InstanceDefaultMismatch => "an instance's parameter default must be the default its typeclass gives that parameter, and a parameter without one in the typeclass cannot have one in the instance",
        error.UnfitInstanceDefault => "the default the typeclass gives this parameter does not fit the type this instance gives it",
        error.UnusedResult => "call result is unused, discard it with _ =",
        error.DiscardedVoid => "there is no value to discard",
        error.TypeVariable => "variable cannot hold a type",
        error.TypeParameter => "parameter cannot hold a type",
        error.CompileTimeValue => "value exists only at compile time",
        error.RuntimeArgument => "argument must be known at compile time",
        error.GenericValue => "function needs its compile-time arguments",
        error.InstanceDepth => "instances nest more than 512 deep",
        error.UnexpectedUndefined => "undefined can only be the initial value of a variable",
        error.UnreachableStatement => "statement never runs",
        error.UnexpectedNull => "null can only be the value of an optional",
        error.NotSliceable => "only arrays, slices and *many(T) pointers can be sliced",
        error.SlicedTemporary => "only arrays that are variables, constants, elements or fields can be sliced",
        error.MissingEnd => "a slice of a *many(T) pointer needs an end",
        error.NotIndexable => "only arrays, slices, *many(T) pointers and tuples can be indexed",
        error.IndexOutOfRange => "index is outside the length",
        error.UnknownTupleIndex => "a tuple index must be known at compile time",
        error.NotAddressable => "only variables, constants, elements, fields and functions have an address",
        error.MissingLength => "value has no length",
        error.CannotEvaluate => "cannot be evaluated at compile time",
        error.NotAPointer => "only pointers can be dereferenced",
        error.NotOptional => "value is not an optional",
        error.SinglePointerArithmetic => "only *many(T) pointers support arithmetic",
        error.ZeroSizedPointerArithmetic => "pointers to zero-sized values do not support arithmetic",
        error.NotWritable => "value cannot be modified",
        error.NeverModified => "variable is never modified, declare it with const",
        error.UnusedVariable => "variable is unused, discard it with _ =",
        error.PointlessDiscard => "discarded name is used",
        error.WrongLength => "number of elements does not match the length of the array",
        error.WrongTupleLength => "number of elements does not match the tuple",
        error.UnexpectedBraces => "braces need an array, a tuple or a struct type",
        error.NotCallable => "only functions and function pointers can be called",
        error.FunctionUsedAsValue => "function is not a value, point to it with &",
        error.FunctionDereferenced => "function pointers cannot be dereferenced",
        error.VoidDereferenced => "pointers to void cannot be dereferenced",
        error.ExpectedPointer => "expected a pointer to a value",
        error.ExpectedManyPointer => "expected a *many(T) pointer",
        error.ComptimeError => "compile-time error",
        error.NeedsAllocator => "this value cannot be computed at compile time because it allocates",
        error.AllocatorNotNeeded => "this call does not need an allocator",
        error.NotAllocator => "`with` takes a pointer to a value whose type has an instance of mn::memory::Allocator",
        error.AllocatorNeedsPointer => "this allocator type has fields, so `with` needs a pointer to a value of it, where its state lives",
        error.MissingAllocator => "this needs an allocator, and none is set here; set one with `with`, e.g. `with memory::Heap`",
        error.AllocatorFunctionAddress => "a function that needs an allocator has no address yet",
        error.OwnResultMisplaced => "this call's result is owned; it goes only into an own declaration, an own parameter or field, or the return of an own function",
        error.OwnNeedsClone => "this value is a view: this place owns its value, and a view cannot be moved into it; pass a copy made with clone, e.g. try value.clone()",
        error.OwnMarkerMissing => "this is held by a name declared own; write own before it to hand it on, e.g. own record",
        error.OwnMarkerMisplaced => "own here needs a name declared own or a part stored inline in one, passed to an own parameter or field",
        error.ReceiverNotTakenOver => "this method does not take over its receiver, so it is called without own as its first argument",
        error.OwnNameReturned => "a name declared own is returned only from a function whose return type is own",
        error.OwnNameMoved => "this name's value has moved; give the name a new value before using it again",
        error.OwnValueCopied => "this would copy a value that owns memory; pass a pointer to it instead, or a copy made with clone",
        error.OwnWithoutAllocation => "own needs a type with a pointer, a slice or an own field, since nothing in this type can have been allocated",
        error.OwnPartMoved => "this value cannot be used as a whole, since one of its parts has moved; its other parts can still be used",
        error.OwnPartIndexUnknown => "own takes an element out of an inline array only with an index known at compile time",
        error.OwnPointerNotOwned => "an own pointer parameter takes `own &name` for a name declared own, or `own &name.part` for a part of one, e.g. `own &record`",
        error.OwnNotConsumed => "this name still holds what it owns where it goes out of reach; hand it on with own before then",
        error.OwnNameDiscarded => "a name declared own cannot be discarded with `_ =`; hand it on with own instead",
        error.OwnParameterHandedOn => "an own parameter is handed on before its function fails, while the caller still holds it",
        error.OwnVariableHeld => "this variable still holds what it owns; hand it on with own before giving it a new value",
        error.OwnPartHeld => "this part still holds a value; end it or take it out first",
        error.InlineMain => "main cannot be inline",
        error.PrivateMain => "main cannot be private, since the program starts at it",
        error.PrivateField => "the field is private to the module of its struct",
        error.PrivateFieldLiteral => "a struct with a private field is built through the functions of its module",
        error.PrivateDeclaration => "the declaration is private to its module",
        error.NeedlessPrivate => "private at a use crosses into a private declaration or field of another module, and is written nowhere else",
        error.OwnUnendable => "the value can be held but not ended outside the module of its type",
        error.InlineValue => "an inline function cannot be used as a value",
        error.InlineRecursion => "an inline function cannot call itself, directly or through other functions",
        error.ComptimeErrorAsValue => "mn::comptime::error can only be used as a statement",
        error.UnknownMethod => "unknown method",
        error.AmbiguousMethod => "method is found in more than one place",
        error.NoSelf => "function is not a method",
        error.UndecidedInstance => "name the instance, the arguments do not decide it",
        error.UndecidedConstructorArgument => "the arguments do not decide every argument of the function that gives the type; write them out",
        error.HiddenConstructorSignature => "the function cannot be seen without the arguments of the function that gives its type; write them out",
        error.AmbiguousInstance => "more than one instance fits",
        error.MissingRequiredInstance => "type has no instance of a typeclass that the typeclass requires",
        error.UnknownSuffix => "unknown suffix",
        error.UnknownValueType => "value has no known type",
        error.CaseWithoutEnum => ast.case_without_enum_message,
        error.ParenthesizedCaseValue => "a case's value is written in braces, not parentheses, e.g. `::Number{ 42 }`",
        error.CaseValueCount => "a case carries one value in its braces, e.g. `::Number{ 42 }`; a case whose value is a tuple takes the tuple's elements, e.g. `::Pair{ 1, 2 }`",
        error.CaseWithoutKnownEnum => ast.case_without_known_enum_message,
        error.UnknownTypeArgument => "_ needs its type known from the surrounding code",
        error.LiteralFunctionIsMethod => "a function that takes the value as its first parameter cannot be written with a leading ::",
        error.LiteralFunctionType => "a function written with a leading :: returns the expected type",
        error.InferredTypeOutOfPlace => "_ stands only for the argument of a type parameter",
        error.NoFields => "value has no fields",
        error.UnknownField => "unknown field",
        error.NamedArgument => "function arguments have no names",
        error.NotAStruct => "type is not a struct",
        error.MissingFieldName => "a value in a struct literal is given with its field name, e.g. `x = 1`, and only a name equal to its field's stands alone, e.g. `x` for `x = x`",
        error.RepeatedField => "field is already given",
        error.MissingField => "missing field",
        error.NotNumeric => "operator needs integers or floats",
        error.NotInteger => "operator needs integers",
        error.NotEquatable => "only numbers, bool, types, pointers, enums and arrays of them can be compared for equality",
        error.NotOrdered => "only numbers and *many(T) pointers can be ordered",
        error.NegatedUnsigned => "unsigned integers cannot be negated",
        error.MismatchedOperands => "operands have different types",
        error.NotSequence => "for goes only over an array, a slice, a pointer to an array, a range or a value whose type has an instance of mn::iterator::Iterable",
        error.ReversedRange => "range starts after its end",
        error.NotTuple => "names in braces need a tuple",
        error.WrongNameCount => "number of names does not match the tuple",
        error.CaseNeedsValue => "case carries a value, give it in braces, e.g. `::Number{ 42 }`",
        error.CaseWithoutValue => "case carries no value",
        error.NotMatchable => "only enums, error sets, results, optionals and integers can be matched",
        error.WrongCaseType => "case is not the type of the value",
        error.MisplacedRange => "only an integer can be matched against a range",
        error.MisplacedValueName => "this case cannot name its value this way",
        error.EmptyRange => "range has no values",
        error.RangeOutsideArray => "the range of this loop ends past the length of the array",
        error.UnknownCase => "enum has no such case",
        error.AmbiguousCase => "case name is ambiguous, name its enum",
        error.DuplicateBranch => "case is already covered",
        error.EmptyElse => "else covers no case",
        error.MissingCase => "a case has no branch",
        error.NotResult => "expected a result, e.g. E!T",
        error.TryWithoutResult => "try needs a function that returns a result",
        error.UnheldError => "the function's result cannot hold this error",
        error.DiscardedError => "a result that can hold an error cannot be discarded",
        error.TryInDefer => "a deferred statement cannot use try",
        error.JumpInDefer => "a deferred statement cannot return, break or continue",
        error.UnreachableCode => "code can never run because of an earlier return, break or continue",
        error.ReturnOutsideFunction => "return outside a function body",
        error.BreakOutsideLoop => "break outside a loop",
        error.ContinueOutsideLoop => "continue outside a loop",
        error.ConflictingDeclaredType => "the arguments give a declared type two different types",
        error.ErrdeferWithoutError => "errdefer needs a function that can return an error",
        error.NoLayout => "type has no size at run time",
        error.ExpectedNumber => "expected a number",
        error.ExpectedInteger => "expected an integer",
        error.NotTupleType => "only tuple types can be indexed",
        error.ElementNotTuple => "an iterator's elements must be tuples",
        error.PointerOverIterator => "this element of the iterator is not a pointer, so it cannot be named by pointer; name it without *",
        error.CursorNotIterator => "the cursor that this value's Iterable instance gives has no instance of Iterator, so for cannot go over it",
        error.NoInstance => "type has no instance of the typeclass",
    };
}

