const Production = struct {
    expected: ?types.Type,
    found: ?types.Type = null,
    result: bool = false,
    ends_with_void: bool = false,
    combining: bool = false,
    value: ?types.Type = null,
    errors: ?*const types.Enum = null,
    mixed: ?token.Location = null,
    void_line: ?token.Location = null,
};

const Trace = struct {
    exits: std.ArrayList(Exit) = .empty,
};

const Exit = struct {
    loop: *const ast.Statement,
    flow: Flow = .ended,
};

const Flow = enum {
    ended,
    reached,
};

fn mergeExit(trace: *Trace, loop: *const ast.Statement, flow: Flow) void {
    for (trace.exits.items) |*exit| {
        if (exit.loop == loop) exit.flow = mergeFlows(exit.flow, flow);
    }
}

fn mergeFlows(one: Flow, two: Flow) Flow {
    if (one == .ended) return two;
    if (two == .ended) return one;
    return .reached;
}

fn isEndless(statement: ast.Statement) bool {
    return switch (statement.kind) {
        .@"while" => |loop| loop.condition.kind == .boolean_literal and loop.condition.kind.boolean_literal,
        .@"for" => |loop| loop.sequence == .range and loop.sequence.range.end == null,
        .noop, .@"return", .discard, .call, .constant_declaration, .tuple_declaration, .variable_declaration => false,
        .assignment, .@"if", .match, .@"defer", .@"break", .@"continue", .value => false,
    };
}

fn isUnfinishedArray(written: ast.Expression) bool {
    return written.kind == .array_type and written.kind.array_type.value == null;
}

fn canHoldError(return_type: types.Type) bool {
    return return_type == .result and return_type.result.error_set.cases.len > 0;
}

fn returnsNoValue(return_type: types.Type) bool {
    return return_type == .void or (return_type == .result and return_type.result.value == .void);
}

fn findErrorSet(value_type: types.Type) ?*const types.Enum {
    return switch (value_type) {
        .result => |result| result.error_set,
        .@"enum" => |enumeration| if (enumeration.kind == .error_set) enumeration else null,
        else => null,
    };
}

fn isResultConvertible(value: types.Result, expected: types.Result) bool {
    if (!std.meta.eql(value.value, expected.value)) return false;
    return value.error_set.cases.len == 0 or types.isEnumPart(value.error_set, expected.error_set);
}

fn isWidened(value_type: types.Type, expected: types.Type) bool {
    if (value_type != .number) return false;
    const target = if (expected == .optional) expected.optional.child else expected;
    return target == .number and target.number != value_type.number;
}

fn isWidening(value: types.NumberType, expected: types.NumberType) bool {
    const value_float = isFloatNumber(value);
    if (value_float != isFloatNumber(expected)) return false;
    if (value_float) return findBits(value) < findBits(expected);
    const value_signed = isSignedNumber(value);
    const expected_signed = isSignedNumber(expected);
    if (value_signed and !expected_signed) return false;
    if (value_signed == expected_signed) return findBits(value) <= findBits(expected);
    return findBits(value) < findBits(expected);
}

fn isFloatNumber(number: types.NumberType) bool {
    return number == .f16 or number == .f32 or number == .f64 or number == .f128;
}

fn isSignedNumber(number: types.NumberType) bool {
    return switch (number) {
        .i8, .i16, .i32, .i64, .i128, .isize => true,
        .u8, .u16, .u32, .u64, .u128, .usize, .f16, .f32, .f64, .f128 => false,
    };
}

fn findBits(number: types.NumberType) u8 {
    return switch (number) {
        .i8, .u8 => 8,
        .i16, .u16, .f16 => 16,
        .i32, .u32, .f32 => 32,
        .i64, .u64, .isize, .usize, .f64 => 64,
        .i128, .u128, .f128 => 128,
    };
}

fn isConvertible(value_type: types.Type, expected: types.Type) bool {
    if (isDirectlyConvertible(value_type, expected)) return true;
    if (expected == .optional) return isDirectlyConvertible(value_type, expected.optional.child);
    if (expected != .result) return false;
    if (value_type == .result) return isResultConvertible(value_type.result.*, expected.result.*);
    if (isConvertible(value_type, expected.result.value)) return true;
    return value_type == .@"enum" and types.isEnumPart(value_type.@"enum", expected.result.error_set);
}

fn isDirectlyConvertible(value_type: types.Type, expected: types.Type) bool {
    if (isReadOnlyMatch(value_type, expected)) return true;
    if (isVoidPointerConversion(value_type, expected)) return true;
    if (value_type == .number and expected == .number) return isWidening(value_type.number, expected.number);
    if (value_type == .@"enum" and expected == .@"enum" and types.isEnumPart(value_type.@"enum", expected.@"enum")) return true;
    if (expected != .slice or value_type != .pointer) return false;
    const pointer = value_type.pointer;
    if (pointer.many or pointer.target != .array) return false;
    if (pointer.constant and !expected.slice.constant) return false;
    return std.meta.eql(pointer.target.array.element, expected.slice.element);
}

fn isVoidPointerConversion(value_type: types.Type, expected: types.Type) bool {
    if (value_type != .pointer or expected != .pointer) return false;
    const target = expected.pointer;
    if (target.target != .void or target.many) return false;
    const pointer = value_type.pointer;
    if (pointer.target == .function) return false;
    return target.constant or !pointer.constant;
}

fn isDataPointer(value_type: types.Type) bool {
    return value_type == .pointer and value_type.pointer.target != .function;
}

fn isReadOnlyMatch(value_type: types.Type, expected: types.Type) bool {
    if (std.meta.eql(value_type, expected)) return true;
    if (value_type == .pointer and expected == .pointer) {
        const pointer = value_type.pointer;
        if (pointer.many != expected.pointer.many) return false;
        return expected.pointer.constant and std.meta.eql(pointer.target, expected.pointer.target);
    }
    if (value_type != .slice or expected != .slice) return false;
    const element = value_type.slice.element;
    return expected.slice.constant and std.meta.eql(element, expected.slice.element);
}

fn findLiteralType(expected: types.Type) types.Type {
    var current = expected;
    while (true) {
        switch (current) {
            .result => |result| current = result.value,
            .optional => |optional| current = optional.child,
            else => return current,
        }
    }
}

fn recordExpectedType(expression: *ast.Expression, expected: types.Type) void {
    var current = expression;
    while (true) {
        switch (current.kind) {
            .@"try" => |operand| current = operand,
            .binary => |binary| {
                if (binary.operator != .@"catch" and binary.operator != .@"orelse") return;
                current = binary.left;
            },
            .case_literal => |*literal| {
                literal.expected = expected;
                return;
            },
            .call => |call| return recordExpectedArguments(call.arguments, expected),
            .method_call => |call| return recordExpectedArguments(call.arguments, expected),
            else => return,
        }
    }
}

fn recordExpectedArguments(arguments: []ast.Argument, expected: types.Type) void {
    for (arguments) |*argument| {
        if (argument.value.kind == .inferred_type) argument.value.kind.inferred_type.expected = expected;
    }
}

fn hasTypeclassTypeParameter(definition: ast.TypeclassDefinition, signature: ast.FunctionSignature) bool {
    for (signature.parameters) |parameter| {
        if (parameter.kind == .type and findTypeclassParameter(definition, parameter.name) != null) return true;
    }
    return false;
}

fn findTypeclassParameter(definition: ast.TypeclassDefinition, name: []const u8) ?usize {
    for (definition.parameters, 0..) |parameter, index| {
        if (std.mem.eql(u8, parameter.name, name)) return index;
    }
    return null;
}

fn takesExpectedType(expression: ast.Expression) bool {
    return switch (expression.kind) {
        .integer_literal, .float_literal, .negation, .composite_literal => !hasOwnType(expression),
        .boolean_literal => true,
        else => false,
    };
}

fn hasOwnType(expression: ast.Expression) bool {
    return switch (expression.kind) {
        .integer_literal, .float_literal => |literal| literal.suffix != null,
        .negation => |operand| hasOwnType(operand.*),
        .composite_literal => |literal| literal.type != null,
        .null, .undefined, .jump, .branching, .case_literal, .inferred_type => false,
        .unary => |unary| unary.operator == .not or hasOwnType(unary.operand.*),
        .binary => |binary| switch (binary.operator) {
            .shift_left, .shift_right, .@"orelse" => hasOwnType(binary.left.*),
            .combine, .result, .@"catch" => true,
            .add,
            .subtract,
            .multiply,
            .divide,
            .remainder,
            .bitwise_and,
            .bitwise_exclusive_or,
            .bitwise_or,
            => hasOwnType(binary.left.*) or hasOwnType(binary.right.*),
            .equal,
            .not_equal,
            .less_than,
            .less_than_or_equal,
            .greater_than,
            .greater_than_or_equal,
            .@"and",
            .@"or",
            => true,
        },
        .boolean_literal,
        .string_literal,
        .identifier,
        .path_expression,
        .member,
        .call,
        .method_call,
        .address_of,
        .array_type,
        .slice_type,
        .index,
        .slice,
        .pointer_type,
        .optional_type,
        .tuple_type,
        .function_type,
        .struct_type,
        .field_access,
        .dereference,
        .unwrap,
        .@"try",
        .range,
        => true,
    };
}

fn hasNames(elements: []const ast.Argument) bool {
    for (elements) |element| {
        if (element.name != null or element.crossing) return true;
    }
    return false;
}

fn findElement(elements: []const ast.Argument, name: []const u8) ?*const ast.Argument {
    for (elements) |*element| {
        const element_name = element.name orelse switch (element.value.kind) {
            .identifier => |identifier| identifier.name,
            else => continue,
        };
        if (std.mem.eql(u8, element_name, name)) return element;
    }
    return null;
}

fn unifyTypes(one: types.Type, two: types.Type) ?types.Type {
    if (isReadOnlyMatch(one, two)) return two;
    if (isReadOnlyMatch(two, one)) return one;
    if (one == .@"enum" and two == .@"enum") {
        if (types.isEnumPart(one.@"enum", two.@"enum")) return two;
        if (types.isEnumPart(two.@"enum", one.@"enum")) return one;
    }
    return null;
}

fn isEquatable(value_type: types.Type) bool {
    return switch (value_type) {
        .number, .boolean, .type, .pointer => true,
        .array => |array| isEquatable(array.element),
        .optional => |optional| isEquatable(optional.child),
        .result => false,
        .@"enum" => |enumeration| {
            for (enumeration.cases) |case| {
                if (!isEquatable(case.type orelse continue)) return false;
            }
            return true;
        },
        .void, .@"struct", .slice, .tuple, .function, .variable, .application => false,
    };
}

fn containsBoundVariable(arguments: []const Bound) bool {
    for (arguments) |argument| {
        if (argument.value != .type) continue;
        if (types.containsVariable(argument.value.type, .function) or types.containsVariable(argument.value.type, .typeclass)) return true;
    }
    return false;
}

fn containsVariable(decided: []const ?types.Argument) bool {
    for (decided) |optional_argument| {
        const argument = optional_argument orelse continue;
        switch (argument) {
            .type => |value_type| {
                if (types.containsVariable(value_type, .typeclass) or types.containsVariable(value_type, .function)) return true;
            },
            .constructor => |constructor| if (constructor == .variable) return true,
            .length => {},
        }
    }
    return false;
}

fn matchesConstraint(constraint: ast.Constraint, decided: []const ?types.Argument) bool {
    if (constraint.arguments.len != decided.len) return false;
    for (constraint.arguments, decided) |argument, optional_argument| {
        const decided_argument = optional_argument orelse continue;
        if (!std.meta.eql(argument, decided_argument)) return false;
    }
    return true;
}

fn mentionsReceiver(constraint: ast.Constraint, receiver: types.Type) bool {
    if (constraint.arguments.len == 0) return false;
    const first = constraint.arguments[0];
    return first == .type and std.meta.eql(first.type, receiver);
}

fn isConcreteArguments(arguments: []const types.Argument) bool {
    for (arguments) |argument| {
        switch (argument) {
            .type => |value_type| {
                if (types.containsVariable(value_type, .typeclass) or types.containsVariable(value_type, .function)) return false;
            },
            .constructor => |constructor| if (constructor == .variable) return false,
            .length => {},
        }
    }
    return true;
}

fn acceptsArgumentCount(signature: ast.FunctionSignature, count: usize) bool {
    if (count > signature.parameters.len) return false;
    for (signature.parameters[count..]) |parameter| {
        if (parameter.default_constant == null and parameter.default == null) return false;
    }
    return true;
}

fn findTypeclassFunction(definition: ast.TypeclassDefinition, name: []const u8) ?usize {
    for (definition.functions, 0..) |signature, position| {
        if (std.mem.eql(u8, signature.name, name)) return position;
    }
    return null;
}

fn isOrdered(value_type: types.Type) bool {
    return switch (value_type) {
        .number => true,
        .pointer => |pointer| pointer.many,
        .boolean, .void, .type, .@"struct", .@"enum", .array, .slice, .optional, .result, .tuple, .function, .variable, .application => {
            return false;
        },
    };
}

fn mentionsBinding(bindings: []const ast.Binding, expression: ast.Expression) bool {
    return switch (expression.kind) {
        .identifier => |identifier| isBoundName(bindings, identifier.name, identifier.resolution),
        .path_expression => |path_expression| isBoundName(bindings, path_expression.path[0], path_expression.resolution),
        .call => |call| isBoundCallee(bindings, call.callee) or for (call.arguments) |argument| {
            if (mentionsBinding(bindings, argument.value)) break true;
        } else false,
        .array_type => |array_type| mentionsBinding(bindings, array_type.element.*) or
            (if (array_type.length) |length| mentionsBinding(bindings, length.*) else false),
        .slice_type => |slice_type| mentionsBinding(bindings, slice_type.element.*),
        .pointer_type => |pointer_type| mentionsBinding(bindings, pointer_type.target.*),
        .optional_type => |optional_type| mentionsBinding(bindings, optional_type.child.*),
        .tuple_type => |tuple_type| for (tuple_type.elements) |element| {
            if (mentionsBinding(bindings, element)) break true;
        } else false,
        .function_type => |function_type| mentionsBinding(bindings, function_type.return_type.*) or for (function_type.parameters) |parameter| {
            if (mentionsBinding(bindings, parameter)) break true;
        } else false,
        .binary => |binary| mentionsBinding(bindings, binary.left.*) or mentionsBinding(bindings, binary.right.*),
        .index => |indexing| mentionsBinding(bindings, indexing.value.*) or mentionsBinding(bindings, indexing.index.*),
        .field_access => |access| mentionsBinding(bindings, access.value.*),
        else => false,
    };
}

fn isBoundCallee(bindings: []const ast.Binding, callee: ast.Name) bool {
    return switch (callee) {
        .identifier => |identifier| isBoundName(bindings, identifier.name, identifier.resolution),
        .path_expression => |path_expression| isBoundName(bindings, path_expression.path[0], path_expression.resolution),
        .member => false,
    };
}

fn isBoundName(bindings: []const ast.Binding, name: []const u8, resolution: ?ast.Resolution) bool {
    const resolved = resolution orelse return false;
    if (resolved == .local or resolved == .parameter or resolved == .element) return false;
    for (bindings) |binding| {
        if (std.mem.eql(u8, binding.name, name)) return true;
    }
    return false;
}

fn appendBlockCalls(
    allocator: std.mem.Allocator,
    calls: *std.ArrayList(FunctionCall),
    statements: []const ast.Statement,
) std.mem.Allocator.Error!void {
    for (statements) |statement| {
        switch (statement.kind) {
            .@"return" => |value| if (value) |returned| try appendExpressionCalls(allocator, calls, returned),
            .discard, .call => |expression| try appendExpressionCalls(allocator, calls, expression),
            .constant_declaration => |constant| try appendExpressionCalls(allocator, calls, constant.value),
            .variable_declaration => |variable| try appendExpressionCalls(allocator, calls, variable.value),
            .tuple_declaration => |declaration| try appendExpressionCalls(allocator, calls, declaration.value),
            .assignment => |assignment| {
                try appendExpressionCalls(allocator, calls, assignment.target);
                try appendExpressionCalls(allocator, calls, assignment.value);
            },
            .@"if" => |conditional| try appendExpressionCalls(allocator, calls, conditional.condition),
            .@"while" => |loop| try appendExpressionCalls(allocator, calls, loop.condition),
            .@"for" => |loop| switch (loop.sequence) {
                .value => |value| try appendExpressionCalls(allocator, calls, value),
                .range => |range| {
                    try appendExpressionCalls(allocator, calls, range.start);
                    if (range.end) |end| try appendExpressionCalls(allocator, calls, end);
                },
            },
            .match => |matching| try appendExpressionCalls(allocator, calls, matching.value),
            .@"defer" => |deferred| try appendBlockCalls(allocator, calls, deferred.statement[0..1]),
            .value => |expression| try appendExpressionCalls(allocator, calls, expression),
            .noop, .@"break", .@"continue" => {},
        }
        var blocks = ast.iterateBlocks(statement);
        while (blocks.next()) |block| try appendBlockCalls(allocator, calls, block);
    }
}

fn appendExpressionCalls(
    allocator: std.mem.Allocator,
    calls: *std.ArrayList(FunctionCall),
    expression: ast.Expression,
) std.mem.Allocator.Error!void {
    switch (expression.kind) {
        .call => |call| {
            const resolution: ?ast.Resolution = switch (call.callee) {
                inline else => |name| name.resolution,
            };
            if (resolution) |resolved| {
                if (resolved == .function) try calls.append(allocator, .{ .function = resolved.function, .location = expression.location });
            }
            for (call.arguments) |argument| try appendExpressionCalls(allocator, calls, argument.value);
        },
        .method_call => |call| {
            try appendExpressionCalls(allocator, calls, call.receiver.*);
            for (call.arguments) |argument| try appendExpressionCalls(allocator, calls, argument.value);
        },
        .composite_literal => |literal| {
            for (literal.elements) |element| try appendExpressionCalls(allocator, calls, element.value);
        },
        .case_literal => |literal| {
            for (literal.arguments) |element| try appendExpressionCalls(allocator, calls, element.value);
        },
        .inferred_type => {},
        .binary => |binary| {
            try appendExpressionCalls(allocator, calls, binary.left.*);
            try appendExpressionCalls(allocator, calls, binary.right.*);
        },
        .unary => |unary| try appendExpressionCalls(allocator, calls, unary.operand.*),
        .negation, .address_of, .dereference, .unwrap, .@"try" => |operand| try appendExpressionCalls(allocator, calls, operand.*),
        .index => |indexing| {
            try appendExpressionCalls(allocator, calls, indexing.value.*);
            try appendExpressionCalls(allocator, calls, indexing.index.*);
        },
        .slice => |slice| {
            try appendExpressionCalls(allocator, calls, slice.value.*);
            if (slice.start) |start| try appendExpressionCalls(allocator, calls, start.*);
            if (slice.end) |end| try appendExpressionCalls(allocator, calls, end.*);
        },
        .field_access => |access| try appendExpressionCalls(allocator, calls, access.value.*),
        .range => |range| {
            try appendExpressionCalls(allocator, calls, range.start);
            if (range.end) |end| try appendExpressionCalls(allocator, calls, end);
        },
        .jump => |statement| try appendBlockCalls(allocator, calls, statement[0..1]),
        .branching => |statement| try appendBlockCalls(allocator, calls, statement[0..1]),
        .integer_literal,
        .float_literal,
        .boolean_literal,
        .string_literal,
        .undefined,
        .null,
        .identifier,
        .path_expression,
        .member,
        .array_type,
        .slice_type,
        .pointer_type,
        .optional_type,
        .tuple_type,
        .function_type,
        .struct_type,
        => {},
    }
}

fn containsCall(expression: ast.Expression) bool {
    return switch (expression.kind) {
        .call, .method_call, .@"try", .jump, .branching => true,
        .field_access => |access| containsCall(access.value.*),
        .index => |indexing| containsCall(indexing.value.*) or containsCall(indexing.index.*),
        .dereference, .unwrap, .address_of, .negation => |operand| containsCall(operand.*),
        .unary => |unary| containsCall(unary.operand.*),
        .binary => |binary| containsCall(binary.left.*) or containsCall(binary.right.*),
        .slice => |slice| containsCall(slice.value.*) or
            (if (slice.start) |start| containsCall(start.*) else false) or
            (if (slice.end) |end| containsCall(end.*) else false),
        .composite_literal => |literal| for (literal.elements) |element| {
            if (containsCall(element.value)) break true;
        } else false,
        .case_literal => |literal| literal.called or for (literal.arguments) |argument| {
            if (containsCall(argument.value)) break true;
        } else false,
        .inferred_type => false,
        .range => |range| containsCall(range.start) or (if (range.end) |end| containsCall(end) else false),
        .integer_literal,
        .float_literal,
        .boolean_literal,
        .string_literal,
        .undefined,
        .null,
        .identifier,
        .path_expression,
        .member,
        .array_type,
        .slice_type,
        .pointer_type,
        .optional_type,
        .tuple_type,
        .function_type,
        .struct_type,
        => false,
    };
}

fn markMeasured(parameters: []const ast.TypedName, base: ast.Expression) void {
    if (base.kind != .identifier) return;
    const resolution = base.kind.identifier.resolution orelse return;
    if (resolution == .parameter) {
        if (resolution.parameter < parameters.len) @constCast(&parameters[resolution.parameter]).measured = true;
        return;
    }
    if (resolution != .local) return;
    const statement = @constCast(resolution.local);
    switch (statement.kind) {
        .constant_declaration => |*constant| constant.measured = true,
        .variable_declaration => |*variable| variable.measured = true,
        else => {},
    }
}

fn isErrorPattern(error_set: *const types.Enum, pattern: ast.Expression) bool {
    return switch (pattern.kind) {
        .identifier => |identifier| for (error_set.cases) |case| {
            if (std.mem.eql(u8, case.name, identifier.name)) break true;
        } else false,
        .path_expression => |path_expression| path_expression.resolution.? == .case,
        else => false,
    };
}

fn isCallOrTriedCall(expression: ast.Expression) bool {
    const call = if (expression.kind == .@"try") expression.kind.@"try".* else expression;
    if (expression.kind == .@"try" and call.kind == .branching) return true;
    return call.kind == .call or call.kind == .method_call;
}

fn countInferred(error_set: *const types.Enum) usize {
    return error_set.parts.len + error_set.cases.len;
}

fn isShortCircuit(operator: ast.BinaryOperator) bool {
    return operator == .@"and" or operator == .@"or" or operator == .@"orelse" or operator == .@"catch";
}

fn isUnknownName(expression: ast.Expression) bool {
    return expression.kind == .identifier and expression.kind.identifier.resolution == null;
}

fn coversRange(cases: []const *const ast.BranchCase, minimum: Integer, maximum: Integer) bool {
    var next = minimum;
    while (true) {
        const reaching = findCoveringMaximum(cases, next) orelse return false;
        if (reaching.order(maximum) != .lt) return true;
        next = reaching.increment();
    }
}

fn findCoveringMaximum(cases: []const *const ast.BranchCase, value: Integer) ?Integer {
    for (cases) |case| {
        if (case.minimum.order(value) != .gt and value.order(case.maximum) != .gt) return case.maximum;
    }
    return null;
}

fn isInteger(value_type: types.Type) bool {
    return value_type == .number and computeIntegerMaximum(value_type.number) != null;
}

fn findPlaceType(root_type: types.Type, steps: []const ast.PartStep) ?types.Type {
    var current = root_type;
    for (steps) |step| current = findStepType(current, step) orelse return null;
    return current;
}

fn findStepType(value_type: types.Type, step: ast.PartStep) ?types.Type {
    switch (step) {
        .field => |name| {
            if (value_type != .@"struct") return null;
            const field = findField(value_type.@"struct".fields, name) orelse return null;
            return field.type;
        },
        .element => |position| return switch (value_type) {
            .array => |array| array.element,
            .tuple => |tuple| if (position < tuple.elements.len) tuple.elements[position] else null,
            else => null,
        },
        .value => {
            if (value_type != .optional) return null;
            return value_type.optional.child;
        },
    }
}

fn isEmptyValue(value: ast.Expression) bool {
    return switch (value.kind) {
        .undefined, .null => true,
        .composite_literal => |literal| literal.elements.len == 0,
        else => false,
    };
}

fn findField(fields: []const types.Field, name: []const u8) ?types.Field {
    for (fields) |field| {
        if (std.mem.eql(u8, field.name, name)) return field;
    }
    return null;
}

fn findFunction(expression: ast.Expression) ?ast.Resolution {
    return switch (expression.kind) {
        inline .identifier, .path_expression, .member => |name| switch (name.resolution.?) {
            .function, .typeclass_function => name.resolution.?,
            .parameter, .type, .constant, .local, .element, .typeclass_method, .case, .builtin => null,
        },
        else => null,
    };
}

fn findFunctionName(modules: []const ast.Module, function: ast.Resolution.Function) []const u8 {
    return ast.findDeclaration(modules[function.module], function.declaration).kind.function_definition.signature.name;
}

fn containsFunction(functions: []const ast.Resolution.Function, function: ast.Resolution.Function) bool {
    for (functions) |one| {
        if (std.meta.eql(one, function)) return true;
    }
    return false;
}

fn isNoneAllocator(modules: []const ast.Module, value_type: types.Type) bool {
    if (value_type != .@"struct" or !std.mem.eql(u8, value_type.@"struct".name, "None")) return false;
    const path = modules[value_type.@"struct".module].path;
    return path.len == 2 and std.mem.eql(u8, path[0], "mn") and std.mem.eql(u8, path[1], "memory");
}

fn findMemoryTypeclass(modules: []const ast.Module, name: []const u8) ?ast.Resolution.Typeclass {
    for (modules, 0..) |module, module_index| {
        if (!isMemoryModule(module.path)) continue;
        for (module.declarations, 0..) |declaration, index| {
            if (declaration.kind != .typeclass_definition) continue;
            if (std.mem.eql(u8, declaration.kind.typeclass_definition.name, name)) return .{ .module = module_index, .declaration = index };
        }
    }
    return null;
}

fn containsAnyVariable(value_type: types.Type) bool {
    for ([_]types.Scope{ .typeclass, .instance, .function, .declared }) |scope| {
        if (types.containsVariable(value_type, scope)) return true;
    }
    return false;
}

fn isTypeclassVisible(module: ast.Module, module_index: usize, typeclass: ast.Resolution.Typeclass) bool {
    for (module.declarations, 0..) |declaration, index| {
        switch (declaration.kind) {
            .typeclass_definition => {
                if (typeclass.module == module_index and typeclass.declaration == index) return true;
            },
            .import => |import| {
                const imported = import.typeclass orelse continue;
                if (std.meta.eql(imported, typeclass)) return true;
            },
            .function_declaration,
            .function_definition,
            .constant_declaration,
            .struct_definition,
            .enum_definition,
            .instance_declaration,
            => {},
        }
    }
    return false;
}

fn isPlace(expression: ast.Expression) bool {
    return switch (expression.kind) {
        inline .identifier, .path_expression, .member => |name| switch (name.resolution.?) {
            .local, .parameter, .constant, .element => true,
            .function, .type, .typeclass_function, .typeclass_method, .case, .builtin => false,
        },
        .field_access => |access| !isSliceField(access) and (access.value.type.? == .pointer or isPlace(access.value.*)),
        .index => |indexing| isElementPlace(indexing.value.*),
        .dereference => true,
        else => false,
    };
}

fn isSliceField(access: ast.FieldAccess) bool {
    return followPointer(access.value.type.?) == .slice;
}

fn isElementPlace(container: ast.Expression) bool {
    return !isStorage(container) or isPlace(container);
}

fn isWritable(expression: ast.Expression) bool {
    return switch (expression.kind) {
        .identifier => |identifier| switch (identifier.resolution.?) {
            .local => |statement| statement.kind == .variable_declaration,
            .element => |element| ast.isWritableElement(element),
            .parameter, .function, .type, .constant, .typeclass_function, .typeclass_method, .case, .builtin => false,
        },
        .field_access => |access| {
            if (isSliceField(access)) return false;
            return switch (access.value.type.?) {
                .pointer => |pointer| !pointer.constant,
                .number, .boolean, .void, .type, .@"struct", .@"enum", .array, .slice, .optional, .result, .tuple, .function, .variable, .application => {
                    return isWritable(access.value.*);
                },
            };
        },
        .index => |indexing| isElementWritable(indexing.value.*),
        .dereference => |operand| !operand.type.?.pointer.constant,
        else => false,
    };
}

fn isOwnFieldTarget(target: ast.Expression) bool {
    if (target.kind != .field_access) return false;
    const access = target.kind.field_access;
    const container = followPointer(access.value.type orelse return false);
    if (container != .@"struct") return false;
    const field = findField(container.@"struct".fields, access.field) orelse return false;
    return field.own;
}

fn isOwnConstant(expression: ast.Expression) bool {
    if (expression.kind != .identifier) return false;
    const resolution = expression.kind.identifier.resolution orelse return false;
    if (resolution != .local) return false;
    return switch (resolution.local.kind) {
        .constant_declaration => |constant| constant.own,
        else => false,
    };
}

fn isElementWritable(container: ast.Expression) bool {
    return switch (container.type.?) {
        .slice => |slice| !slice.constant,
        .pointer => |pointer| !pointer.constant,
        .number, .boolean, .void, .type, .@"struct", .@"enum", .array, .optional, .result, .tuple, .function, .variable, .application => {
            return isWritable(container);
        },
    };
}

fn isStorage(value: ast.Expression) bool {
    const value_type = value.type.?;
    return value_type == .array or value_type == .tuple or value_type == .@"enum";
}

fn recordTargetUses(
    use: *ast.Use,
    variable: *const ast.Statement,
    statements: []const ast.Statement,
) void {
    for (statements) |statement| {
        if (ast.findBranching(&statement)) |inner| recordTargetUses(use, variable, inner[0..1]);
        switch (statement.kind) {
            .assignment => |assignment| {
                const target = assignment.target;
                if (target.kind == .identifier) continue;
                if (!isNamed(findTargetBase(target), variable)) continue;
                if (isRootedAt(target, variable)) {
                    use.modified = true;
                } else {
                    use.used = true;
                }
            },
            .@"if", .@"while", .@"for", .match => {
                var blocks = ast.iterateBlocks(statement);
                while (blocks.next()) |block| recordTargetUses(use, variable, block);
            },
            .@"defer" => |deferred| recordTargetUses(use, variable, deferred.statement[0..1]),
            .noop,
            .@"return",
            .discard,
            .call,
            .constant_declaration,
            .tuple_declaration,
            .variable_declaration,
            .@"break",
            .@"continue",
            .value,
            => {},
        }
    }
}

fn findTargetBase(target: ast.Expression) ast.Expression {
    return switch (target.kind) {
        .field_access => |access| findTargetBase(access.value.*),
        .index => |indexing| findTargetBase(indexing.value.*),
        else => target,
    };
}

fn isRootedAt(expression: ast.Expression, variable: *const ast.Statement) bool {
    return isNamed(findRoot(expression), variable);
}

fn findRoot(expression: ast.Expression) ast.Expression {
    return switch (expression.kind) {
        .field_access => |access| {
            if (access.value.type.? == .pointer) return expression;
            return findRoot(access.value.*);
        },
        .index => |indexing| if (isStorage(indexing.value.*)) findRoot(indexing.value.*) else expression,
        else => expression,
    };
}

fn isNamed(expression: ast.Expression, variable: *const ast.Statement) bool {
    if (expression.kind != .identifier) return false;
    const resolution = expression.kind.identifier.resolution orelse return false;
    return resolution == .local and resolution.local == variable;
}

fn computeIntegerMaximum(number: types.NumberType) ?u128 {
    return switch (number) {
        .i8 => std.math.maxInt(i8),
        .i16 => std.math.maxInt(i16),
        .i32 => std.math.maxInt(i32),
        .i64, .isize => std.math.maxInt(i64),
        .i128 => std.math.maxInt(i128),
        .u8 => std.math.maxInt(u8),
        .u16 => std.math.maxInt(u16),
        .u32 => std.math.maxInt(u32),
        .u64, .usize => std.math.maxInt(u64),
        .u128 => std.math.maxInt(u128),
        .f16, .f32, .f64, .f128 => null,
    };
}

fn isSigned(number: types.NumberType) bool {
    return switch (number) {
        .i8, .i16, .i32, .i64, .i128, .isize, .f16, .f32, .f64, .f128 => true,
        .u8, .u16, .u32, .u64, .u128, .usize => false,
    };
}

fn fitsFloat(comptime Float: type, text: []const u8) bool {
    const value = std.fmt.parseFloat(Float, text) catch return false;
    return std.math.isFinite(value);
}

test "TypeChecker.check: sets the type of each returned value" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var compiler_directory = std.testing.tmpDir(.{});
    defer compiler_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "fn one() -> u8 = return 255\nfn two() -> f32 = return 2.5\nfn three() -> bool = return true\nfn four() -> i64 = return 1_i64\nfn main() = return" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var name_resolver = @import("name_resolver.zig").NameResolver.init(&arena, std.testing.io, &loader, &type_registry);
    try name_resolver.resolve();
    const program: ast.Program = .{ .modules = loader.modules.items, .types = &type_registry };
    var type_checker = TypeChecker.init(&arena, program);
    try type_checker.check();

    try std.testing.expectEqual(types.Type{ .number = .u8 }, loader.modules.items[0].declarations[0].kind.function_definition.body[0].kind.@"return".?.type);
    try std.testing.expectEqual(types.Type{ .number = .f32 }, loader.modules.items[0].declarations[1].kind.function_definition.body[0].kind.@"return".?.type);
    try std.testing.expectEqual(types.Type.boolean, loader.modules.items[0].declarations[2].kind.function_definition.body[0].kind.@"return".?.type);
    try std.testing.expectEqual(types.Type{ .number = .i64 }, loader.modules.items[0].declarations[3].kind.function_definition.body[0].kind.@"return".?.type);
}

