    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "error OpenError\n    NotFound\n    Denied\nerror CreateError\n    Full\nfn open() -> OpenError!i32 = return 1\nfn create() -> CreateError!i32 = return 2\nerror Short\n    Gone\n    Lost\nfn act() -> Short!void = noop\nfn note() = noop\nfn run() -> !void\n    try match act()\n        case (Gone) noop\n        else (_ as rest) rest\n    try match act()\n        case (Gone) note()\n        else (_ as rest) rest\n    try match act()\n        case (void) noop\n        else (_ as rest) rest" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    const body = loader.modules.items[0].declarations[7].kind.function_definition.body;
    try std.testing.expectEqual(types.Type.void, body[0].kind.call.type.?);
    try std.testing.expect(body[0].kind.call.kind.@"try".kind.branching.kind.match.gives_void);
    try std.testing.expect(body[1].kind.call.kind.@"try".kind.branching.kind.match.gives_void);
    const value_handled = body[2].kind.call.kind.@"try".type.?.result;
    try std.testing.expectEqual(types.Type.void, value_handled.value);
}

