test "completeGroup: keeps a handled error out of a set inferred through a cycle" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "error Failure\n    One\n    Other\nerror Short\n    Two\nfn fallback() -> i32 = 3\nfn first(count: i32) -> !i32\n    if (count == 0) return Failure::One\n    const value = try second(count - 1)\n    return value\nfn second(count: i32) -> !i32\n    if (count == 0) return Short::Two\n    const value = try match first(count - 1)\n        case (One) fallback()\n        else (_ as rest) rest\n    return value\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    const declarations = loader.modules.items[0].declarations;
    const first = ast.extractType(declarations[3].kind.function_definition.signature.return_type).result.error_set;
    const second = ast.extractType(declarations[4].kind.function_definition.signature.return_type).result.error_set;
    try std.testing.expectEqual(3, first.cases.len);
    try std.testing.expectEqual(2, second.cases.len);
    try std.testing.expectEqualStrings("Other", second.cases[0].name);
    try std.testing.expectEqualStrings("Two", second.cases[1].name);
}

test "completeGroup: gives each function of a longer cycle the narrowed sets it reaches" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "error Failure\n    One\n    Two\n    Three\nfn pick() -> Failure!i32 = return 1\nfn fallback() -> i32 = 3\nfn only_two() -> !i32\n    const value = try match pick()\n        case (One, Three) fallback()\n        else (_ as rest) rest\n    return value\nfn only_three() -> !i32\n    const value = try match pick()\n        case (One, Two) fallback()\n        else (_ as rest) rest\n    return value\nfn head(count: i32) -> !i32\n    const first = try middle(count)\n    const second = try only_two()\n    return first + second\nfn middle(count: i32) -> !i32\n    const first = try inner(count)\n    const second = try head(count)\n    return first + second\nfn inner(count: i32) -> !i32\n    const first = try middle(count)\n    const second = try only_three()\n    return first + second\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    const declarations = loader.modules.items[0].declarations;
    try std.testing.expectEqual(2, ast.extractType(declarations[5].kind.function_definition.signature.return_type).result.error_set.cases.len);
    try std.testing.expectEqual(2, ast.extractType(declarations[6].kind.function_definition.signature.return_type).result.error_set.cases.len);
    const inner = ast.extractType(declarations[7].kind.function_definition.signature.return_type).result.error_set;
    try std.testing.expectEqual(2, inner.cases.len);
    try std.testing.expectEqualStrings("Two", inner.cases[0].name);
    try std.testing.expectEqualStrings("Three", inner.cases[1].name);
}

