test "resolveMethodCall: takes the address of the value for a method with a pointer receiver" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "struct Counter\n    count: i32\n\n    fn read(self: Self) -> i32 = return self.count\n    fn increment(self: *Self) = self.count += 1\n    fn peek(self: *const(Self)) -> i32 = return self.count\nfn main()\n    var counter = Counter{ count = 0 }\n    counter.increment()\n    _ = counter.peek()\n    _ = counter.read()" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var name_resolver = @import("name_resolver.zig").NameResolver.init(&arena, std.testing.io, &loader, &type_registry);
    try name_resolver.resolve();
    var type_checker = TypeChecker.init(&arena, .{ .modules = loader.modules.items, .types = &type_registry });
    try type_checker.check();

    const body = loader.modules.items[0].declarations[4].kind.function_definition.body;
    const increment = body[1].kind.call.kind.call;
    const peek = body[2].kind.discard.kind.call;
    const read = body[3].kind.discard.kind.call;
    try std.testing.expectEqual(ast.Resolution{ .function = .{ .module = 0, .declaration = 2 } }, ast.extractResolution(increment.callee));
    try std.testing.expectEqualStrings("counter", increment.arguments[0].value.kind.address_of.kind.identifier.name);
    try std.testing.expectEqualStrings("counter", peek.arguments[0].value.kind.address_of.kind.identifier.name);
    try std.testing.expectEqualStrings("counter", read.arguments[0].value.kind.identifier.name);
}

test "resolveMethodCall: calls the methods of a typeclass with each kind of receiver" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "typeclass Shape(type T)\n\n    fn area(self: T) -> i32\n    fn grow(self: *T)\n    fn measure(self: *const(T)) -> i32\nstruct Square\n    side: i32\ninstance Shape(Square)\n\n    fn area(self: Square) -> i32 = return self.side\n    fn grow(self: *Square) = self.side += 1\n    fn measure(self: *const(Square)) -> i32 = return self.side\nfn main()\n    var square = Square{ side = 1 }\n    square.grow()\n    _ = square.measure()\n    _ = square.area()" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var name_resolver = @import("name_resolver.zig").NameResolver.init(&arena, std.testing.io, &loader, &type_registry);
