    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "enum Shape\n    Point: [i32, bool]\n    Empty\nfn make() -> Shape = ::Point{ 3, true }" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    const call = loader.modules.items[0].declarations[1].kind.function_definition.body[0].kind.@"return".?.kind.call;
    try std.testing.expectEqual(ast.Braces.gathered, call.braces);
    try std.testing.expectEqual(1, call.arguments.len);
    const value = call.arguments[0].value;
    try std.testing.expectEqual(2, value.kind.composite_literal.elements.len);
    try std.testing.expectEqual(types.Type.boolean, value.type.?.tuple.elements[1]);
}

