    try std.testing.expect(analyzer.failure.?.location != null);
}

test "fillTypeArgument: takes a type from the surrounding code in each position" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\ntypeclass To(type T, type U)\n\n    fn to(value: T, type U) -> !U\nstruct Data\n    number: u8\ninstance To(Data, u8)\n\n    fn to(value: Data, type U) -> !U = value.number\ninstance To(Data, u16)\n\n    fn to(value: Data, type U) -> !U\n        _ = value\n        return 300\nfn take(value: u8) -> u8 = value\nfn give_return() -> !u8\n    return Data{ number = 1 }.to(_)\nfn give_tried() -> !u16\n    return try Data{ number = 1 }.to(_)\nfn give_line() -> !u16\n    try Data{ number = 1 }.to(_)\nfn make(type T) -> T = 9\nfn find(type T, value: T, flag: bool) -> ?T = if (flag) value else null\nfn call_argument() -> !u8 = take(try Data{ number = 2 }.to(_))\nconst DECLARED: u8 = Data{ number = 3 }.to(_) catch 0\nconst WIDE: u16 = Data{ number = 3 }.to(_) catch 0\nconst PLAIN: u8 = make(_)\nconst FOUND: u8 = find(_, 4, true) orelse 0\nconst MISSING: u8 = find(_, 4, false) orelse 5\nconst RETURNED = give_return() catch 0\nconst TRIED = give_tried() catch 0\nconst LINE = give_line() catch 0\nconst ARGUMENT = call_argument() catch 0\nconst OPTIONAL: ?u8 = find(_, 6, true)\nconst BOTH: u8 = mn::convert(_, 8u16)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    var checked: usize = 0;
    for (loader.modules.items[0].declarations) |declaration| {
        if (declaration.kind != .constant_declaration) continue;
        const constant = declaration.kind.constant_declaration;
        if (std.mem.eql(u8, constant.name, "DECLARED")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 3 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "WIDE")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 300 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "PLAIN")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 9 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "FOUND")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 4 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "MISSING")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 5 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "RETURNED")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 1 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "TRIED")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 300 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "LINE")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 300 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "ARGUMENT")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 2 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "BOTH")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 8 } }, constant.known.?.*);
            checked += 1;
        }
    }
    try std.testing.expectEqual(10, checked);
}

