    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nstruct Fixed\n    pairs: [32][2]u8\n    bytes: [32]u8\n    numbers: [32]usize\n    used_pairs: usize\n    used_bytes: usize\n    used_numbers: usize\ninstance Allocator(Fixed)\n\n    fn allocate(fixed: *Fixed, type T, count: usize) -> own memory::Error![]T\n        if mn::size(T) == 2\n            const start = fixed.used_pairs\n            fixed.used_pairs += count\n            return mn::cast(*many(T), fixed.pairs[start..fixed.used_pairs].pointer)[0..count]\n        if mn::size(T) == 1\n            const start = fixed.used_bytes\n            fixed.used_bytes += count\n            return mn::cast(*many(T), fixed.bytes[start..fixed.used_bytes].pointer)[0..count]\n        const start = fixed.used_numbers\n        fixed.used_numbers += count\n        return mn::cast(*many(T), fixed.numbers[start..fixed.used_numbers].pointer)[0..count]\n    fn(type T) resize(_: *Fixed, _: []T, _: usize) -> bool = false\n    fn(type T) free(_: *Fixed, own _: []const(T)) = noop\nfn run() -> !usize\n    var fixed: Fixed = undefined\n    fixed.used_pairs = 0\n    fixed.used_bytes = 0\n    fixed.used_numbers = 0\n    var own seen = HashMap([2]u8, u8)::init()\n    defer seen.deinit(own) with &fixed\n    const one_two: [2]u8 = { 1, 2 }\n    const two_one: [2]u8 = { 2, 1 }\n    _ = try seen.put(&one_two, 1) with &fixed\n    _ = try seen.put(&two_one, 2) with &fixed\n    const own repeated = try seen.put(&one_two, 3) with &fixed\n    const lookup_381: [2]u8 = { 2, 1 }\n    const own removed = seen.remove(&lookup_381)\n    var total: usize = 0\n    const lookup_402: [2]u8 = { 1, 2 }\n    const lookup_403: [2]u8 = { 2, 1 }\n    if (repeated != null and removed != null and seen.contains(&lookup_402) and !seen.contains(&lookup_403)) total = seen.length()\n    return total\nconst RESULT = run() catch 0\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    var found: ?Value = null;
    for (loader.modules.items[0].declarations) |declaration| {
        if (declaration.kind == .constant_declaration and std.mem.eql(u8, declaration.kind.constant_declaration.name, "RESULT")) found = declaration.kind.constant_declaration.known.?.*;
    }
    try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 1 } }, found.?);
}

test "integration: copies elements at compile time through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("loader.zig").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nstruct Point\n    x: i32\n    y: u8\nfn distinct() -> [3]u32\n    const source: [3]u32 = { 7, 8, 9 }\n    var target: [3]u32 = undefined\n    memory::copy(target[..], source[..])\n    return target\nfn forward() -> [8]u8\n    var numbers: [8]u8 = { 1, 2, 3, 4, 5, 6, 7, 8 }\n    memory::copy(numbers[0..5], numbers[2..7])\n    return numbers\nfn backward() -> [8]u8\n    var numbers: [8]u8 = { 1, 2, 3, 4, 5, 6, 7, 8 }\n    memory::copy(numbers[2..7], numbers[0..5])\n    return numbers\nfn same() -> [3]u8\n    var numbers: [3]u8 = { 1, 2, 3 }\n    memory::copy(numbers[..], numbers[..])\n    return numbers\nfn structs() -> i32\n    const source: [1]Point = { Point{ x = 5, y = 6 } }\n    var target: [1]Point = undefined\n    memory::copy(target[..], source[..])\n    if (target[0].y != 6) return 0\n    return target[0].x + 6\nfn empty() -> u8\n    var numbers: [2]u8 = { 1, 2 }\n    memory::copy(numbers[1..1], numbers[0..0])\n    return numbers[1]\nconst DISTINCT = distinct()\nconst FORWARD = forward()\nconst BACKWARD = backward()\nconst SAME = same()\nconst STRUCTS = structs()\nconst EMPTY = empty()\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("analyzer.zig").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    _ = try analyzer.analyze();

    var checked: usize = 0;
    for (loader.modules.items[0].declarations) |declaration| {
        if (declaration.kind != .constant_declaration) continue;
        const constant = declaration.kind.constant_declaration;
        if (std.mem.eql(u8, constant.name, "DISTINCT")) {
            for ([_]u128{ 7, 8, 9 }, constant.known.?.aggregate) |expected, value| try std.testing.expectEqual(Value{ .integer = .{ .unsigned = expected } }, value);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "FORWARD")) {
            for ([_]u128{ 3, 4, 5, 6, 7, 6, 7, 8 }, constant.known.?.aggregate) |expected, value| try std.testing.expectEqual(Value{ .integer = .{ .unsigned = expected } }, value);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "BACKWARD")) {
            for ([_]u128{ 1, 2, 1, 2, 3, 4, 5, 8 }, constant.known.?.aggregate) |expected, value| try std.testing.expectEqual(Value{ .integer = .{ .unsigned = expected } }, value);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "SAME")) {
            for ([_]u128{ 1, 2, 3 }, constant.known.?.aggregate) |expected, value| try std.testing.expectEqual(Value{ .integer = .{ .unsigned = expected } }, value);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "STRUCTS")) {
            try std.testing.expectEqual(Value{ .integer = .{ .signed = 11 } }, constant.known.?.*);
            checked += 1;
        }
        if (std.mem.eql(u8, constant.name, "EMPTY")) {
            try std.testing.expectEqual(Value{ .integer = .{ .unsigned = 2 } }, constant.known.?.*);
            checked += 1;
        }
    }
    try std.testing.expectEqual(6, checked);
}

